  (id,subject_key,year,academic_year,week,session,duration_minutes,sp_code,printed_pages,content_sha256,reviewed_blocks_sha256,approval_manifest_sha256,approval_status,active,lesson,reviewed_blocks,limits)
values
  ('PJ1-2026B-2S-W31-S2','pj',1,2026,31,2,30,'1.10.1',array[42]::int[],'a48fd970cb40596c7238c535f5475570de6cab1e9ea2d61d6ab91548e6fee913','7595b3b01cabf7c74b37a5727e1adb8b2a033921b0a5658580f6c6f91766d52b','715d2dd93e616381f7de4fb5e317e008bae7007088b12831c3d9d17a2be5d6d7','ACCEPTED_FROM_DOWNLOADED_CATATAN',false,'{"id": "PJ1-2026B-2S-W31-S2", "subject": "Pendidikan Jasmani", "year": 1, "week": 31, "session": 2, "revision": "PJ1-30MIN-REVIEW-R1", "date": "", "teaching_time": "", "minutes": 30, "sessions_per_week": 2, "weekly_minutes": 60, "title": "Santai Petang", "source_title": "Santai Petang", "unit": "Unit 6: Mari Bersantai", "source_row_id": "PJ1-RPT2026-T10-R5", "source_row_literal": ["31\n\nKump A: 06.09.2026-10.09.2026\n\nKump B:\n07.09.2026-11.09.2026", "6: MARI BERSANTAI\nSANTAI PETANG", "1.10 Melakukan aktiviti rekreasi dan kesenggangan\n2.9 Mengaplikasi strategi dan idea kreatif dalam aktiviti rekreasi dan   kesenggangan\n5.4 Membentuk kumpulan dan bekerjasama dalam kumpulan semasa melakukan aktiviti.", "1.10.1 Menggunakan kemahiran lokomotor dan manipulasi semasa melakukan permainan tradisional seperti Datuk Harimau dan Congkak.\n\n2.9.1 Mengenal pasti cara bermain permainan tradisional.\n\n5.4.1 Mempamerkan aktiviti secara berpasangan. \n5.4.2 Mempamerkan rasa seronok semasa melakukan aktiviti dalam kumpulan.", "Pemerhatian /\nPentaksiran \n\nPERMAINAN:\nCongkak\nDatuk harimau\n\nEMK: \nKreativiti & Inovasi\nBT m/s 41-42"], "rpt_original_page_literal": "41-42", "source_pages": [42], "source_pdf_pages": [50], "rpt_book_pages": "42", "main_standard_key": "1.10.1", "sk_code": "1.10", "sk_text": "Melakukan aktiviti rekreasi dan kesenggangan.", "sp_code": "1.10.1", "sp_text": "Menggunakan kemahiran lokomotor dan manipulasi semasa melakukan permainan tradisional seperti Datuk Harimau dan Congkak.", "complementary_standards": [{"standard_key": "2.9.1", "sp_code": "2.9.1", "sp_text": "Mengenal pasti cara bermain permainan tradisional.", "sk_code": "2.9", "sk_text": "Mengaplikasi strategi dan idea kreatif dalam aktiviti rekreasi dan kesenggangan.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.4.1", "sp_code": "5.4.1", "sp_text": "Mempamerkan aktiviti secara berpasangan.", "sk_code": "5.4", "sk_text": "Membentuk kumpulan dan bekerjasama dalam kumpulan semasa melakukan aktiviti.", "domain": "afektif", "source_label": ""}, {"standard_key": "5.4.2", "sp_code": "5.4.2", "sp_text": "Mempamerkan rasa seronok semasa melakukan aktiviti dalam kumpulan.", "sk_code": "5.4", "sk_text": "Membentuk kumpulan dan bekerjasama dalam kumpulan semasa melakukan aktiviti.", "domain": "afektif", "source_label": ""}], "source_task": "Congkak bergilir dan gerak selamat Datuk Harimau", "authoring_focus": "Congkak bergilir dan gerak selamat Datuk Harimau", "source_hold": "Teks RPT, DSKP dan buku dibaca. Semakan imej guling BT35 dan kod DSKP hlm70 terhalang ralat402; OCR dan teks salinan menyokong kod berulang, bukan kelulusan visual. Guru perlu menilai postur, alat dan kesediaan setiap murid.", "practical_required": true, "warmup_required": true, "cooldown_required": true, "facility_replacement": false, "facility_replacement_note": "", "source_subset_focus": false, "source_subset_note": "", "adaptation_note": "BT42 menamakan Datuk Harimau dan Congkak tanpa peraturan lengkap dalam teks. Kedua-dua permainan digunakan setiap sesi untuk lokomotor dan manipulasi. Versi mini Datuk Harimau tanpa sentuhan dan congkak tiga buah setiap rumah anak ialah latihan guru, bukan peraturan pertandingan penuh. Papan congkak dan buah sebenar yang selamat digunakan, bukan permainan kad.", "privacy_adaptation": false, "privacy_note": "", "held_standards": [], "source_code_conflict": false, "source_code_note": "", "unperformed_literal_elements": [], "source_mapping_review": "20 RPH, dua sesi30minit seminggu dibenarkan guru. S1/S2 ialah cadangan pecahan RPT mingguan, bukan nombor sesi yang tercetak dalam RPT.", "routine_book_pages": [46, 47], "active": false, "production_write_performed": false, "presentation_review": "PENDING_TEACHER_REVIEW", "safety": ["Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula.", "Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan.", "Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan.", "Datuk Harimau ialah adaptasi guru tanpa sentuhan dan tanpa kejar-mengejar. Guru kekal di belakang kon; tiada menangkap, menolak, menyekat, menyingkir atau memaksa murid berlari.", "Selepas Waktu makan, murid berpusing dengan tenang lalu berjalan pantas dalam lorong sendiri. Murid berhenti stabil di rumah selamat. Jangan mengundur laju atau memotong lorong.", "Hanya satu kumpulan kecil aktif. Kumpulan menunggu berada di luar laluan dan tetap dalam pandangan guru. Hentikan pusingan jika laluan terganggu.", "Buah congkak tidak dimasukkan ke mulut, hidung atau telinga dan tidak dibaling. Tangan berada rendah di atas papan. Buah yang jatuh dikutip selepas semua tangan berhenti.", "Guru memantau risiko tercekik. Jika buah tidak sesuai atau murid masih memasukkan benda ke mulut, tangguhkan amali Congkak murid berkenaan sehingga alat dan pengawasan selamat tersedia; catat bahagian belum dilaksanakan."], "weather_plan": "Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat.", "reflection": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________.", "activity_name": "Congkak bertukar tempat mula dan Datuk Harimau terkawal", "objective": "Murid dapat mengawal langkah Datuk Harimau dan menabur buah Congkak dari rumah mula yang berbeza sambil menjaga giliran.", "success_criteria": ["Berhenti dan pulang mengikut arahan Datuk Harimau serta menabur Congkak dari rumah mula berbeza dengan terkawal.", "Menamatkan giliran Congkak selepas genggaman habis dan menunggu arahan sebelum bergerak dalam Datuk Harimau.", "Menyebut cara menjaga giliran dalam Datuk Harimau dan Congkak."], "prior_knowledge": "Guru menyemak semula rumah selamat dan taburan satu demi satu. Murid yang belum hadir sesi lalu diberi tunjuk cara awal, bukan dianggap sudah menguasai.", "equipment": [{"item": "Kon penanda", "quantity": "15 kon: 12 bagi enam lorong, satu untuk guru dan dua untuk tempat menunggu.", "use": "Menandakan mula, hujung dan ruang menunggu dari sisi laluan; tiada kon di tempat kaki melangkah."}, {"item": "Papan congkak sebenar", "quantity": "Satu papan bagi setiap pasangan; tujuh rumah anak pada setiap sisi dan satu rumah ibu pada setiap hujung.", "use": "Setiap murid menggenggam dan menabur buah pada gilirannya sendiri."}, {"item": "Buah congkak licin bukan kaca dan bekas simpanan", "quantity": "42 buah bagi setiap papan, tiga bagi setiap rumah anak; satu bekas bagi setiap papan.", "use": "Buah sesuai untuk umur murid, boleh digenggam dan tidak tajam; rumah ibu kosong ketika mula."}, {"item": "Air minuman sendiri dan jam guru", "quantity": "Satu botol bagi setiap murid dan satu jam guru.", "use": "Rehat, minum dan mengurus pertukaran kumpulan."}], "preparation": ["Guru menyusun enam lorong selari di permukaan rata yang kering. Dua kon diletakkan di sisi setiap lorong untuk menunjukkan rumah selamat di titik mula dan had hujung.", "Jarak setiap lorong cukup untuk tiga langkah kecil dengan ruang berhenti. Jarak antara murid membolehkan tangan dibuka tanpa menyentuh rakan. Kurangkan bilangan lorong aktif jika ruang sempit.", "Guru berdiri tetap di belakang konnya, jauh di hadapan had hujung murid. Dua kon lain menandakan tempat menunggu di luar laluan dan dalam pandangan guru.", "Papan congkak diletakkan stabil di kawasan teduh di luar lorong. Isi tiga buah pada setiap rumah anak, jumlah 42 buah bagi satu papan. Kosongkan kedua-dua rumah ibu.", "Guru mengira dan memeriksa buah sebelum serta selepas aktiviti. Buah yang terlalu kecil, retak atau tidak sesuai tidak digunakan."], "organisation": ["Kekalkan pasangan. Sehingga tiga pasangan, paling banyak enam murid, bermain Datuk Harimau serentak dalam lorong sendiri. Setiap pasangan berada dalam dua lorong bersebelahan, bukan berpegangan tangan.", "Kumpulan lain duduk tenang di tempat menunggu dan melihat. Guru menamatkan pusingan dahulu sebelum memanggil kumpulan seterusnya. Semua kumpulan mendapat pusingan sebelum sebarang ulangan.", "Semasa Congkak, semua pasangan bermain pada papan masing-masing. Dua atau tiga pasangan duduk berdekatan sebagai kumpulan kecil tanpa berkongsi giliran pemain.", "Guru menetapkan siapa bermula pada setiap papan. Pasangan berselang giliran satu genggaman; setiap murid melakukan sendiri, bukan seorang wakil pasangan.", "Murid boleh berehat atau minum selepas memberitahu guru. Guru merekod bahagian yang belum dicuba dan mengatur susulan, bukan mengisi pencapaian bagi murid yang hanya memerhati."], "movement_cues": ["Datuk Harimau: dengar jawapan satu hingga tiga dahulu. Ambil langkah kecil mengikut bilangan itu dan berhenti. Jangan bergerak hanya kerana rakan bergerak.", "Apabila Waktu makan disebut, pusing dengan tenang dan berjalan pantas pulang dalam lorong sendiri. Perlahankan langkah akhir dan berhenti di rumah selamat.", "Congkak: pilih rumah anak berisi pada sisi sendiri yang berbeza daripada rumah tengah sesi lalu. Mulakan dengan rumah kedua dari kiri, dekat rumah ibu sendiri; guru mengesahkan arahnya.", "Genggam semua isi rumah mula dengan tapak tangan menadah. Tabur bermula di rumah seterusnya dari kanan ke kiri, satu buah setiap rumah. Masukkan satu ke rumah ibu sendiri jika dilalui, teruskan di sisi lawan dan langkau rumah ibu lawan.", "Buah terakhir menamatkan satu giliran mini walaupun jatuh di rumah berisi atau rumah ibu sendiri. Lepaskan tangan dan beri giliran pasangan; tiada kutip semula, tangkap buah atau giliran tambahan."], "timing_note": "Persediaan dua minit, pemanasan empat minit, tunjuk cara empat minit, Congkak sembilan minit, Datuk Harimau tujuh minit dan penyejukan empat minit. Pertukaran, rehat serta minum berada dalam masa fasa. Dahulukan giliran pertama semua murid sebelum ulangan.", "values": "Kerjasama, disiplin dan menjaga keselamatan rakan.", "classroom_example": {"teacher_says": "Pilih rumah mula yang lain. Selepas buah terakhir, beri giliran. Dalam Datuk Harimau, tunggu suara saya sebelum bergerak.", "pupils_do": "Setiap murid menabur Congkak sendiri, kemudian bergerak dan berhenti dalam pusingan Datuk Harimau.", "teacher_checks": "Guru memeriksa rumah mula, arah, pertukaran giliran dan hentian setiap murid."}, "bbm": ["Kon penanda — 15 kon: 12 bagi enam lorong, satu untuk guru dan dua untuk tempat menunggu.", "Papan congkak sebenar — Satu papan bagi setiap pasangan; tujuh rumah anak pada setiap sisi dan satu rumah ibu pada setiap hujung.", "Buah congkak licin bukan kaca dan bekas simpanan — 42 buah bagi setiap papan, tiga bagi setiap rumah anak; satu bekas bagi setiap papan.", "Air minuman sendiri dan jam guru — Satu botol bagi setiap murid dan satu jam guru.", "Buku teks dan senarai semak pemerhatian guru."], "pak21": "Pasangan memerhati taburan Congkak secara bergilir dan menyebut Giliran awak selepas genggaman habis. Dalam Datuk Harimau, pasangan bertanya waktu bersama tetapi bergerak di lorong berasingan. Rakan memberi teguran pendek dengan sopan; setiap murid tetap melaksanakan kedua-duanya sendiri.", "source_note": "RPT PJ1-RPT2026-T10-R5, DSKP PDF72–74 dan BT42/PDF50 dibaca sebagai sumber teks. BT42 tidak membekalkan peraturan penuh. Peraturan Congkak DVS halaman dua menerangkan arah, rumah ibu sendiri dan sambungan giliran permainan sebenar. Sesi ini sengaja menggunakan adaptasi guru: tiga buah setiap rumah anak, satu genggaman kemudian bertukar, tanpa sambung isi rumah terakhir, tangkap buah atau giliran tambahan. Datuk Harimau tanpa sentuhan dan tanpa kejar-mengejar juga adaptasi guru. Perubahan rumah mula ialah latihan kawalan, bukan pertandingan penuh; tiada pengesahan visual didakwa.", "assessment_scope": "Catat lakuan sebenar individu dalam kedua-dua permainan. Langkah pulang tanpa kejar-mengejar bukan pentaksiran kemahiran mengelak. Menguasai giliran Congkak mini tidak membuktikan penguasaan semua peraturan permainan atau menetapkan TP secara automatik.", "phases": [{"name": "Persediaan murid dan alatan", "minutes": 2, "teacher": ["Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan.", "Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."], "pupils": ["Murid memberitahu guru jika tidak sihat.", "Murid mengambil tempat yang ditetapkan dan mendengar arahan."], "check": "Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan.", "resources": ["Kon penanda", "Papan congkak sebenar", "Buah congkak licin bukan kaca dan bekas simpanan", "Air minuman sendiri dan jam guru"]}, {"name": "Pemanasan badan", "minutes": 4, "teacher": ["Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit.", "Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."], "pupils": ["Murid bergerak dalam ruang sendiri tanpa bersentuh.", "Murid bernafas seperti biasa dan berehat jika perlu."], "check": "Murid bersedia untuk aktiviti tanpa terlalu penat.", "resources": ["Ruang lapang", "Kon penanda"]}, {"name": "Ulang arah dan tunjuk pertukaran giliran", "minutes": 4, "teacher": ["Guru menunjukkan rumah mula Congkak yang berbeza daripada rumah tengah: rumah kedua dari kiri pada sisi pemain. Guru menabur tiga buah, memasukkan buah ke rumah ibu sendiri apabila dilalui, lalu berhenti selepas buah terakhir.", "Guru menegaskan peraturan mini: tamat genggaman bermaksud tamat giliran walaupun rumah terakhir berisi atau rumah ibu sendiri. Guru menunjukkan pemain seterusnya menunggu tangan pemain pertama dilepaskan.", "Guru mengingatkan semula rumah selamat Datuk Harimau. Guru menunjukkan melangkah selepas bilangan disebut, berhenti, kemudian berpusing dan pulang selepas Waktu makan; guru harimau tidak bergerak mengejar."], "pupils": ["Murid menunjuk rumah Congkak berisi yang hendak digunakan dan rumah ibu sendiri. Pasangan menyebut siapa bermula hari ini.", "Murid menyebut Giliran awak apabila genggaman contoh habis, bukan mengambil isi rumah terakhir.", "Murid menunjuk lorong Datuk Harimau sendiri dan meniru cara berhenti serta berpusing perlahan di tempat."], "check": "Murid membezakan rumah mula dengan rumah seterusnya dan tahu bila boleh bergerak atau mengambil giliran.", "resources": ["Papan congkak sebenar", "42 buah congkak", "Kon penanda"]}, {"name": "Congkak: mula berbeza, giliran terjaga", "minutes": 9, "teacher": ["Guru memeriksa tiga buah pada setiap rumah anak, 42 buah bagi papan dan rumah ibu kosong. Murid yang bermula kedua pada sesi lalu diberi giliran pertama hari ini; jika tiada rekod, guru menetapkan pemain pertama.", "Guru meminta setiap pemain menggunakan rumah kedua dari kiri pada sisi sendiri, bukan rumah tengah. Jika rumah itu kosong semasa giliran tiba, pilih rumah anak berisi lain pada sisi sendiri; jangan menggenggam ruang kosong atau mengambil buah rakan.", "Guru memerhati genggaman menadah dan taburan satu demi satu bermula di rumah seterusnya, dari kanan ke kiri. Masukkan buah ke rumah ibu sendiri jika dilalui, sambung di sisi lawan dan langkau rumah ibu lawan.", "Selepas buah terakhir dilepaskan, pemain meletakkan tangan di sisi papan dan pasangan bermain. Hadnya satu genggaman: rumah akhir berisi, kosong atau rumah ibu sendiri semuanya menamatkan giliran mini. Tiada mengambil semula isi rumah akhir, menangkap buah atau giliran tambahan.", "Selepas kedua-dua pemain selesai, pasangan menyusun semula tiga buah setiap rumah anak dan mengosongkan rumah ibu. Pemain kedua tadi bermula pusingan seterusnya; jika masa mengizinkan, pilih rumah berisi lain daripada pusingan tadi.", "Guru menyemak kedua-dua murid dan bertanya tentang arah serta giliran. Pada akhir fasa, jangan mula giliran baharu; habiskan genggaman semasa dengan tenang, simpan buah dan berjalan ke ruang Datuk Harimau. Rehat dan minum dibenarkan ketika pertukaran."], "pupils": ["Murid menunjuk rumah Congkak yang dipilih sebelum mengambil semua isinya. Pasangan menunggu tangan pemain bersedia.", "Murid menggenggam dan menabur satu demi satu mengikut arah. Murid memasukkan buah ke rumah ibu sendiri jika dilalui dan meneruskan taburan tanpa melangkau rumah anak.", "Selepas buah terakhir, murid menyebut Giliran awak dan meletakkan tangan di sisi. Pasangan melakukan taburannya sendiri, bukan hanya mengira untuk rakan.", "Kedua-dua murid menyusun semula papan selepas giliran masing-masing. Murid boleh memilih rumah berisi lain pada pusingan seterusnya dan menerangkan bila gilirannya tamat.", "Murid mengemas apabila diarahkan. Murid menyatakan respons sebenar tentang bermain dalam kumpulan kecil dan tidak dipaksa meneruskan jika tidak selesa."], "check": "Setiap murid mempunyai bukti taburan dari rumah mula berbeza, arah dan pertukaran giliran; guru merekod bantuan serta giliran belum selesai.", "resources": ["Papan congkak bagi setiap pasangan", "42 buah bagi setiap papan", "Bekas simpanan", "Air minuman"]}, {"name": "Datuk Harimau: dengar, berhenti dan pulang", "minutes": 7, "teacher": ["Guru memanggil sehingga enam murid, berpasangan dalam lorong bersebelahan. Guru kekal sebagai harimau di belakang kon; yang lain duduk tenang dalam pandangan guru.", "Guru menunggu soalan Pukul berapa, Datuk Harimau? lalu menjawab antara satu hingga tiga. Hanya satu soalan bagi satu pusingan supaya murid tidak menghampiri guru. Guru menunggu murid berhenti sebelum menyebut Waktu makan.", "Guru memerhatikan murid berpusing dan berjalan pantas pulang dalam lorong masing-masing. Guru menegaskan tiada sentuhan, kejar-mengejar, perlumbaan atau penyingkiran.", "Selepas semua berhenti stabil, guru menyebut Berhenti dan mengarahkan keluar ke sisi kosong. Kumpulan baharu masuk hanya selepas lorong kosong. Semua kumpulan mesti mendapat giliran sebelum pusingan ulangan.", "Guru merekod kawalan setiap murid dan bertanya bila perlu bergerak atau berhenti serta perasaannya bermain bersama rakan. Jika ada masa selepas semua mendapat giliran, gunakan bilangan langkah yang berbeza dalam had yang sama."], "pupils": ["Pasangan bertanya waktu bersama. Murid mendengar jawapan dahulu, mengambil bilangan langkah kecil yang disebut dan berhenti sebelum had hujung.", "Selepas Waktu makan, murid berpusing dengan tenang lalu berjalan pantas ke rumah selamat sendiri. Murid memperlahankan langkah akhir dan berhenti tanpa bersentuh.", "Murid menunggu arahan keluar. Kumpulan menunggu memberi ruang dan tidak masuk awal atau mengganggu lorong.", "Setiap murid menjelaskan bila boleh bergerak dan berkongsi perasaan apabila ditanya; murid boleh meminta rehat."], "check": "Bandingkan kawalan mula dan berhenti murid dengan percubaannya sendiri, bukan kelajuan rakan. Lengkapkan bukti Datuk Harimau bagi murid yang sama yang bermain Congkak.", "resources": ["15 kon penanda", "Jam guru", "Air minuman"]}, {"name": "Penyejukan badan dan penutup", "minutes": 4, "teacher": ["Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit.", "Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."], "pupils": ["Murid meregang mengikut keselesaan tanpa sentapan.", "Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."], "check": "Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli.", "resources": ["Air minuman", "Ruang rehat"]}], "differentiation": {"support": {"label": "Peneroka", "support_description": "Guru membimbing satu langkah pada satu masa.", "task": "Memilih rumah mula Congkak dengan bantuan dan menunggu arahan Datuk Harimau sebelum melangkah.", "materials": ["Papan congkak pasangan", "42 buah bagi satu papan", "Lorong berkon yang sama"], "teacher": ["Guru menunjuk rumah Congkak kedua dari kiri dan membimbing arah dengan jari dari luar papan. Guru menyebut Tamat, giliran pasangan selepas buah terakhir.", "Guru memberi arahan Datuk Harimau dengan jeda yang jelas. Guru mengingatkan pusing dahulu dan berjalan pulang tanpa bergerak mengejar."], "pupil_steps": ["Murid memilih rumah mula Congkak yang ditunjukkan, berbeza daripada rumah tengah, dan menggenggam semua isinya.", "Murid menabur satu demi satu, memasukkan buah ke rumah ibu sendiri jika dilalui dan memberi giliran selepas buah terakhir dengan bantuan lisan.", "Murid bertanya waktu Datuk Harimau bersama pasangan, mendengar bilangan dan mengambil langkah kecil dalam lorong sendiri.", "Murid berpusing dan pulang selepas Waktu makan. Murid menyebut bila gilirannya tamat dalam Congkak dan bila pulang dalam Datuk Harimau."], "product": "Taburan Congkak dari rumah mula lain serta langkah dan kepulangan Datuk Harimau oleh murid sendiri dengan bantuan dicatat.", "criterion": "Murid menabur satu genggaman Congkak sebelum memberi giliran dan menunggu arahan Datuk Harimau sebelum melangkah atau pulang.", "next_step": "Kekalkan bantuan menunjuk rumah Congkak dan arahan Datuk Harimau yang berjarak. Semak semula kedua-dua lakuan yang belum jelas tanpa meminta rakan melakukannya.", "example": {"teacher": "Siapa bermain selepas buah habis? Bila kamu pulang ke rumah selamat?", "pupil": "Pasangan saya bermain. Saya pulang apabila dengar Waktu makan."}}, "core": {"label": "Pembina", "support_description": "Murid berlatih berpasangan dan melakukan sendiri.", "task": "Menjaga arah dan giliran Congkak serta mula dan berhenti tepat pada arahan Datuk Harimau.", "materials": ["Satu papan congkak bagi pasangan", "42 buah bagi satu papan", "Dua lorong berkon bersebelahan"], "teacher": ["Guru menyemak rumah mula Congkak berbeza dan membetulkan arah sebelum murid melepaskan buah seterusnya.", "Guru memeriksa pasangan Datuk Harimau menggunakan lorong sendiri dan memperlahankan langkah sebelum berhenti di rumah selamat."], "pupil_steps": ["Murid memilih rumah mula Congkak berisi yang berbeza daripada rumah tengah dan menabur dari kanan ke kiri.", "Murid berhenti selepas genggaman habis, memberi giliran pasangan dan menyusun semula papan selepas kedua-duanya selesai.", "Murid bertanya waktu Datuk Harimau bersama pasangan, mendengar bilangan dan berhenti selepas langkah yang disebut.", "Murid pulang selepas Waktu makan dan berhenti stabil. Setiap murid menyebut cara menjaga giliran dalam Datuk Harimau dan Congkak kepada pasangan."], "product": "Giliran Congkak dari rumah mula berbeza dan pusingan Datuk Harimau dengan mula serta hentian terkawal bagi setiap murid.", "criterion": "Setiap murid menamatkan satu genggaman Congkak sebelum pasangan bermain dan mengikut arahan mula serta pulang Datuk Harimau.", "next_step": "Ulang giliran Congkak atau pusingan Datuk Harimau yang memerlukan pembetulan sahaja, dalam masa tersedia selepas semua murid mendapat giliran.", "example": {"teacher": "Apakah yang kamu tunggu sebelum mengambil buah dan sebelum pulang?", "pupil": "Saya tunggu pasangan habis menabur. Saya tunggu Waktu makan sebelum pulang."}}, "challenge": {"label": "Pencabar", "support_description": "Murid memperkemas satu perkara dalam kemahiran yang sama.", "task": "Melaras arah Congkak dari tempat mula baharu dan memperkemas hentian Datuk Harimau tanpa menambah kepantasan.", "materials": ["Papan congkak pasangan", "42 buah bagi satu papan", "Lorong berkon yang sama"], "teacher": ["Guru meminta murid menunjuk rumah Congkak seterusnya sebelum menabur jika ragu-ragu. Guru membenarkan bantuan arah sepanjang giliran.", "Guru menumpukan pada langkah akhir Datuk Harimau yang semakin perlahan, bukan jarak atau bilangan langkah tambahan."], "pupil_steps": ["Murid memilih rumah mula Congkak yang berbeza dan menunjuk arah rumah seterusnya sebelum menggenggam buah.", "Murid menabur rendah di atas papan dan menyerahkan giliran selepas buah terakhir, walaupun jatuh di rumah ibu sendiri. Murid memberitahu pasangan sebab berhenti dalam versi mini.", "Murid mendengar jawapan Datuk Harimau, melangkah mengikut bilangan dan berhenti tanpa mengikut gerakan awal rakan.", "Murid pulang selepas Waktu makan dengan langkah akhir perlahan. Murid berkongsi satu pembaikan kawalan Datuk Harimau dan Congkak."], "product": "Taburan Congkak yang kekal teratur dari mula baharu serta hentian pulang Datuk Harimau yang stabil; bukti setiap murid.", "criterion": "Murid menjaga arah dan tamat giliran Congkak walaupun rumah mula berubah serta memperlahankan langkah sebelum berhenti dalam Datuk Harimau.", "next_step": "Jika masih tersalah arah Congkak atau pulang terlalu awal dalam Datuk Harimau, kekalkan petunjuk guru. Kemajuan tidak diukur dengan kelajuan atau kemenangan.", "example": {"teacher": "Buah terakhir masuk rumah ibu sendiri. Apa tindakan hari ini? Bagaimana kamu berhenti ketika pulang?", "pupil": "Saya beri giliran kerana latihan satu genggaman. Saya perlahankan langkah akhir."}}}, "differentiation_delivery": {"common_task": "Murid dapat mengawal langkah Datuk Harimau dan menabur buah Congkak dari rumah mula yang berbeza sambil menjaga giliran.", "placement": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan.", "teacher_rounds": ["Guru menyemak kedua-dua pemain Congkak, bukan pemerhati sahaja, sambil bergerak dari papan ke papan. Catat bantuan rumah mula dan arah.", "Semasa Datuk Harimau, guru kekal di belakang kon dan memerhatikan setiap murid dalam kumpulan kecil. Catat mula serta hentian selepas pusingan berhenti."], "individual_check": "Berhenti dan pulang mengikut arahan Datuk Harimau serta menabur Congkak dari rumah mula berbeza dengan terkawal.", "flexible_help": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, "pbd": {"method": "Pemerhatian individu ketika menabur Congkak dari rumah mula berbeza dan bergerak dalam pusingan Datuk Harimau.", "evidence": "Catatan nama yang sama bagi genggaman, arah dan pelepasan Congkak serta masa mula, pusingan dan hentian pulang Datuk Harimau.", "criterion": "Murid menabur Congkak satu demi satu dari rumah mula berbeza dan melakukan langkah serta kepulangan Datuk Harimau dengan terkawal; kedua-dua amali diperlukan.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama murid: ____.", "Congkak — rumah mula, genggaman dan taburan: ____; bantuan: ____.", "Datuk Harimau — langkah, pusingan dan hentian: ____; bantuan: ____.", "Bahagian belum dicuba atau belum diperhatikan: ____; susulan: ____."]}, "pbd_complementary": {"2.9.1": {"method": "Soal jawab seorang demi seorang selepas taburan Congkak dan pusingan Datuk Harimau.", "evidence": "Jawapan murid tentang buah terakhir menamatkan giliran Congkak mini serta arahan bilangan dan Waktu makan dalam Datuk Harimau.", "criterion": "Murid menerangkan secara ringkas bila gilirannya tamat dalam Congkak mini dan bila perlu bergerak atau pulang dalam Datuk Harimau.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama murid: ____.", "Congkak — penjelasan tamat giliran mini: ____.", "Datuk Harimau — penjelasan arahan bergerak atau pulang: ____.", "Petunjuk guru yang diperlukan: ____."]}, "5.4.1": {"method": "Pemerhatian perbuatan setiap murid dalam pasangan Congkak dan pasangan Datuk Harimau.", "evidence": "Murid memberi serta mengambil giliran Congkak sendiri dan bertanya waktu serta menjaga ruang pasangan Datuk Harimau tanpa mewakilkan lakuan.", "criterion": "Setiap murid melakukan peranannya sendiri bersama pasangan dalam Congkak dan Datuk Harimau serta membenarkan pasangan mendapat giliran.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama murid: ____; pasangan: ____.", "Congkak — mengambil dan memberi giliran sendiri: ____.", "Datuk Harimau — turut bergerak dan menjaga ruang pasangan: ____.", "Bantuan kerjasama yang diperlukan: ____."]}, "5.4.2": {"method": "Pemerhatian dan pertanyaan individu tentang pengalaman berkumpulan dalam Congkak serta Datuk Harimau.", "evidence": "Kata-kata atau tingkah laku sebenar setiap murid tentang keseronokan giliran Congkak dan bermain Datuk Harimau bersama rakan; respons kedua-dua aktiviti direkod.", "criterion": "Murid menunjukkan atau menyatakan rasa seronok dalam kumpulan Congkak dan Datuk Harimau. Jika murid diam atau tidak selesa, catat keadaan sebenar dan susuli tanpa paksaan.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama murid: ____.", "Congkak — respons atau tingkah laku sebenar: ____.", "Datuk Harimau — respons atau tingkah laku sebenar: ____.", "Keselesaan, rehat atau susulan: ____."]}}, "intervention": "Murid yang masih keliru memilih rumah Congkak berisi diberi petunjuk langsung dan menabur sendiri. Murid yang pulang awal dalam Datuk Harimau diberi latihan dengar dan berhenti sebelum pusingan berikutnya. Lengkapkan bukti kedua-dua aktiviti pada susulan jika belum dilihat; jangan menukar minit sesi atau menganggap percubaan selesai.", "book_pages_text": "42", "sp_focus": "", "sp_display": "1.10.1", "complementary": [{"standard_key": "2.9.1", "sp_code": "2.9.1", "sp_text": "Mengenal pasti cara bermain permainan tradisional.", "sk_code": "2.9", "sk_text": "Mengaplikasi strategi dan idea kreatif dalam aktiviti rekreasi dan kesenggangan.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.4.1", "sp_code": "5.4.1", "sp_text": "Mempamerkan aktiviti secara berpasangan.", "sk_code": "5.4", "sk_text": "Membentuk kumpulan dan bekerjasama dalam kumpulan semasa melakukan aktiviti.", "domain": "afektif", "source_label": ""}, {"standard_key": "5.4.2", "sp_code": "5.4.2", "sp_text": "Mempamerkan rasa seronok semasa melakukan aktiviti dalam kumpulan.", "sk_code": "5.4", "sk_text": "Membentuk kumpulan dan bekerjasama dalam kumpulan semasa melakukan aktiviti.", "domain": "afektif", "source_label": ""}], "draft_sha256": "feb28b87d4824b4d9e2bb2bb7b4a169fe8f18cdae39641f1d15cfc62233c7a4b"}'::jsonb,'[{"kind": "title", "text": "Minggu 31 Sesi 2 — Congkak bertukar tempat mula dan Datuk Harimau terkawal"}, {"kind": "subtitle", "text": "Pendidikan Jasmani Tahun 1 | Dua sesi seminggu | 30 minit setiap sesi | R1"}, {"kind": "p", "text": "ID: PJ1-2026B-2S-W31-S2"}, {"kind": "h2", "text": "A. Maklumat pengajaran"}, {"kind": "p", "text": "Guru: ____________________ | Kelas: __________ | Tarikh: __________ | Waktu: __________"}, {"kind": "p", "text": "Unit 6: Mari Bersantai"}, {"kind": "p", "text": "Tajuk buku teks: Santai Petang"}, {"kind": "p", "text": "Aktiviti guru: Congkak bertukar tempat mula dan Datuk Harimau terkawal"}, {"kind": "p", "text": "Rujukan buku teks PJPK Tahun 1, bahagian PJ: muka surat 42."}, {"kind": "p", "text": "Persediaan dua minit, pemanasan empat minit, tunjuk cara empat minit, Congkak sembilan minit, Datuk Harimau tujuh minit dan penyejukan empat minit. Pertukaran, rehat serta minum berada dalam masa fasa. Dahulukan giliran pertama semua murid sebelum ulangan."}, {"kind": "h2", "text": "B. Standard dan hasil pembelajaran"}, {"kind": "p", "text": "SK utama 1.10: Melakukan aktiviti rekreasi dan kesenggangan."}, {"kind": "p", "text": "SP utama 1.10.1: Menggunakan kemahiran lokomotor dan manipulasi semasa melakukan permainan tradisional seperti Datuk Harimau dan Congkak."}, {"kind": "p", "text": "SK sokongan 2.9: Mengaplikasi strategi dan idea kreatif dalam aktiviti rekreasi dan kesenggangan."}, {"kind": "p", "text": "SP sokongan 2.9.1: Mengenal pasti cara bermain permainan tradisional."}, {"kind": "p", "text": "SK sokongan 5.4: Membentuk kumpulan dan bekerjasama dalam kumpulan semasa melakukan aktiviti."}, {"kind": "p", "text": "SP sokongan 5.4.1: Mempamerkan aktiviti secara berpasangan."}, {"kind": "p", "text": "SK sokongan 5.4: Membentuk kumpulan dan bekerjasama dalam kumpulan semasa melakukan aktiviti."}, {"kind": "p", "text": "SP sokongan 5.4.2: Mempamerkan rasa seronok semasa melakukan aktiviti dalam kumpulan."}, {"kind": "label", "text": "Objektif"}, {"kind": "p", "text": "Murid dapat mengawal langkah Datuk Harimau dan menabur buah Congkak dari rumah mula yang berbeza sambil menjaga giliran."}, {"kind": "label", "text": "Kriteria kejayaan"}, {"kind": "p", "text": "1. Berhenti dan pulang mengikut arahan Datuk Harimau serta menabur Congkak dari rumah mula berbeza dengan terkawal."}, {"kind": "p", "text": "2. Menamatkan giliran Congkak selepas genggaman habis dan menunggu arahan sebelum bergerak dalam Datuk Harimau."}, {"kind": "p", "text": "3. Menyebut cara menjaga giliran dalam Datuk Harimau dan Congkak."}, {"kind": "p", "text": "Pengetahuan sedia ada: Guru menyemak semula rumah selamat dan taburan satu demi satu. Murid yang belum hadir sesi lalu diberi tunjuk cara awal, bukan dianggap sudah menguasai."}, {"kind": "h2", "text": "C. Alatan, persediaan dan keselamatan"}, {"kind": "label", "text": "Kon penanda"}, {"kind": "p", "text": "Keperluan: 15 kon: 12 bagi enam lorong, satu untuk guru dan dua untuk tempat menunggu."}, {"kind": "p", "text": "Kegunaan: Menandakan mula, hujung dan ruang menunggu dari sisi laluan; tiada kon di tempat kaki melangkah."}, {"kind": "label", "text": "Papan congkak sebenar"}, {"kind": "p", "text": "Keperluan: Satu papan bagi setiap pasangan; tujuh rumah anak pada setiap sisi dan satu rumah ibu pada setiap hujung."}, {"kind": "p", "text": "Kegunaan: Setiap murid menggenggam dan menabur buah pada gilirannya sendiri."}, {"kind": "label", "text": "Buah congkak licin bukan kaca dan bekas simpanan"}, {"kind": "p", "text": "Keperluan: 42 buah bagi setiap papan, tiga bagi setiap rumah anak; satu bekas bagi setiap papan."}, {"kind": "p", "text": "Kegunaan: Buah sesuai untuk umur murid, boleh digenggam dan tidak tajam; rumah ibu kosong ketika mula."}, {"kind": "label", "text": "Air minuman sendiri dan jam guru"}, {"kind": "p", "text": "Keperluan: Satu botol bagi setiap murid dan satu jam guru."}, {"kind": "p", "text": "Kegunaan: Rehat, minum dan mengurus pertukaran kumpulan."}, {"kind": "label", "text": "Persediaan guru"}, {"kind": "p", "text": "1. Guru menyusun enam lorong selari di permukaan rata yang kering. Dua kon diletakkan di sisi setiap lorong untuk menunjukkan rumah selamat di titik mula dan had hujung."}, {"kind": "p", "text": "2. Jarak setiap lorong cukup untuk tiga langkah kecil dengan ruang berhenti. Jarak antara murid membolehkan tangan dibuka tanpa menyentuh rakan. Kurangkan bilangan lorong aktif jika ruang sempit."}, {"kind": "p", "text": "3. Guru berdiri tetap di belakang konnya, jauh di hadapan had hujung murid. Dua kon lain menandakan tempat menunggu di luar laluan dan dalam pandangan guru."}, {"kind": "p", "text": "4. Papan congkak diletakkan stabil di kawasan teduh di luar lorong. Isi tiga buah pada setiap rumah anak, jumlah 42 buah bagi satu papan. Kosongkan kedua-dua rumah ibu."}, {"kind": "p", "text": "5. Guru mengira dan memeriksa buah sebelum serta selepas aktiviti. Buah yang terlalu kecil, retak atau tidak sesuai tidak digunakan."}, {"kind": "label", "text": "Susunan dan giliran murid"}, {"kind": "p", "text": "1. Kekalkan pasangan. Sehingga tiga pasangan, paling banyak enam murid, bermain Datuk Harimau serentak dalam lorong sendiri. Setiap pasangan berada dalam dua lorong bersebelahan, bukan berpegangan tangan."}, {"kind": "p", "text": "2. Kumpulan lain duduk tenang di tempat menunggu dan melihat. Guru menamatkan pusingan dahulu sebelum memanggil kumpulan seterusnya. Semua kumpulan mendapat pusingan sebelum sebarang ulangan."}, {"kind": "p", "text": "3. Semasa Congkak, semua pasangan bermain pada papan masing-masing. Dua atau tiga pasangan duduk berdekatan sebagai kumpulan kecil tanpa berkongsi giliran pemain."}, {"kind": "p", "text": "4. Guru menetapkan siapa bermula pada setiap papan. Pasangan berselang giliran satu genggaman; setiap murid melakukan sendiri, bukan seorang wakil pasangan."}, {"kind": "p", "text": "5. Murid boleh berehat atau minum selepas memberitahu guru. Guru merekod bahagian yang belum dicuba dan mengatur susulan, bukan mengisi pencapaian bagi murid yang hanya memerhati."}, {"kind": "label", "text": "Petunjuk pergerakan"}, {"kind": "p", "text": "1. Datuk Harimau: dengar jawapan satu hingga tiga dahulu. Ambil langkah kecil mengikut bilangan itu dan berhenti. Jangan bergerak hanya kerana rakan bergerak."}, {"kind": "p", "text": "2. Apabila Waktu makan disebut, pusing dengan tenang dan berjalan pantas pulang dalam lorong sendiri. Perlahankan langkah akhir dan berhenti di rumah selamat."}, {"kind": "p", "text": "3. Congkak: pilih rumah anak berisi pada sisi sendiri yang berbeza daripada rumah tengah sesi lalu. Mulakan dengan rumah kedua dari kiri, dekat rumah ibu sendiri; guru mengesahkan arahnya."}, {"kind": "p", "text": "4. Genggam semua isi rumah mula dengan tapak tangan menadah. Tabur bermula di rumah seterusnya dari kanan ke kiri, satu buah setiap rumah. Masukkan satu ke rumah ibu sendiri jika dilalui, teruskan di sisi lawan dan langkau rumah ibu lawan."}, {"kind": "p", "text": "5. Buah terakhir menamatkan satu giliran mini walaupun jatuh di rumah berisi atau rumah ibu sendiri. Lepaskan tangan dan beri giliran pasangan; tiada kutip semula, tangkap buah atau giliran tambahan."}, {"kind": "label", "text": "BBM"}, {"kind": "p", "text": "1. Kon penanda — 15 kon: 12 bagi enam lorong, satu untuk guru dan dua untuk tempat menunggu."}, {"kind": "p", "text": "2. Papan congkak sebenar — Satu papan bagi setiap pasangan; tujuh rumah anak pada setiap sisi dan satu rumah ibu pada setiap hujung."}, {"kind": "p", "text": "3. Buah congkak licin bukan kaca dan bekas simpanan — 42 buah bagi setiap papan, tiga bagi setiap rumah anak; satu bekas bagi setiap papan."}, {"kind": "p", "text": "4. Air minuman sendiri dan jam guru — Satu botol bagi setiap murid dan satu jam guru."}, {"kind": "p", "text": "5. Buku teks dan senarai semak pemerhatian guru."}, {"kind": "p", "text": "PAK-21: Pasangan memerhati taburan Congkak secara bergilir dan menyebut Giliran awak selepas genggaman habis. Dalam Datuk Harimau, pasangan bertanya waktu bersama tetapi bergerak di lorong berasingan. Rakan memberi teguran pendek dengan sopan; setiap murid tetap melaksanakan kedua-duanya sendiri."}, {"kind": "p", "text": "Nilai: Kerjasama, disiplin dan menjaga keselamatan rakan."}, {"kind": "label", "text": "Keselamatan"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula."}, {"kind": "p", "text": "2. Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan."}, {"kind": "p", "text": "3. Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan."}, {"kind": "p", "text": "4. Datuk Harimau ialah adaptasi guru tanpa sentuhan dan tanpa kejar-mengejar. Guru kekal di belakang kon; tiada menangkap, menolak, menyekat, menyingkir atau memaksa murid berlari."}, {"kind": "p", "text": "5. Selepas Waktu makan, murid berpusing dengan tenang lalu berjalan pantas dalam lorong sendiri. Murid berhenti stabil di rumah selamat. Jangan mengundur laju atau memotong lorong."}, {"kind": "p", "text": "6. Hanya satu kumpulan kecil aktif. Kumpulan menunggu berada di luar laluan dan tetap dalam pandangan guru. Hentikan pusingan jika laluan terganggu."}, {"kind": "p", "text": "7. Buah congkak tidak dimasukkan ke mulut, hidung atau telinga dan tidak dibaling. Tangan berada rendah di atas papan. Buah yang jatuh dikutip selepas semua tangan berhenti."}, {"kind": "p", "text": "8. Guru memantau risiko tercekik. Jika buah tidak sesuai atau murid masih memasukkan benda ke mulut, tangguhkan amali Congkak murid berkenaan sehingga alat dan pengawasan selamat tersedia; catat bahagian belum dilaksanakan."}, {"kind": "p", "text": "Jika cuaca atau ruang tidak sesuai: Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat."}, {"kind": "h2", "text": "D. Langkah PdP"}, {"kind": "h3", "text": "Langkah 1: Persediaan murid dan alatan — 2 minit"}, {"kind": "p", "text": "Minit 0 hingga 2."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan."}, {"kind": "p", "text": "2. Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid memberitahu guru jika tidak sihat."}, {"kind": "p", "text": "2. Murid mengambil tempat yang ditetapkan dan mendengar arahan."}, {"kind": "p", "text": "Semakan: Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan."}, {"kind": "p", "text": "Alatan: Kon penanda Papan congkak sebenar Buah congkak licin bukan kaca dan bekas simpanan Air minuman sendiri dan jam guru"}, {"kind": "h3", "text": "Langkah 2: Pemanasan badan — 4 minit"}, {"kind": "p", "text": "Minit 2 hingga 6."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit."}, {"kind": "p", "text": "2. Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid bergerak dalam ruang sendiri tanpa bersentuh."}, {"kind": "p", "text": "2. Murid bernafas seperti biasa dan berehat jika perlu."}, {"kind": "p", "text": "Semakan: Murid bersedia untuk aktiviti tanpa terlalu penat."}, {"kind": "p", "text": "Alatan: Ruang lapang Kon penanda"}, {"kind": "h3", "text": "Langkah 3: Ulang arah dan tunjuk pertukaran giliran — 4 minit"}, {"kind": "p", "text": "Minit 6 hingga 10."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan rumah mula Congkak yang berbeza daripada rumah tengah: rumah kedua dari kiri pada sisi pemain. Guru menabur tiga buah, memasukkan buah ke rumah ibu sendiri apabila dilalui, lalu berhenti selepas buah terakhir."}, {"kind": "p", "text": "2. Guru menegaskan peraturan mini: tamat genggaman bermaksud tamat giliran walaupun rumah terakhir berisi atau rumah ibu sendiri. Guru menunjukkan pemain seterusnya menunggu tangan pemain pertama dilepaskan."}, {"kind": "p", "text": "3. Guru mengingatkan semula rumah selamat Datuk Harimau. Guru menunjukkan melangkah selepas bilangan disebut, berhenti, kemudian berpusing dan pulang selepas Waktu makan; guru harimau tidak bergerak mengejar."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid menunjuk rumah Congkak berisi yang hendak digunakan dan rumah ibu sendiri. Pasangan menyebut siapa bermula hari ini."}, {"kind": "p", "text": "2. Murid menyebut Giliran awak apabila genggaman contoh habis, bukan mengambil isi rumah terakhir."}, {"kind": "p", "text": "3. Murid menunjuk lorong Datuk Harimau sendiri dan meniru cara berhenti serta berpusing perlahan di tempat."}, {"kind": "p", "text": "Semakan: Murid membezakan rumah mula dengan rumah seterusnya dan tahu bila boleh bergerak atau mengambil giliran."}, {"kind": "p", "text": "Alatan: Papan congkak sebenar 42 buah congkak Kon penanda"}, {"kind": "h3", "text": "Langkah 4: Congkak: mula berbeza, giliran terjaga — 9 minit"}, {"kind": "p", "text": "Minit 10 hingga 19."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memeriksa tiga buah pada setiap rumah anak, 42 buah bagi papan dan rumah ibu kosong. Murid yang bermula kedua pada sesi lalu diberi giliran pertama hari ini; jika tiada rekod, guru menetapkan pemain pertama."}, {"kind": "p", "text": "2. Guru meminta setiap pemain menggunakan rumah kedua dari kiri pada sisi sendiri, bukan rumah tengah. Jika rumah itu kosong semasa giliran tiba, pilih rumah anak berisi lain pada sisi sendiri; jangan menggenggam ruang kosong atau mengambil buah rakan."}, {"kind": "p", "text": "3. Guru memerhati genggaman menadah dan taburan satu demi satu bermula di rumah seterusnya, dari kanan ke kiri. Masukkan buah ke rumah ibu sendiri jika dilalui, sambung di sisi lawan dan langkau rumah ibu lawan."}, {"kind": "p", "text": "4. Selepas buah terakhir dilepaskan, pemain meletakkan tangan di sisi papan dan pasangan bermain. Hadnya satu genggaman: rumah akhir berisi, kosong atau rumah ibu sendiri semuanya menamatkan giliran mini. Tiada mengambil semula isi rumah akhir, menangkap buah atau giliran tambahan."}, {"kind": "p", "text": "5. Selepas kedua-dua pemain selesai, pasangan menyusun semula tiga buah setiap rumah anak dan mengosongkan rumah ibu. Pemain kedua tadi bermula pusingan seterusnya; jika masa mengizinkan, pilih rumah berisi lain daripada pusingan tadi."}, {"kind": "p", "text": "6. Guru menyemak kedua-dua murid dan bertanya tentang arah serta giliran. Pada akhir fasa, jangan mula giliran baharu; habiskan genggaman semasa dengan tenang, simpan buah dan berjalan ke ruang Datuk Harimau. Rehat dan minum dibenarkan ketika pertukaran."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid menunjuk rumah Congkak yang dipilih sebelum mengambil semua isinya. Pasangan menunggu tangan pemain bersedia."}, {"kind": "p", "text": "2. Murid menggenggam dan menabur satu demi satu mengikut arah. Murid memasukkan buah ke rumah ibu sendiri jika dilalui dan meneruskan taburan tanpa melangkau rumah anak."}, {"kind": "p", "text": "3. Selepas buah terakhir, murid menyebut Giliran awak dan meletakkan tangan di sisi. Pasangan melakukan taburannya sendiri, bukan hanya mengira untuk rakan."}, {"kind": "p", "text": "4. Kedua-dua murid menyusun semula papan selepas giliran masing-masing. Murid boleh memilih rumah berisi lain pada pusingan seterusnya dan menerangkan bila gilirannya tamat."}, {"kind": "p", "text": "5. Murid mengemas apabila diarahkan. Murid menyatakan respons sebenar tentang bermain dalam kumpulan kecil dan tidak dipaksa meneruskan jika tidak selesa."}, {"kind": "p", "text": "Semakan: Setiap murid mempunyai bukti taburan dari rumah mula berbeza, arah dan pertukaran giliran; guru merekod bantuan serta giliran belum selesai."}, {"kind": "p", "text": "Alatan: Papan congkak bagi setiap pasangan 42 buah bagi setiap papan Bekas simpanan Air minuman"}, {"kind": "h3", "text": "Langkah 5: Datuk Harimau: dengar, berhenti dan pulang — 7 minit"}, {"kind": "p", "text": "Minit 19 hingga 26."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memanggil sehingga enam murid, berpasangan dalam lorong bersebelahan. Guru kekal sebagai harimau di belakang kon; yang lain duduk tenang dalam pandangan guru."}, {"kind": "p", "text": "2. Guru menunggu soalan Pukul berapa, Datuk Harimau? lalu menjawab antara satu hingga tiga. Hanya satu soalan bagi satu pusingan supaya murid tidak menghampiri guru. Guru menunggu murid berhenti sebelum menyebut Waktu makan."}, {"kind": "p", "text": "3. Guru memerhatikan murid berpusing dan berjalan pantas pulang dalam lorong masing-masing. Guru menegaskan tiada sentuhan, kejar-mengejar, perlumbaan atau penyingkiran."}, {"kind": "p", "text": "4. Selepas semua berhenti stabil, guru menyebut Berhenti dan mengarahkan keluar ke sisi kosong. Kumpulan baharu masuk hanya selepas lorong kosong. Semua kumpulan mesti mendapat giliran sebelum pusingan ulangan."}, {"kind": "p", "text": "5. Guru merekod kawalan setiap murid dan bertanya bila perlu bergerak atau berhenti serta perasaannya bermain bersama rakan. Jika ada masa selepas semua mendapat giliran, gunakan bilangan langkah yang berbeza dalam had yang sama."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Pasangan bertanya waktu bersama. Murid mendengar jawapan dahulu, mengambil bilangan langkah kecil yang disebut dan berhenti sebelum had hujung."}, {"kind": "p", "text": "2. Selepas Waktu makan, murid berpusing dengan tenang lalu berjalan pantas ke rumah selamat sendiri. Murid memperlahankan langkah akhir dan berhenti tanpa bersentuh."}, {"kind": "p", "text": "3. Murid menunggu arahan keluar. Kumpulan menunggu memberi ruang dan tidak masuk awal atau mengganggu lorong."}, {"kind": "p", "text": "4. Setiap murid menjelaskan bila boleh bergerak dan berkongsi perasaan apabila ditanya; murid boleh meminta rehat."}, {"kind": "p", "text": "Semakan: Bandingkan kawalan mula dan berhenti murid dengan percubaannya sendiri, bukan kelajuan rakan. Lengkapkan bukti Datuk Harimau bagi murid yang sama yang bermain Congkak."}, {"kind": "p", "text": "Alatan: 15 kon penanda Jam guru Air minuman"}, {"kind": "h3", "text": "Langkah 6: Penyejukan badan dan penutup — 4 minit"}, {"kind": "p", "text": "Minit 26 hingga 30."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit."}, {"kind": "p", "text": "2. Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid meregang mengikut keselesaan tanpa sentapan."}, {"kind": "p", "text": "2. Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."}, {"kind": "p", "text": "Semakan: Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli."}, {"kind": "p", "text": "Alatan: Air minuman Ruang rehat"}, {"kind": "p", "text": "Jumlah masa: 30 minit."}, {"kind": "label", "text": "Contoh arahan kelas"}, {"kind": "p", "text": "Guru: Pilih rumah mula yang lain. Selepas buah terakhir, beri giliran. Dalam Datuk Harimau, tunggu suara saya sebelum bergerak."}, {"kind": "p", "text": "Murid: Setiap murid menabur Congkak sendiri, kemudian bergerak dan berhenti dalam pusingan Datuk Harimau."}, {"kind": "p", "text": "Semakan guru: Guru memeriksa rumah mula, arah, pertukaran giliran dan hentian setiap murid."}, {"kind": "h2", "text": "E. PdP terbeza", "anchor": "pdp-PJ1-2026B-2S-W31-S2"}, {"kind": "p", "text": "Tugasan bersama: Murid dapat mengawal langkah Datuk Harimau dan menabur buah Congkak dari rumah mula yang berbeza sambil menjaga giliran."}, {"kind": "p", "text": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan."}, {"kind": "label", "text": "Bimbingan guru"}, {"kind": "p", "text": "1. Guru menyemak kedua-dua pemain Congkak, bukan pemerhati sahaja, sambil bergerak dari papan ke papan. Catat bantuan rumah mula dan arah."}, {"kind": "p", "text": "2. Semasa Datuk Harimau, guru kekal di belakang kon dan memerhatikan setiap murid dalam kumpulan kecil. Catat mula serta hentian selepas pusingan berhenti."}, {"kind": "p", "text": "Semakan individu: Berhenti dan pulang mengikut arahan Datuk Harimau serta menabur Congkak dari rumah mula berbeza dengan terkawal."}, {"kind": "p", "text": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, {"kind": "h3", "text": "Peneroka"}, {"kind": "p", "text": "Guru membimbing satu langkah pada satu masa."}, {"kind": "p", "text": "Tugasan: Memilih rumah mula Congkak dengan bantuan dan menunggu arahan Datuk Harimau sebelum melangkah."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Papan congkak pasangan"}, {"kind": "p", "text": "2. 42 buah bagi satu papan"}, {"kind": "p", "text": "3. Lorong berkon yang sama"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjuk rumah Congkak kedua dari kiri dan membimbing arah dengan jari dari luar papan. Guru menyebut Tamat, giliran pasangan selepas buah terakhir."}, {"kind": "p", "text": "2. Guru memberi arahan Datuk Harimau dengan jeda yang jelas. Guru mengingatkan pusing dahulu dan berjalan pulang tanpa bergerak mengejar."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Murid memilih rumah mula Congkak yang ditunjukkan, berbeza daripada rumah tengah, dan menggenggam semua isinya."}, {"kind": "p", "text": "2. Murid menabur satu demi satu, memasukkan buah ke rumah ibu sendiri jika dilalui dan memberi giliran selepas buah terakhir dengan bantuan lisan."}, {"kind": "p", "text": "3. Murid bertanya waktu Datuk Harimau bersama pasangan, mendengar bilangan dan mengambil langkah kecil dalam lorong sendiri."}, {"kind": "p", "text": "4. Murid berpusing dan pulang selepas Waktu makan. Murid menyebut bila gilirannya tamat dalam Congkak dan bila pulang dalam Datuk Harimau."}, {"kind": "p", "text": "Contoh guru: Siapa bermain selepas buah habis? Bila kamu pulang ke rumah selamat?"}, {"kind": "p", "text": "Contoh respons murid: Pasangan saya bermain. Saya pulang apabila dengar Waktu makan."}, {"kind": "p", "text": "Hasil individu: Taburan Congkak dari rumah mula lain serta langkah dan kepulangan Datuk Harimau oleh murid sendiri dengan bantuan dicatat."}, {"kind": "p", "text": "Kriteria: Murid menabur satu genggaman Congkak sebelum memberi giliran dan menunggu arahan Datuk Harimau sebelum melangkah atau pulang."}, {"kind": "p", "text": "Susulan: Kekalkan bantuan menunjuk rumah Congkak dan arahan Datuk Harimau yang berjarak. Semak semula kedua-dua lakuan yang belum jelas tanpa meminta rakan melakukannya."}, {"kind": "h3", "text": "Pembina"}, {"kind": "p", "text": "Murid berlatih berpasangan dan melakukan sendiri."}, {"kind": "p", "text": "Tugasan: Menjaga arah dan giliran Congkak serta mula dan berhenti tepat pada arahan Datuk Harimau."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Satu papan congkak bagi pasangan"}, {"kind": "p", "text": "2. 42 buah bagi satu papan"}, {"kind": "p", "text": "3. Dua lorong berkon bersebelahan"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menyemak rumah mula Congkak berbeza dan membetulkan arah sebelum murid melepaskan buah seterusnya."}, {"kind": "p", "text": "2. Guru memeriksa pasangan Datuk Harimau menggunakan lorong sendiri dan memperlahankan langkah sebelum berhenti di rumah selamat."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Murid memilih rumah mula Congkak berisi yang berbeza daripada rumah tengah dan menabur dari kanan ke kiri."}, {"kind": "p", "text": "2. Murid berhenti selepas genggaman habis, memberi giliran pasangan dan menyusun semula papan selepas kedua-duanya selesai."}, {"kind": "p", "text": "3. Murid bertanya waktu Datuk Harimau bersama pasangan, mendengar bilangan dan berhenti selepas langkah yang disebut."}, {"kind": "p", "text": "4. Murid pulang selepas Waktu makan dan berhenti stabil. Setiap murid menyebut cara menjaga giliran dalam Datuk Harimau dan Congkak kepada pasangan."}, {"kind": "p", "text": "Contoh guru: Apakah yang kamu tunggu sebelum mengambil buah dan sebelum pulang?"}, {"kind": "p", "text": "Contoh respons murid: Saya tunggu pasangan habis menabur. Saya tunggu Waktu makan sebelum pulang."}, {"kind": "p", "text": "Hasil individu: Giliran Congkak dari rumah mula berbeza dan pusingan Datuk Harimau dengan mula serta hentian terkawal bagi setiap murid."}, {"kind": "p", "text": "Kriteria: Setiap murid menamatkan satu genggaman Congkak sebelum pasangan bermain dan mengikut arahan mula serta pulang Datuk Harimau."}, {"kind": "p", "text": "Susulan: Ulang giliran Congkak atau pusingan Datuk Harimau yang memerlukan pembetulan sahaja, dalam masa tersedia selepas semua murid mendapat giliran."}, {"kind": "h3", "text": "Pencabar"}, {"kind": "p", "text": "Murid memperkemas satu perkara dalam kemahiran yang sama."}, {"kind": "p", "text": "Tugasan: Melaras arah Congkak dari tempat mula baharu dan memperkemas hentian Datuk Harimau tanpa menambah kepantasan."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Papan congkak pasangan"}, {"kind": "p", "text": "2. 42 buah bagi satu papan"}, {"kind": "p", "text": "3. Lorong berkon yang sama"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru meminta murid menunjuk rumah Congkak seterusnya sebelum menabur jika ragu-ragu. Guru membenarkan bantuan arah sepanjang giliran."}, {"kind": "p", "text": "2. Guru menumpukan pada langkah akhir Datuk Harimau yang semakin perlahan, bukan jarak atau bilangan langkah tambahan."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Murid memilih rumah mula Congkak yang berbeza dan menunjuk arah rumah seterusnya sebelum menggenggam buah."}, {"kind": "p", "text": "2. Murid menabur rendah di atas papan dan menyerahkan giliran selepas buah terakhir, walaupun jatuh di rumah ibu sendiri. Murid memberitahu pasangan sebab berhenti dalam versi mini."}, {"kind": "p", "text": "3. Murid mendengar jawapan Datuk Harimau, melangkah mengikut bilangan dan berhenti tanpa mengikut gerakan awal rakan."}, {"kind": "p", "text": "4. Murid pulang selepas Waktu makan dengan langkah akhir perlahan. Murid berkongsi satu pembaikan kawalan Datuk Harimau dan Congkak."}, {"kind": "p", "text": "Contoh guru: Buah terakhir masuk rumah ibu sendiri. Apa tindakan hari ini? Bagaimana kamu berhenti ketika pulang?"}, {"kind": "p", "text": "Contoh respons murid: Saya beri giliran kerana latihan satu genggaman. Saya perlahankan langkah akhir."}, {"kind": "p", "text": "Hasil individu: Taburan Congkak yang kekal teratur dari mula baharu serta hentian pulang Datuk Harimau yang stabil; bukti setiap murid."}, {"kind": "p", "text": "Kriteria: Murid menjaga arah dan tamat giliran Congkak walaupun rumah mula berubah serta memperlahankan langkah sebelum berhenti dalam Datuk Harimau."}, {"kind": "p", "text": "Susulan: Jika masih tersalah arah Congkak atau pulang terlalu awal dalam Datuk Harimau, kekalkan petunjuk guru. Kemajuan tidak diukur dengan kelajuan atau kemenangan."}, {"kind": "h2", "text": "F. Pentaksiran Bilik Darjah"}, {"kind": "p", "text": "Catat lakuan sebenar individu dalam kedua-dua permainan. Langkah pulang tanpa kejar-mengejar bukan pentaksiran kemahiran mengelak. Menguasai giliran Congkak mini tidak membuktikan penguasaan semua peraturan permainan atau menetapkan TP secara automatik."}, {"kind": "h3", "text": "PBD utama — SP 1.10.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian individu ketika menabur Congkak dari rumah mula berbeza dan bergerak dalam pusingan Datuk Harimau."}, {"kind": "p", "text": "Bukti: Catatan nama yang sama bagi genggaman, arah dan pelepasan Congkak serta masa mula, pusingan dan hentian pulang Datuk Harimau."}, {"kind": "p", "text": "Kriteria: Murid menabur Congkak satu demi satu dari rumah mula berbeza dan melakukan langkah serta kepulangan Datuk Harimau dengan terkawal; kedua-dua amali diperlukan."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama murid: ____."}, {"kind": "p", "text": "2. Congkak — rumah mula, genggaman dan taburan: ____; bantuan: ____."}, {"kind": "p", "text": "3. Datuk Harimau — langkah, pusingan dan hentian: ____; bantuan: ____."}, {"kind": "p", "text": "4. Bahagian belum dicuba atau belum diperhatikan: ____; susulan: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 2.9.1"}, {"kind": "p", "text": "Kaedah: Soal jawab seorang demi seorang selepas taburan Congkak dan pusingan Datuk Harimau."}, {"kind": "p", "text": "Bukti: Jawapan murid tentang buah terakhir menamatkan giliran Congkak mini serta arahan bilangan dan Waktu makan dalam Datuk Harimau."}, {"kind": "p", "text": "Kriteria: Murid menerangkan secara ringkas bila gilirannya tamat dalam Congkak mini dan bila perlu bergerak atau pulang dalam Datuk Harimau."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama murid: ____."}, {"kind": "p", "text": "2. Congkak — penjelasan tamat giliran mini: ____."}, {"kind": "p", "text": "3. Datuk Harimau — penjelasan arahan bergerak atau pulang: ____."}, {"kind": "p", "text": "4. Petunjuk guru yang diperlukan: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 5.4.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian perbuatan setiap murid dalam pasangan Congkak dan pasangan Datuk Harimau."}, {"kind": "p", "text": "Bukti: Murid memberi serta mengambil giliran Congkak sendiri dan bertanya waktu serta menjaga ruang pasangan Datuk Harimau tanpa mewakilkan lakuan."}, {"kind": "p", "text": "Kriteria: Setiap murid melakukan peranannya sendiri bersama pasangan dalam Congkak dan Datuk Harimau serta membenarkan pasangan mendapat giliran."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama murid: ____; pasangan: ____."}, {"kind": "p", "text": "2. Congkak — mengambil dan memberi giliran sendiri: ____."}, {"kind": "p", "text": "3. Datuk Harimau — turut bergerak dan menjaga ruang pasangan: ____."}, {"kind": "p", "text": "4. Bantuan kerjasama yang diperlukan: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 5.4.2"}, {"kind": "p", "text": "Kaedah: Pemerhatian dan pertanyaan individu tentang pengalaman berkumpulan dalam Congkak serta Datuk Harimau."}, {"kind": "p", "text": "Bukti: Kata-kata atau tingkah laku sebenar setiap murid tentang keseronokan giliran Congkak dan bermain Datuk Harimau bersama rakan; respons kedua-dua aktiviti direkod."}, {"kind": "p", "text": "Kriteria: Murid menunjukkan atau menyatakan rasa seronok dalam kumpulan Congkak dan Datuk Harimau. Jika murid diam atau tidak selesa, catat keadaan sebenar dan susuli tanpa paksaan."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama murid: ____."}, {"kind": "p", "text": "2. Congkak — respons atau tingkah laku sebenar: ____."}, {"kind": "p", "text": "3. Datuk Harimau — respons atau tingkah laku sebenar: ____."}, {"kind": "p", "text": "4. Keselesaan, rehat atau susulan: ____."}, {"kind": "h2", "text": "G. Refleksi dan intervensi"}, {"kind": "p", "text": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________."}, {"kind": "label", "text": "Intervensi"}, {"kind": "p", "text": "Murid yang masih keliru memilih rumah Congkak berisi diberi petunjuk langsung dan menabur sendiri. Murid yang pulang awal dalam Datuk Harimau diberi latihan dengar dan berhenti sebelum pusingan berikutnya. Lengkapkan bukti kedua-dua aktiviti pada susulan jika belum dilihat; jangan menukar minit sesi atau menganggap percubaan selesai."}]'::jsonb,'{"source_hold": "", "adaptation_note": "BT42 menamakan Datuk Harimau dan Congkak tanpa peraturan lengkap dalam teks. Kedua-dua permainan digunakan setiap sesi untuk lokomotor dan manipulasi. Versi mini Datuk Harimau tanpa sentuhan dan congkak tiga buah setiap rumah anak ialah latihan guru, bukan peraturan pertandingan penuh. Papan congkak dan buah sebenar yang selamat digunakan, bukan permainan kad.", "source_images_verified": true, "audio_verified": false, "ba_verified": false, "classroom_trial_performed": false}'::jsonb),
  ('PJ1-2026B-2S-W32-S1','pj',1,2026,32,1,30,'1.10.2',array[43]::int[],'0b86dbfacf8bb81e7a5d68832dcab1e60f61e0d14483de0fa1bd1c1204152981','983a83f37e694d17d330c5ff24d6d90f30aad2487fa40e8170542280e233ff31','715d2dd93e616381f7de4fb5e317e008bae7007088b12831c3d9d17a2be5d6d7','ACCEPTED_FROM_DOWNLOADED_CATATAN',false,'{"id": "PJ1-2026B-2S-W32-S1", "subject": "Pendidikan Jasmani", "year": 1, "week": 32, "session": 1, "revision": "PJ1-30MIN-REVIEW-R1", "date": "", "teaching_time": "", "minutes": 30, "sessions_per_week": 2, "weekly_minutes": 60, "title": "Saya Kreatif", "source_title": "Saya Kreatif", "unit": "Unit 6: Mari Bersantai", "source_row_id": "PJ1-RPT2026-T11-R2", "source_row_literal": ["32\n\nKump A: 13.09.2026-17.09.2026\n\nKump B:\n14.09.2026-18.09.2026", "6: MARI BERSANTAI\nSAYA KREATIF", "1.10 Melakukan aktiviti rekreasi dan kesenggangan\n2.9 Mengaplikasi strategi dan idea kreatif dalam aktiviti rekreasi dan   kesenggangan\n5.2 Menunjukkan keyakinan dan tanggungjawab kendiri semasa melakukan aktiviti.", "1.10.2 Membina istana pasir, dan mereka cipta objek menggunakan plastisin atau blok mainan.\n\n2.9.2 Menerangkan reka bentuk istana pasir dan objek yang dibina.\n\n5.2.1 Mempamerkan rasa seronok melakukan aktiviti baharu dalam Pendidikan Jasmani.", "Pemerhatian /\nPentaksiran \n\n\nEMK: \nKreativiti & Inovasi\n\nBT m/s 43"], "rpt_original_page_literal": "43", "source_pages": [43], "source_pdf_pages": [51], "rpt_book_pages": "43", "main_standard_key": "1.10.2", "sk_code": "1.10", "sk_text": "Melakukan aktiviti rekreasi dan kesenggangan.", "sp_code": "1.10.2", "sp_text": "Membina istana pasir dan mereka cipta objek menggunakan plastisin atau blok mainan.", "complementary_standards": [{"standard_key": "2.9.2", "sp_code": "2.9.2", "sp_text": "Menerangkan reka bentuk istana pasir dan objek yang dibina.", "sk_code": "2.9", "sk_text": "Mengaplikasi strategi dan idea kreatif dalam aktiviti rekreasi dan kesenggangan.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.2.1", "sp_code": "5.2.1", "sp_text": "Mempamerkan rasa seronok melakukan aktiviti baharu dalam Pendidikan Jasmani.", "sk_code": "5.2", "sk_text": "Menunjukkan keyakinan dan tanggungjawab kendiri semasa melakukan aktiviti.", "domain": "afektif", "source_label": ""}], "source_task": "Membina istana pasir kecil dan rumah blok", "authoring_focus": "Membina istana pasir kecil dan rumah blok", "source_hold": "Teks RPT, DSKP dan buku dibaca. Semakan imej guling BT35 dan kod DSKP hlm70 terhalang ralat402; OCR dan teks salinan menyokong kod berulang, bukan kelulusan visual. Guru perlu menilai postur, alat dan kesediaan setiap murid.", "practical_required": true, "warmup_required": true, "cooldown_required": true, "facility_replacement": false, "facility_replacement_note": "", "source_subset_focus": false, "source_subset_note": "", "adaptation_note": "Guru mengesahkan pasir bersih dalam dulang dan plastisin atau blok. Blok dipilih daripada pilihan sumber. Setiap murid membina istana pasir dan objek blok dalam setiap sesi; bukan satu bahan bagi satu kumpulan. Tugas ringkas dengan bahagian individu dan penerangan sendiri.", "privacy_adaptation": false, "privacy_note": "", "held_standards": [], "source_code_conflict": false, "source_code_note": "", "unperformed_literal_elements": [], "source_mapping_review": "20 RPH, dua sesi30minit seminggu dibenarkan guru. S1/S2 ialah cadangan pecahan RPT mingguan, bukan nombor sesi yang tercetak dalam RPT.", "routine_book_pages": [46, 47], "active": false, "production_write_performed": false, "presentation_review": "PENDING_TEACHER_REVIEW", "safety": ["Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula.", "Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan.", "Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan.", "Pasir mesti bersih, bebas najis, serpihan dan benda tajam serta sedikit lembap supaya tidak berdebu. Jika tidak sesuai, tangguhkan bahagian pasir dan rekod belum dilaksanakan.", "Pasir dan blok tidak dimasukkan ke mulut, hidung atau telinga. Tiada tiupan pasir, balingan atau perebutan bahan.", "Tangan dibasuh dengan sabun selepas pasir dan sebelum minum atau menyentuh muka. Luka terbuka ditutup mengikut panduan sekolah; murid yang tidak boleh mengendalikan pasir diberi susulan sesuai.", "Dulang stabil di atas alas pada permukaan rendah. Bersihkan tumpahan segera dan kosongkan laluan sebelum murid bergerak.", "Binaan rendah sahaja; murid tidak memanjat, mengangkat dulang berat atau menjatuhkan blok ke arah rakan."], "weather_plan": "Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat.", "reflection": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________.", "activity_name": "Istana pasir kecil dan rumah blok", "objective": "Murid dapat membina istana pasir dan objek blok serta menerangkan binaannya.", "success_criteria": ["Membina satu istana pasir kecil dan satu objek rumah daripada blok melalui tindakan sendiri.", "Menunjukkan serta menamakan satu bahagian bagi setiap binaan."], "prior_knowledge": "Murid pernah menyusun objek. Guru menyemak cara memegang sudu dan blok dengan selamat.", "equipment": [{"item": "Dulang pasir bersih yang sedikit lembap", "quantity": "Satu dulang lebar setiap pasangan, dibahagi kepada dua ruang kerja.", "use": "Setiap murid membina istana pasir sendiri tanpa mengganggu binaan pasangan."}, {"item": "Cawan acuan dan sudu plastik tumpul", "quantity": "Dua cawan dan dua sudu setiap pasangan; satu set setiap murid.", "use": "Mencedok, memadatkan dan membentuk pasir."}, {"item": "Blok mainan besar", "quantity": "Dua belas blok setiap pasangan; enam bagi setiap murid.", "use": "Membina objek sendiri di ruang berasingan daripada dulang pasir."}, {"item": "Kon, alas kerja dan bekas alatan", "quantity": "Empat kon di luar ruang berjalan; alas serta bekas setiap pasangan.", "use": "Menandakan ruang gerak dan mengasingkan pasir daripada laluan."}, {"item": "Air minuman serta tempat mencuci tangan", "quantity": "Botol sendiri; kemudahan basuh tangan dengan sabun tersedia.", "use": "Rehat, minum selepas tangan dibersihkan dan kebersihan selepas mengendalikan pasir."}], "preparation": ["Sediakan pasir sedikit lembap lebih awal; bukan membancuh atau menuang air semasa murid berjalan.", "Bahagikan dulang kepada dua ruang dan susun enam blok setiap murid di atas alas berasingan.", "Letakkan tempat basuh tangan yang mudah diawasi. Jika satu paip sahaja, kumpulan mencuci bergilir sebelum fasa pasir berakhir; pendekkan pembinaan, bukan abaikan kebersihan."], "organisation": ["Setiap pasangan berkongsi dulang tetapi mempunyai ruang istana dan set blok sendiri. Kedua-dua murid melakukan kedua-dua binaan, bukan seorang pasir dan seorang blok.", "Guru memberi bantuan Peneroka di meja atau alas yang sama. Murid lain membina dengan bahan yang telah disediakan dalam pandangan guru.", "Dua minit akhir fasa pasir digunakan untuk mengasingkan alat dan mencuci tangan; masa beralih serta rehat termasuk dalam fasa. Jika giliran basuh tangan lebih panjang, pendekkan masa membina."], "movement_cues": ["Cedok sedikit pasir dengan sudu. Padatkan dalam cawan, terbalikkan di ruang sendiri dan angkat cawan perlahan.", "Bentuk istana kecil yang rendah; satu menara sudah mencukupi. Jangan meniup atau membaling pasir.", "Susun blok dari tapak yang lebar dan stabil. Bina objek rendah; jangan meletakkan blok di atas kepala atau memanjatnya.", "Tunjukkan bahagian binaan sendiri dan beri penerangan ringkas, contohnya Ini menara istana; ini dinding rumah."], "timing_note": "Fasa sembilan minit untuk pasir dan peralihan kebersihan; tujuh minit untuk objek blok, penerangan serta pengemasan. Semua termasuk dalam 30 minit.", "values": "Kerjasama, disiplin dan menjaga keselamatan rakan.", "classroom_example": {"teacher_says": "Bina satu menara di ruang pasir kamu. Selepas itu, bina rumah rendah dengan blok kamu.", "pupils_do": "Murid membina kedua-dua objek sendiri dan menunjuk menara serta dinding.", "teacher_checks": "Guru semak tangan murid mengendalikan kedua-dua bahan dan mendengar penerangan setiap binaan."}, "bbm": ["Dulang pasir bersih yang sedikit lembap — Satu dulang lebar setiap pasangan, dibahagi kepada dua ruang kerja.", "Cawan acuan dan sudu plastik tumpul — Dua cawan dan dua sudu setiap pasangan; satu set setiap murid.", "Blok mainan besar — Dua belas blok setiap pasangan; enam bagi setiap murid.", "Kon, alas kerja dan bekas alatan — Empat kon di luar ruang berjalan; alas serta bekas setiap pasangan.", "Air minuman serta tempat mencuci tangan — Botol sendiri; kemudahan basuh tangan dengan sabun tersedia.", "Buku teks dan senarai semak pemerhatian guru."], "pak21": "Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan.", "phases": [{"name": "Persediaan murid dan alatan", "minutes": 2, "teacher": ["Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan.", "Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."], "pupils": ["Murid memberitahu guru jika tidak sihat.", "Murid mengambil tempat yang ditetapkan dan mendengar arahan."], "check": "Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan.", "resources": ["Dulang pasir bersih yang sedikit lembap", "Cawan acuan dan sudu plastik tumpul", "Blok mainan besar", "Kon, alas kerja dan bekas alatan", "Air minuman serta tempat mencuci tangan"]}, {"name": "Pemanasan badan", "minutes": 4, "teacher": ["Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit.", "Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."], "pupils": ["Murid bergerak dalam ruang sendiri tanpa bersentuh.", "Murid bernafas seperti biasa dan berehat jika perlu."], "check": "Murid bersedia untuk aktiviti tanpa terlalu penat.", "resources": ["Ruang lapang", "Kon penanda"]}, {"name": "Tunjuk dua cara membina", "minutes": 4, "teacher": ["Guru merujuk arahan BT43 tentang istana pasir dan objek. Guru menunjukkan satu menara menggunakan acuan.", "Guru menyusun rumah blok rendah sebagai contoh, kemudian membuka semula susunan supaya murid membina sendiri."], "pupils": ["Murid melihat cara memadat dan mengangkat cawan perlahan.", "Murid mengenal ruang serta blok sendiri dan menyebut bahagian yang hendak dibina."], "check": "Contoh guru membantu, bukan hasil yang diberikan kepada murid.", "resources": ["Dulang pasir", "Cawan dan sudu", "Blok besar"]}, {"name": "Bina istana pasir sendiri", "minutes": 9, "teacher": ["Guru memberi dua minit untuk mencuba cedok dan padat.", "Guru memberi lima minit untuk setiap murid membentuk istana kecil serta menyebut satu bahagiannya. Bantu satu langkah tanpa membuat seluruh binaan bagi murid.", "Gunakan dua minit akhir untuk merapikan pasir, mengasingkan alatan dan mencuci tangan secara bergilir. Sesuaikan giliran paip dan pendekkan masa membina jika perlu."], "pupils": ["Murid mencedok dan memadatkan pasir di cawan sendiri.", "Murid membentuk satu menara dan merapikan tapaknya di bahagian dulang sendiri.", "Murid menunjuk menara atau tapak sambil menerangkan dengan kata pendek, kemudian mencuci tangan."], "check": "Guru mencatat binaan serta penerangan istana setiap murid; foto sahaja tanpa lakuan bukan bukti lengkap.", "resources": ["Pasir", "Cawan", "Sudu", "Air dan sabun"]}, {"name": "Bina rumah blok dan ceritakan", "minutes": 7, "teacher": ["Pastikan tangan bersih sebelum murid menggunakan blok dan minum.", "Guru memberikan empat minit untuk binaan rendah dengan enam blok, kemudian dua minit untuk pasangan menerangkan rumah masing-masing.", "Guru menggunakan minit akhir untuk mengemas dan merekod murid yang belum sempat dinilai bagi mana-mana binaan."], "pupils": ["Murid menyusun blok sendiri menjadi rumah rendah.", "Murid menunjukkan satu bahagian seperti dinding atau bumbung dan memberi penerangan ringkas.", "Murid menghormati binaan rakan dan mengemas blok sendiri apabila diarahkan."], "check": "Kedua-dua binaan dan kedua-dua penerangan ditelusuri bagi murid yang sama.", "resources": ["Blok", "Alas", "Bekas alatan", "Air sendiri"]}, {"name": "Penyejukan badan dan penutup", "minutes": 4, "teacher": ["Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit.", "Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."], "pupils": ["Murid meregang mengikut keselesaan tanpa sentapan.", "Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."], "check": "Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli.", "resources": ["Air minuman", "Ruang rehat"]}], "differentiation": {"support": {"label": "Peneroka", "support_description": "Guru membimbing satu langkah pada satu masa.", "task": "Membina menara pasir dan rumah blok dengan contoh langkah demi langkah.", "materials": ["Ruang pasir sendiri", "Cawan dan sudu", "Enam blok"], "teacher": ["Guru menunjukkan satu tindakan sebelum murid mencuba.", "Beri pilihan bahagian yang mudah disebut; jangan menyiapkan binaan bagi murid."], "pupil_steps": ["Cedok dan padatkan pasir dengan bantuan arahan.", "Bentuk istana kecil dan tunjuk menaranya, kemudian bersihkan tangan.", "Susun blok menjadi rumah rendah di ruang sendiri.", "Tunjuk satu bahagian rumah dan sebut semula bahagian istana pasir."], "product": "Istana pasir dan rumah blok yang dibina murid serta dua penerangan pendek.", "criterion": "Murid mengendalikan kedua-dua bahan sendiri dengan bimbingan; nama bahagian boleh dibantu.", "next_step": "Ulang tindakan acuan atau tapak blok yang masih sukar.", "example": {"teacher": "Yang mana menara istana dan yang mana dinding rumah?", "pupil": "Ini menara pasir. Ini dinding rumah blok."}}, "core": {"label": "Pembina", "support_description": "Murid berlatih berpasangan dan melakukan sendiri.", "task": "Membina dua objek sendiri dan menunjukkan bahagian setiap satu.", "materials": ["Dulang separuh ruang", "Sudu dan cawan", "Enam blok"], "teacher": ["Semak murid tidak mengambil alih ruang atau kerja pasangan.", "Tanya bahagian selepas murid membina, bukan memberi jawapan siap."], "pupil_steps": ["Bentuk istana pasir kecil dengan tapak dan menara.", "Tunjukkan bahagian istana dan cuci tangan.", "Susun rumah rendah menggunakan blok sendiri.", "Terangkan satu bahagian rumah serta bandingkan dengan istana sendiri."], "product": "Dua binaan individu dan penerangan setiap reka bentuk.", "criterion": "Kedua-dua binaan nyata, dengan bahagian yang boleh ditunjukkan.", "next_step": "Perkemas tapak tanpa menambah saiz atau ketinggian.", "example": {"teacher": "Bagaimana rumah kamu boleh berdiri?", "pupil": "Saya susun blok lebar di bawah."}}, "challenge": {"label": "Pencabar", "support_description": "Murid memperkemas satu perkara dalam kemahiran yang sama.", "task": "Memperkemas tapak istana pasir dan rumah blok supaya stabil.", "materials": ["Dulang pasir", "Cawan dan sudu", "Enam blok"], "teacher": ["Kekalkan bilangan bahan; minta satu pembaikan kecil sahaja.", "Semak kestabilan melalui pemerhatian, bukan menggoncang atau menjatuhkan binaan."], "pupil_steps": ["Bina istana pasir dan rapikan tapaknya.", "Tunjuk satu bahagian serta tujuan tapak yang lebar, kemudian cuci tangan.", "Bina rumah blok rendah dengan tapak stabil.", "Terangkan satu bahagian rumah dan satu perkara yang diperbaik pada kedua-dua binaan."], "product": "Dua binaan sendiri dengan satu pembaikan tapak yang mudah.", "criterion": "Tapak diperbaik tanpa binaan tinggi; kedua-dua reka bentuk diterangkan.", "next_step": "Kongsi cara merapikan tapak tanpa menyentuh binaan pasangan.", "example": {"teacher": "Mengapa kamu lebarkan tapaknya?", "pupil": "Supaya istana pasir dan rumah blok lebih stabil."}}}, "differentiation_delivery": {"common_task": "Murid dapat membina istana pasir dan objek blok serta menerangkan binaannya.", "placement": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan.", "teacher_rounds": ["Bantu acuan Peneroka dahulu.", "Semak dua binaan Pembina.", "Bantu pembaikan tapak Pencabar tanpa menambah ketinggian."], "individual_check": "Membina satu istana pasir kecil dan satu objek rumah daripada blok melalui tindakan sendiri.", "flexible_help": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, "pbd": {"method": "Pemerhatian tangan dan hasil individu dalam kedua-dua fasa.", "evidence": "Murid sendiri membina istana pasir dan rumah blok.", "criterion": "Kedua-dua binaan dibuat melalui tindakan murid. Menonton atau kerja pasangan sahaja tidak cukup.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Istana pasir: ____", "Objek blok: ____", "Bantuan / belum dilaksanakan: ____"]}, "pbd_complementary": {"2.9.2": {"method": "Soal jawab individu sambil murid menunjuk hasil sendiri.", "evidence": "Penerangan satu bahagian istana pasir dan satu bahagian rumah blok.", "criterion": "Kedua-dua reka bentuk diterangkan dengan kata mudah atau menunjuk bersama sebutan.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Bahagian istana pasir: ____", "Bahagian objek blok: ____", "Bantuan / belum didengar: ____"]}, "5.2.1": {"method": "Pemerhatian respons sukarela dan pertanyaan ringkas.", "evidence": "Respons sebenar tentang membina dengan pasir dan blok.", "criterion": "Keseronokan dicatat jika terlihat atau disebut; jangan memaksa senyum atau menghukum murid yang sensitif pada pasir.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Respons pasir: ____", "Respons blok: ____", "Keselesaan / susulan: ____"]}}, "intervention": ["Beri masa tambahan pada sesi susulan jika salah satu bahan belum sempat dikendalikan.", "Murid yang sukar menggunakan acuan boleh membentuk pasir dengan sudu; tugasan istana pasir tidak diganti dengan lukisan lalu dianggap selesai."], "book_pages_text": "43", "sp_focus": "", "sp_display": "1.10.2", "complementary": [{"standard_key": "2.9.2", "sp_code": "2.9.2", "sp_text": "Menerangkan reka bentuk istana pasir dan objek yang dibina.", "sk_code": "2.9", "sk_text": "Mengaplikasi strategi dan idea kreatif dalam aktiviti rekreasi dan kesenggangan.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.2.1", "sp_code": "5.2.1", "sp_text": "Mempamerkan rasa seronok melakukan aktiviti baharu dalam Pendidikan Jasmani.", "sk_code": "5.2", "sk_text": "Menunjukkan keyakinan dan tanggungjawab kendiri semasa melakukan aktiviti.", "domain": "afektif", "source_label": ""}], "draft_sha256": "e5e935fefd50b5f5cad3ee5a8835717739c2ba1f4e6472d3e0091fb8b65c2b80"}'::jsonb,'[{"kind": "title", "text": "Minggu 32 Sesi 1 — Istana pasir kecil dan rumah blok"}, {"kind": "subtitle", "text": "Pendidikan Jasmani Tahun 1 | Dua sesi seminggu | 30 minit setiap sesi | R1"}, {"kind": "p", "text": "ID: PJ1-2026B-2S-W32-S1"}, {"kind": "h2", "text": "A. Maklumat pengajaran"}, {"kind": "p", "text": "Guru: ____________________ | Kelas: __________ | Tarikh: __________ | Waktu: __________"}, {"kind": "p", "text": "Unit 6: Mari Bersantai"}, {"kind": "p", "text": "Tajuk buku teks: Saya Kreatif"}, {"kind": "p", "text": "Aktiviti guru: Istana pasir kecil dan rumah blok"}, {"kind": "p", "text": "Rujukan buku teks PJPK Tahun 1, bahagian PJ: muka surat 43."}, {"kind": "p", "text": "Fasa sembilan minit untuk pasir dan peralihan kebersihan; tujuh minit untuk objek blok, penerangan serta pengemasan. Semua termasuk dalam 30 minit."}, {"kind": "h2", "text": "B. Standard dan hasil pembelajaran"}, {"kind": "p", "text": "SK utama 1.10: Melakukan aktiviti rekreasi dan kesenggangan."}, {"kind": "p", "text": "SP utama 1.10.2: Membina istana pasir dan mereka cipta objek menggunakan plastisin atau blok mainan."}, {"kind": "p", "text": "SK sokongan 2.9: Mengaplikasi strategi dan idea kreatif dalam aktiviti rekreasi dan kesenggangan."}, {"kind": "p", "text": "SP sokongan 2.9.2: Menerangkan reka bentuk istana pasir dan objek yang dibina."}, {"kind": "p", "text": "SK sokongan 5.2: Menunjukkan keyakinan dan tanggungjawab kendiri semasa melakukan aktiviti."}, {"kind": "p", "text": "SP sokongan 5.2.1: Mempamerkan rasa seronok melakukan aktiviti baharu dalam Pendidikan Jasmani."}, {"kind": "label", "text": "Objektif"}, {"kind": "p", "text": "Murid dapat membina istana pasir dan objek blok serta menerangkan binaannya."}, {"kind": "label", "text": "Kriteria kejayaan"}, {"kind": "p", "text": "1. Membina satu istana pasir kecil dan satu objek rumah daripada blok melalui tindakan sendiri."}, {"kind": "p", "text": "2. Menunjukkan serta menamakan satu bahagian bagi setiap binaan."}, {"kind": "p", "text": "Pengetahuan sedia ada: Murid pernah menyusun objek. Guru menyemak cara memegang sudu dan blok dengan selamat."}, {"kind": "h2", "text": "C. Alatan, persediaan dan keselamatan"}, {"kind": "label", "text": "Dulang pasir bersih yang sedikit lembap"}, {"kind": "p", "text": "Keperluan: Satu dulang lebar setiap pasangan, dibahagi kepada dua ruang kerja."}, {"kind": "p", "text": "Kegunaan: Setiap murid membina istana pasir sendiri tanpa mengganggu binaan pasangan."}, {"kind": "label", "text": "Cawan acuan dan sudu plastik tumpul"}, {"kind": "p", "text": "Keperluan: Dua cawan dan dua sudu setiap pasangan; satu set setiap murid."}, {"kind": "p", "text": "Kegunaan: Mencedok, memadatkan dan membentuk pasir."}, {"kind": "label", "text": "Blok mainan besar"}, {"kind": "p", "text": "Keperluan: Dua belas blok setiap pasangan; enam bagi setiap murid."}, {"kind": "p", "text": "Kegunaan: Membina objek sendiri di ruang berasingan daripada dulang pasir."}, {"kind": "label", "text": "Kon, alas kerja dan bekas alatan"}, {"kind": "p", "text": "Keperluan: Empat kon di luar ruang berjalan; alas serta bekas setiap pasangan."}, {"kind": "p", "text": "Kegunaan: Menandakan ruang gerak dan mengasingkan pasir daripada laluan."}, {"kind": "label", "text": "Air minuman serta tempat mencuci tangan"}, {"kind": "p", "text": "Keperluan: Botol sendiri; kemudahan basuh tangan dengan sabun tersedia."}, {"kind": "p", "text": "Kegunaan: Rehat, minum selepas tangan dibersihkan dan kebersihan selepas mengendalikan pasir."}, {"kind": "label", "text": "Persediaan guru"}, {"kind": "p", "text": "1. Sediakan pasir sedikit lembap lebih awal; bukan membancuh atau menuang air semasa murid berjalan."}, {"kind": "p", "text": "2. Bahagikan dulang kepada dua ruang dan susun enam blok setiap murid di atas alas berasingan."}, {"kind": "p", "text": "3. Letakkan tempat basuh tangan yang mudah diawasi. Jika satu paip sahaja, kumpulan mencuci bergilir sebelum fasa pasir berakhir; pendekkan pembinaan, bukan abaikan kebersihan."}, {"kind": "label", "text": "Susunan dan giliran murid"}, {"kind": "p", "text": "1. Setiap pasangan berkongsi dulang tetapi mempunyai ruang istana dan set blok sendiri. Kedua-dua murid melakukan kedua-dua binaan, bukan seorang pasir dan seorang blok."}, {"kind": "p", "text": "2. Guru memberi bantuan Peneroka di meja atau alas yang sama. Murid lain membina dengan bahan yang telah disediakan dalam pandangan guru."}, {"kind": "p", "text": "3. Dua minit akhir fasa pasir digunakan untuk mengasingkan alat dan mencuci tangan; masa beralih serta rehat termasuk dalam fasa. Jika giliran basuh tangan lebih panjang, pendekkan masa membina."}, {"kind": "label", "text": "Petunjuk pergerakan"}, {"kind": "p", "text": "1. Cedok sedikit pasir dengan sudu. Padatkan dalam cawan, terbalikkan di ruang sendiri dan angkat cawan perlahan."}, {"kind": "p", "text": "2. Bentuk istana kecil yang rendah; satu menara sudah mencukupi. Jangan meniup atau membaling pasir."}, {"kind": "p", "text": "3. Susun blok dari tapak yang lebar dan stabil. Bina objek rendah; jangan meletakkan blok di atas kepala atau memanjatnya."}, {"kind": "p", "text": "4. Tunjukkan bahagian binaan sendiri dan beri penerangan ringkas, contohnya Ini menara istana; ini dinding rumah."}, {"kind": "label", "text": "BBM"}, {"kind": "p", "text": "1. Dulang pasir bersih yang sedikit lembap — Satu dulang lebar setiap pasangan, dibahagi kepada dua ruang kerja."}, {"kind": "p", "text": "2. Cawan acuan dan sudu plastik tumpul — Dua cawan dan dua sudu setiap pasangan; satu set setiap murid."}, {"kind": "p", "text": "3. Blok mainan besar — Dua belas blok setiap pasangan; enam bagi setiap murid."}, {"kind": "p", "text": "4. Kon, alas kerja dan bekas alatan — Empat kon di luar ruang berjalan; alas serta bekas setiap pasangan."}, {"kind": "p", "text": "5. Air minuman serta tempat mencuci tangan — Botol sendiri; kemudahan basuh tangan dengan sabun tersedia."}, {"kind": "p", "text": "6. Buku teks dan senarai semak pemerhatian guru."}, {"kind": "p", "text": "PAK-21: Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan."}, {"kind": "p", "text": "Nilai: Kerjasama, disiplin dan menjaga keselamatan rakan."}, {"kind": "label", "text": "Keselamatan"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula."}, {"kind": "p", "text": "2. Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan."}, {"kind": "p", "text": "3. Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan."}, {"kind": "p", "text": "4. Pasir mesti bersih, bebas najis, serpihan dan benda tajam serta sedikit lembap supaya tidak berdebu. Jika tidak sesuai, tangguhkan bahagian pasir dan rekod belum dilaksanakan."}, {"kind": "p", "text": "5. Pasir dan blok tidak dimasukkan ke mulut, hidung atau telinga. Tiada tiupan pasir, balingan atau perebutan bahan."}, {"kind": "p", "text": "6. Tangan dibasuh dengan sabun selepas pasir dan sebelum minum atau menyentuh muka. Luka terbuka ditutup mengikut panduan sekolah; murid yang tidak boleh mengendalikan pasir diberi susulan sesuai."}, {"kind": "p", "text": "7. Dulang stabil di atas alas pada permukaan rendah. Bersihkan tumpahan segera dan kosongkan laluan sebelum murid bergerak."}, {"kind": "p", "text": "8. Binaan rendah sahaja; murid tidak memanjat, mengangkat dulang berat atau menjatuhkan blok ke arah rakan."}, {"kind": "p", "text": "Jika cuaca atau ruang tidak sesuai: Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat."}, {"kind": "h2", "text": "D. Langkah PdP"}, {"kind": "h3", "text": "Langkah 1: Persediaan murid dan alatan — 2 minit"}, {"kind": "p", "text": "Minit 0 hingga 2."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan."}, {"kind": "p", "text": "2. Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid memberitahu guru jika tidak sihat."}, {"kind": "p", "text": "2. Murid mengambil tempat yang ditetapkan dan mendengar arahan."}, {"kind": "p", "text": "Semakan: Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan."}, {"kind": "p", "text": "Alatan: Dulang pasir bersih yang sedikit lembap Cawan acuan dan sudu plastik tumpul Blok mainan besar Kon, alas kerja dan bekas alatan Air minuman serta tempat mencuci tangan"}, {"kind": "h3", "text": "Langkah 2: Pemanasan badan — 4 minit"}, {"kind": "p", "text": "Minit 2 hingga 6."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit."}, {"kind": "p", "text": "2. Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid bergerak dalam ruang sendiri tanpa bersentuh."}, {"kind": "p", "text": "2. Murid bernafas seperti biasa dan berehat jika perlu."}, {"kind": "p", "text": "Semakan: Murid bersedia untuk aktiviti tanpa terlalu penat."}, {"kind": "p", "text": "Alatan: Ruang lapang Kon penanda"}, {"kind": "h3", "text": "Langkah 3: Tunjuk dua cara membina — 4 minit"}, {"kind": "p", "text": "Minit 6 hingga 10."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru merujuk arahan BT43 tentang istana pasir dan objek. Guru menunjukkan satu menara menggunakan acuan."}, {"kind": "p", "text": "2. Guru menyusun rumah blok rendah sebagai contoh, kemudian membuka semula susunan supaya murid membina sendiri."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid melihat cara memadat dan mengangkat cawan perlahan."}, {"kind": "p", "text": "2. Murid mengenal ruang serta blok sendiri dan menyebut bahagian yang hendak dibina."}, {"kind": "p", "text": "Semakan: Contoh guru membantu, bukan hasil yang diberikan kepada murid."}, {"kind": "p", "text": "Alatan: Dulang pasir Cawan dan sudu Blok besar"}, {"kind": "h3", "text": "Langkah 4: Bina istana pasir sendiri — 9 minit"}, {"kind": "p", "text": "Minit 10 hingga 19."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memberi dua minit untuk mencuba cedok dan padat."}, {"kind": "p", "text": "2. Guru memberi lima minit untuk setiap murid membentuk istana kecil serta menyebut satu bahagiannya. Bantu satu langkah tanpa membuat seluruh binaan bagi murid."}, {"kind": "p", "text": "3. Gunakan dua minit akhir untuk merapikan pasir, mengasingkan alatan dan mencuci tangan secara bergilir. Sesuaikan giliran paip dan pendekkan masa membina jika perlu."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid mencedok dan memadatkan pasir di cawan sendiri."}, {"kind": "p", "text": "2. Murid membentuk satu menara dan merapikan tapaknya di bahagian dulang sendiri."}, {"kind": "p", "text": "3. Murid menunjuk menara atau tapak sambil menerangkan dengan kata pendek, kemudian mencuci tangan."}, {"kind": "p", "text": "Semakan: Guru mencatat binaan serta penerangan istana setiap murid; foto sahaja tanpa lakuan bukan bukti lengkap."}, {"kind": "p", "text": "Alatan: Pasir Cawan Sudu Air dan sabun"}, {"kind": "h3", "text": "Langkah 5: Bina rumah blok dan ceritakan — 7 minit"}, {"kind": "p", "text": "Minit 19 hingga 26."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Pastikan tangan bersih sebelum murid menggunakan blok dan minum."}, {"kind": "p", "text": "2. Guru memberikan empat minit untuk binaan rendah dengan enam blok, kemudian dua minit untuk pasangan menerangkan rumah masing-masing."}, {"kind": "p", "text": "3. Guru menggunakan minit akhir untuk mengemas dan merekod murid yang belum sempat dinilai bagi mana-mana binaan."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid menyusun blok sendiri menjadi rumah rendah."}, {"kind": "p", "text": "2. Murid menunjukkan satu bahagian seperti dinding atau bumbung dan memberi penerangan ringkas."}, {"kind": "p", "text": "3. Murid menghormati binaan rakan dan mengemas blok sendiri apabila diarahkan."}, {"kind": "p", "text": "Semakan: Kedua-dua binaan dan kedua-dua penerangan ditelusuri bagi murid yang sama."}, {"kind": "p", "text": "Alatan: Blok Alas Bekas alatan Air sendiri"}, {"kind": "h3", "text": "Langkah 6: Penyejukan badan dan penutup — 4 minit"}, {"kind": "p", "text": "Minit 26 hingga 30."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit."}, {"kind": "p", "text": "2. Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid meregang mengikut keselesaan tanpa sentapan."}, {"kind": "p", "text": "2. Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."}, {"kind": "p", "text": "Semakan: Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli."}, {"kind": "p", "text": "Alatan: Air minuman Ruang rehat"}, {"kind": "p", "text": "Jumlah masa: 30 minit."}, {"kind": "label", "text": "Contoh arahan kelas"}, {"kind": "p", "text": "Guru: Bina satu menara di ruang pasir kamu. Selepas itu, bina rumah rendah dengan blok kamu."}, {"kind": "p", "text": "Murid: Murid membina kedua-dua objek sendiri dan menunjuk menara serta dinding."}, {"kind": "p", "text": "Semakan guru: Guru semak tangan murid mengendalikan kedua-dua bahan dan mendengar penerangan setiap binaan."}, {"kind": "h2", "text": "E. PdP terbeza", "anchor": "pdp-PJ1-2026B-2S-W32-S1"}, {"kind": "p", "text": "Tugasan bersama: Murid dapat membina istana pasir dan objek blok serta menerangkan binaannya."}, {"kind": "p", "text": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan."}, {"kind": "label", "text": "Bimbingan guru"}, {"kind": "p", "text": "1. Bantu acuan Peneroka dahulu."}, {"kind": "p", "text": "2. Semak dua binaan Pembina."}, {"kind": "p", "text": "3. Bantu pembaikan tapak Pencabar tanpa menambah ketinggian."}, {"kind": "p", "text": "Semakan individu: Membina satu istana pasir kecil dan satu objek rumah daripada blok melalui tindakan sendiri."}, {"kind": "p", "text": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, {"kind": "h3", "text": "Peneroka"}, {"kind": "p", "text": "Guru membimbing satu langkah pada satu masa."}, {"kind": "p", "text": "Tugasan: Membina menara pasir dan rumah blok dengan contoh langkah demi langkah."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Ruang pasir sendiri"}, {"kind": "p", "text": "2. Cawan dan sudu"}, {"kind": "p", "text": "3. Enam blok"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan satu tindakan sebelum murid mencuba."}, {"kind": "p", "text": "2. Beri pilihan bahagian yang mudah disebut; jangan menyiapkan binaan bagi murid."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Cedok dan padatkan pasir dengan bantuan arahan."}, {"kind": "p", "text": "2. Bentuk istana kecil dan tunjuk menaranya, kemudian bersihkan tangan."}, {"kind": "p", "text": "3. Susun blok menjadi rumah rendah di ruang sendiri."}, {"kind": "p", "text": "4. Tunjuk satu bahagian rumah dan sebut semula bahagian istana pasir."}, {"kind": "p", "text": "Contoh guru: Yang mana menara istana dan yang mana dinding rumah?"}, {"kind": "p", "text": "Contoh respons murid: Ini menara pasir. Ini dinding rumah blok."}, {"kind": "p", "text": "Hasil individu: Istana pasir dan rumah blok yang dibina murid serta dua penerangan pendek."}, {"kind": "p", "text": "Kriteria: Murid mengendalikan kedua-dua bahan sendiri dengan bimbingan; nama bahagian boleh dibantu."}, {"kind": "p", "text": "Susulan: Ulang tindakan acuan atau tapak blok yang masih sukar."}, {"kind": "h3", "text": "Pembina"}, {"kind": "p", "text": "Murid berlatih berpasangan dan melakukan sendiri."}, {"kind": "p", "text": "Tugasan: Membina dua objek sendiri dan menunjukkan bahagian setiap satu."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Dulang separuh ruang"}, {"kind": "p", "text": "2. Sudu dan cawan"}, {"kind": "p", "text": "3. Enam blok"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Semak murid tidak mengambil alih ruang atau kerja pasangan."}, {"kind": "p", "text": "2. Tanya bahagian selepas murid membina, bukan memberi jawapan siap."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Bentuk istana pasir kecil dengan tapak dan menara."}, {"kind": "p", "text": "2. Tunjukkan bahagian istana dan cuci tangan."}, {"kind": "p", "text": "3. Susun rumah rendah menggunakan blok sendiri."}, {"kind": "p", "text": "4. Terangkan satu bahagian rumah serta bandingkan dengan istana sendiri."}, {"kind": "p", "text": "Contoh guru: Bagaimana rumah kamu boleh berdiri?"}, {"kind": "p", "text": "Contoh respons murid: Saya susun blok lebar di bawah."}, {"kind": "p", "text": "Hasil individu: Dua binaan individu dan penerangan setiap reka bentuk."}, {"kind": "p", "text": "Kriteria: Kedua-dua binaan nyata, dengan bahagian yang boleh ditunjukkan."}, {"kind": "p", "text": "Susulan: Perkemas tapak tanpa menambah saiz atau ketinggian."}, {"kind": "h3", "text": "Pencabar"}, {"kind": "p", "text": "Murid memperkemas satu perkara dalam kemahiran yang sama."}, {"kind": "p", "text": "Tugasan: Memperkemas tapak istana pasir dan rumah blok supaya stabil."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Dulang pasir"}, {"kind": "p", "text": "2. Cawan dan sudu"}, {"kind": "p", "text": "3. Enam blok"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Kekalkan bilangan bahan; minta satu pembaikan kecil sahaja."}, {"kind": "p", "text": "2. Semak kestabilan melalui pemerhatian, bukan menggoncang atau menjatuhkan binaan."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Bina istana pasir dan rapikan tapaknya."}, {"kind": "p", "text": "2. Tunjuk satu bahagian serta tujuan tapak yang lebar, kemudian cuci tangan."}, {"kind": "p", "text": "3. Bina rumah blok rendah dengan tapak stabil."}, {"kind": "p", "text": "4. Terangkan satu bahagian rumah dan satu perkara yang diperbaik pada kedua-dua binaan."}, {"kind": "p", "text": "Contoh guru: Mengapa kamu lebarkan tapaknya?"}, {"kind": "p", "text": "Contoh respons murid: Supaya istana pasir dan rumah blok lebih stabil."}, {"kind": "p", "text": "Hasil individu: Dua binaan sendiri dengan satu pembaikan tapak yang mudah."}, {"kind": "p", "text": "Kriteria: Tapak diperbaik tanpa binaan tinggi; kedua-dua reka bentuk diterangkan."}, {"kind": "p", "text": "Susulan: Kongsi cara merapikan tapak tanpa menyentuh binaan pasangan."}, {"kind": "h2", "text": "F. Pentaksiran Bilik Darjah"}, {"kind": "h3", "text": "PBD utama — SP 1.10.2"}, {"kind": "p", "text": "Kaedah: Pemerhatian tangan dan hasil individu dalam kedua-dua fasa."}, {"kind": "p", "text": "Bukti: Murid sendiri membina istana pasir dan rumah blok."}, {"kind": "p", "text": "Kriteria: Kedua-dua binaan dibuat melalui tindakan murid. Menonton atau kerja pasangan sahaja tidak cukup."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Istana pasir: ____"}, {"kind": "p", "text": "2. Objek blok: ____"}, {"kind": "p", "text": "3. Bantuan / belum dilaksanakan: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 2.9.2"}, {"kind": "p", "text": "Kaedah: Soal jawab individu sambil murid menunjuk hasil sendiri."}, {"kind": "p", "text": "Bukti: Penerangan satu bahagian istana pasir dan satu bahagian rumah blok."}, {"kind": "p", "text": "Kriteria: Kedua-dua reka bentuk diterangkan dengan kata mudah atau menunjuk bersama sebutan."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Bahagian istana pasir: ____"}, {"kind": "p", "text": "2. Bahagian objek blok: ____"}, {"kind": "p", "text": "3. Bantuan / belum didengar: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 5.2.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian respons sukarela dan pertanyaan ringkas."}, {"kind": "p", "text": "Bukti: Respons sebenar tentang membina dengan pasir dan blok."}, {"kind": "p", "text": "Kriteria: Keseronokan dicatat jika terlihat atau disebut; jangan memaksa senyum atau menghukum murid yang sensitif pada pasir."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Respons pasir: ____"}, {"kind": "p", "text": "2. Respons blok: ____"}, {"kind": "p", "text": "3. Keselesaan / susulan: ____"}, {"kind": "h2", "text": "G. Refleksi dan intervensi"}, {"kind": "p", "text": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________."}, {"kind": "label", "text": "Intervensi"}, {"kind": "p", "text": "1. Beri masa tambahan pada sesi susulan jika salah satu bahan belum sempat dikendalikan."}, {"kind": "p", "text": "2. Murid yang sukar menggunakan acuan boleh membentuk pasir dengan sudu; tugasan istana pasir tidak diganti dengan lukisan lalu dianggap selesai."}]'::jsonb,'{"source_hold": "", "adaptation_note": "Guru mengesahkan pasir bersih dalam dulang dan plastisin atau blok. Blok dipilih daripada pilihan sumber. Setiap murid membina istana pasir dan objek blok dalam setiap sesi; bukan satu bahan bagi satu kumpulan. Tugas ringkas dengan bahagian individu dan penerangan sendiri.", "source_images_verified": true, "audio_verified": false, "ba_verified": false, "classroom_trial_performed": false}'::jsonb),
  ('PJ1-2026B-2S-W32-S2','pj',1,2026,32,2,30,'1.10.2',array[43]::int[],'5647bab10a8d267b5a4e1a80f2ab48db0e9a10544284c70a44e089fbfaa7714b','73f8c9a5d5fb42f50eb7eff31b1de87d393f493847998715227eae4ef27169e0','715d2dd93e616381f7de4fb5e317e008bae7007088b12831c3d9d17a2be5d6d7','ACCEPTED_FROM_DOWNLOADED_CATATAN',false,'{"id": "PJ1-2026B-2S-W32-S2", "subject": "Pendidikan Jasmani", "year": 1, "week": 32, "session": 2, "revision": "PJ1-30MIN-REVIEW-R1", "date": "", "teaching_time": "", "minutes": 30, "sessions_per_week": 2, "weekly_minutes": 60, "title": "Saya Kreatif", "source_title": "Saya Kreatif", "unit": "Unit 6: Mari Bersantai", "source_row_id": "PJ1-RPT2026-T11-R2", "source_row_literal": ["32\n\nKump A: 13.09.2026-17.09.2026\n\nKump B:\n14.09.2026-18.09.2026", "6: MARI BERSANTAI\nSAYA KREATIF", "1.10 Melakukan aktiviti rekreasi dan kesenggangan\n2.9 Mengaplikasi strategi dan idea kreatif dalam aktiviti rekreasi dan   kesenggangan\n5.2 Menunjukkan keyakinan dan tanggungjawab kendiri semasa melakukan aktiviti.", "1.10.2 Membina istana pasir, dan mereka cipta objek menggunakan plastisin atau blok mainan.\n\n2.9.2 Menerangkan reka bentuk istana pasir dan objek yang dibina.\n\n5.2.1 Mempamerkan rasa seronok melakukan aktiviti baharu dalam Pendidikan Jasmani.", "Pemerhatian /\nPentaksiran \n\n\nEMK: \nKreativiti & Inovasi\n\nBT m/s 43"], "rpt_original_page_literal": "43", "source_pages": [43], "source_pdf_pages": [51], "rpt_book_pages": "43", "main_standard_key": "1.10.2", "sk_code": "1.10", "sk_text": "Melakukan aktiviti rekreasi dan kesenggangan.", "sp_code": "1.10.2", "sp_text": "Membina istana pasir dan mereka cipta objek menggunakan plastisin atau blok mainan.", "complementary_standards": [{"standard_key": "2.9.2", "sp_code": "2.9.2", "sp_text": "Menerangkan reka bentuk istana pasir dan objek yang dibina.", "sk_code": "2.9", "sk_text": "Mengaplikasi strategi dan idea kreatif dalam aktiviti rekreasi dan kesenggangan.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.2.1", "sp_code": "5.2.1", "sp_text": "Mempamerkan rasa seronok melakukan aktiviti baharu dalam Pendidikan Jasmani.", "sk_code": "5.2", "sk_text": "Menunjukkan keyakinan dan tanggungjawab kendiri semasa melakukan aktiviti.", "domain": "afektif", "source_label": ""}], "source_task": "Membaiki binaan pasir dan mencipta objek blok", "authoring_focus": "Membaiki binaan pasir dan mencipta objek blok", "source_hold": "Teks RPT, DSKP dan buku dibaca. Semakan imej guling BT35 dan kod DSKP hlm70 terhalang ralat402; OCR dan teks salinan menyokong kod berulang, bukan kelulusan visual. Guru perlu menilai postur, alat dan kesediaan setiap murid.", "practical_required": true, "warmup_required": true, "cooldown_required": true, "facility_replacement": false, "facility_replacement_note": "", "source_subset_focus": false, "source_subset_note": "", "adaptation_note": "Guru mengesahkan pasir bersih dalam dulang dan plastisin atau blok. Blok dipilih daripada pilihan sumber. Setiap murid membina istana pasir dan objek blok dalam setiap sesi; bukan satu bahan bagi satu kumpulan. Tugas ringkas dengan bahagian individu dan penerangan sendiri.", "privacy_adaptation": false, "privacy_note": "", "held_standards": [], "source_code_conflict": false, "source_code_note": "", "unperformed_literal_elements": [], "source_mapping_review": "20 RPH, dua sesi30minit seminggu dibenarkan guru. S1/S2 ialah cadangan pecahan RPT mingguan, bukan nombor sesi yang tercetak dalam RPT.", "routine_book_pages": [46, 47], "active": false, "production_write_performed": false, "presentation_review": "PENDING_TEACHER_REVIEW", "safety": ["Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula.", "Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan.", "Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan.", "Pasir mesti bersih, bebas najis, serpihan dan benda tajam serta sedikit lembap supaya tidak berdebu. Jika tidak sesuai, tangguhkan bahagian pasir dan rekod belum dilaksanakan.", "Pasir dan blok tidak dimasukkan ke mulut, hidung atau telinga. Tiada tiupan pasir, balingan atau perebutan bahan.", "Tangan dibasuh dengan sabun selepas pasir dan sebelum minum atau menyentuh muka. Luka terbuka ditutup mengikut panduan sekolah; murid yang tidak boleh mengendalikan pasir diberi susulan sesuai.", "Dulang stabil di atas alas pada permukaan rendah. Bersihkan tumpahan segera dan kosongkan laluan sebelum murid bergerak.", "Binaan rendah sahaja; murid tidak memanjat, mengangkat dulang berat atau menjatuhkan blok ke arah rakan."], "weather_plan": "Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat.", "reflection": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________.", "activity_name": "Istana berpintu dan jambatan blok", "objective": "Murid dapat membina istana pasir dan objek blok dengan reka bentuk sendiri yang mudah.", "success_criteria": ["Membina satu istana pasir berpintu dan satu objek jambatan rendah menggunakan blok sendiri.", "Menerangkan satu bahagian atau pembaikan pada setiap binaan."], "prior_knowledge": "Murid pernah membina menara pasir dan objek blok. Guru memberi contoh semula kepada murid yang belum mencuba.", "equipment": [{"item": "Dulang pasir bersih yang sedikit lembap", "quantity": "Satu dulang lebar setiap pasangan, dibahagi kepada dua ruang kerja.", "use": "Setiap murid membina istana pasir sendiri tanpa mengganggu binaan pasangan."}, {"item": "Cawan acuan dan sudu plastik tumpul", "quantity": "Dua cawan dan dua sudu setiap pasangan; satu set setiap murid.", "use": "Mencedok, memadatkan dan membentuk pasir."}, {"item": "Blok mainan besar", "quantity": "Dua belas blok setiap pasangan; enam bagi setiap murid.", "use": "Membina objek sendiri di ruang berasingan daripada dulang pasir."}, {"item": "Kon, alas kerja dan bekas alatan", "quantity": "Empat kon di luar ruang berjalan; alas serta bekas setiap pasangan.", "use": "Menandakan ruang gerak dan mengasingkan pasir daripada laluan."}, {"item": "Air minuman serta tempat mencuci tangan", "quantity": "Botol sendiri; kemudahan basuh tangan dengan sabun tersedia.", "use": "Rehat, minum selepas tangan dibersihkan dan kebersihan selepas mengendalikan pasir."}], "preparation": ["Sediakan dulang pasir bersih sedikit lembap, dua ruang kerja dan alat sendiri seperti sesi pertama.", "Asingkan enam blok besar setiap murid. Sediakan contoh jambatan rendah daripada dua sokongan dan blok penghubung, bukan jambatan yang boleh dipijak.", "Susun giliran basuh tangan dalam pandangan guru. Pendekkan masa membina jika perlu supaya kebersihan dan pertukaran tetap sempat."], "organisation": ["Murid berpasangan tetapi membina istana pasir dan objek blok masing-masing. Binaan pasangan tidak dikira sebagai hasil murid yang hanya melihat.", "Guru membimbing Peneroka pada cara membentuk pintu di hadapan istana, kemudian menyemak semua ruang blok.", "Setiap murid menerangkan kedua-dua binaan kepada guru atau pasangan pada gilirannya; guru mencatat siapa belum didengar."], "movement_cues": ["Bentukkan satu atau dua menara pasir yang rendah. Tinggalkan ruang di hadapan sebagai pintu masuk; tidak perlu mengorek terowong yang meruntuhkan binaan.", "Rapikan bahagian yang runtuh dengan menambah sedikit pasir pada tapak dan memadatkan perlahan, bukan membaling pasir.", "Letakkan dua sokongan blok rendah dan hubungkan dengan blok yang sesuai. Jika bentuk blok tidak dapat merentang, susun jambatan rendah yang ditiru melalui bentuk keseluruhan; jangan paksa blok bersambung.", "Tunjukkan pintu istana dan sokongan jambatan. Jelaskan dengan kata mudah seperti untuk masuk atau supaya tidak jatuh."], "timing_note": "Sembilan minit untuk istana pasir dan kebersihan; tujuh minit untuk objek blok serta penerangan. Pertukaran, rehat dan penyejukan berada dalam 30 minit.", "values": "Kerjasama, disiplin dan menjaga keselamatan rakan.", "classroom_example": {"teacher_says": "Di manakah pintu istana kamu? Selepas cuci tangan, tunjuk sokongan jambatan blok kamu.", "pupils_do": "Murid menunjukkan pintu dan sokongan pada dua binaan sendiri.", "teacher_checks": "Guru menilai dua tindakan membina dan dua penerangan, bukan kecantikan atau saiz."}, "bbm": ["Dulang pasir bersih yang sedikit lembap — Satu dulang lebar setiap pasangan, dibahagi kepada dua ruang kerja.", "Cawan acuan dan sudu plastik tumpul — Dua cawan dan dua sudu setiap pasangan; satu set setiap murid.", "Blok mainan besar — Dua belas blok setiap pasangan; enam bagi setiap murid.", "Kon, alas kerja dan bekas alatan — Empat kon di luar ruang berjalan; alas serta bekas setiap pasangan.", "Air minuman serta tempat mencuci tangan — Botol sendiri; kemudahan basuh tangan dengan sabun tersedia.", "Buku teks dan senarai semak pemerhatian guru."], "pak21": "Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan.", "phases": [{"name": "Persediaan murid dan alatan", "minutes": 2, "teacher": ["Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan.", "Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."], "pupils": ["Murid memberitahu guru jika tidak sihat.", "Murid mengambil tempat yang ditetapkan dan mendengar arahan."], "check": "Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan.", "resources": ["Dulang pasir bersih yang sedikit lembap", "Cawan acuan dan sudu plastik tumpul", "Blok mainan besar", "Kon, alas kerja dan bekas alatan", "Air minuman serta tempat mencuci tangan"]}, {"name": "Pemanasan badan", "minutes": 4, "teacher": ["Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit.", "Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."], "pupils": ["Murid bergerak dalam ruang sendiri tanpa bersentuh.", "Murid bernafas seperti biasa dan berehat jika perlu."], "check": "Murid bersedia untuk aktiviti tanpa terlalu penat.", "resources": ["Ruang lapang", "Kon penanda"]}, {"name": "Contoh bahagian dan pembaikan", "minutes": 4, "teacher": ["Guru menunjukkan ruang pintu di hadapan istana pasir kecil.", "Guru menunjukkan dua sokongan jambatan blok rendah dan cara meletak penghubung dengan perlahan. Beritahu murid bahawa objek itu tidak dipijak."], "pupils": ["Murid menunjuk tempat pintu pada contoh guru.", "Murid mengenal blok sokongan dan penghubung tanpa mengambil binaan guru sebagai hasil sendiri."], "check": "Murid tahu dua binaan yang akan dibuat dan bahagian yang diterangkan.", "resources": ["Dulang pasir", "Cawan dan sudu", "Blok"]}, {"name": "Bina dan baiki istana berpintu", "minutes": 9, "teacher": ["Berikan dua minit untuk membentuk menara rendah dengan acuan.", "Gunakan lima minit untuk menambah ruang pintu dan merapikan tapak. Guru bertanya tentang satu bahagian setiap murid.", "Gunakan dua minit akhir untuk mengasingkan alat dan mencuci tangan bergilir. Jika giliran paip lebih lama, kurangkan pembinaan, bukan masa kebersihan."], "pupils": ["Murid membentuk istana pasir di ruang sendiri.", "Murid meninggalkan ruang pintu dan membaiki tapak yang runtuh dengan perlahan.", "Murid menerangkan pintu atau tapak, kemudian mencuci tangan sebelum ke blok atau minum."], "check": "Setiap murid mengendalikan pasir; pembaikan kecil diterima tanpa tuntutan binaan besar.", "resources": ["Pasir lembap", "Cawan", "Sudu", "Air dan sabun"]}, {"name": "Cipta jambatan blok rendah", "minutes": 7, "teacher": ["Pastikan tangan murid bersih. Berikan empat minit untuk membina objek jambatan rendah dengan blok sendiri.", "Gunakan dua minit untuk murid bergilir menunjukkan sokongan atau penghubung dan satu sebab ringkas.", "Gunakan minit akhir untuk mengemas dan mencatat bahagian istana atau blok yang belum diperhatikan."], "pupils": ["Murid menyusun sokongan dan penghubung jambatan tanpa memanjatnya.", "Murid menerangkan satu bahagian objek sendiri dan mendengar pasangan.", "Murid mengemas blok apabila diarahkan serta menyatakan bantuan yang masih diperlukan."], "check": "Kedua-dua reka bentuk diterangkan oleh murid yang sama; hasil kumpulan bukan bukti semua murid.", "resources": ["Blok besar", "Alas", "Bekas alatan", "Air sendiri"]}, {"name": "Penyejukan badan dan penutup", "minutes": 4, "teacher": ["Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit.", "Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."], "pupils": ["Murid meregang mengikut keselesaan tanpa sentapan.", "Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."], "check": "Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli.", "resources": ["Air minuman", "Ruang rehat"]}], "differentiation": {"support": {"label": "Peneroka", "support_description": "Guru membimbing satu langkah pada satu masa.", "task": "Membentuk istana berpintu dan jambatan blok dengan tunjuk cara ringkas.", "materials": ["Ruang pasir sendiri", "Cawan dan sudu", "Enam blok"], "teacher": ["Guru menunjukkan ruang pintu tanpa mengorek terowong.", "Guru meletakkan contoh di sisinya sendiri dan meminta murid menyusun bahan sendiri."], "pupil_steps": ["Bentuk istana pasir rendah dengan acuan atau sudu.", "Tunjuk ruang pintu dan sebut untuk masuk, kemudian cuci tangan.", "Susun dua sokongan dan penghubung objek blok dengan bimbingan.", "Tunjuk bahagian jambatan dan sebut semula bahagian istana sendiri."], "product": "Istana pasir serta objek blok sendiri dan dua penerangan pendek.", "criterion": "Kedua-dua bahan dikendalikan murid dengan bantuan; bahagian dapat ditunjuk dan disebut.", "next_step": "Ulang satu bentuk asas bagi bahan yang masih sukar digunakan.", "example": {"teacher": "Yang mana pintu istana? Yang mana sokongan jambatan?", "pupil": "Ini pintu pasir. Blok di bawah ini menyokong jambatan."}}, "core": {"label": "Pembina", "support_description": "Murid berlatih berpasangan dan melakukan sendiri.", "task": "Membina dua reka bentuk dan menerangkan bahagiannya.", "materials": ["Dulang dua ruang", "Cawan dan sudu", "Blok sendiri"], "teacher": ["Pastikan murid mengendalikan kedua-dua bahan pada gilirannya.", "Tanya bahagian yang dipilih tanpa menuntut penerangan panjang."], "pupil_steps": ["Bentuk istana pasir dengan ruang pintu di hadapan.", "Rapikan tapak dan terangkan satu bahagian, kemudian cuci tangan.", "Bina jambatan rendah menggunakan blok sendiri.", "Terangkan satu sokongan atau penghubung serta bandingkan dengan istana pasir sendiri."], "product": "Dua binaan individu dengan penerangan setiap satu.", "criterion": "Bahagian yang diterangkan benar-benar ada pada binaan; hasil sendiri, bukan salinan catatan pasangan.", "next_step": "Perkemas satu sambungan blok atau tapak pasir tanpa menambah tinggi.", "example": {"teacher": "Mengapa ada dua sokongan pada jambatan?", "pupil": "Supaya bahagian penghubung dapat diletakkan di atasnya."}}, "challenge": {"label": "Pencabar", "support_description": "Murid memperkemas satu perkara dalam kemahiran yang sama.", "task": "Membaiki satu bahagian istana pasir dan jambatan blok supaya stabil.", "materials": ["Dulang pasir", "Sudu", "Enam blok"], "teacher": ["Minta murid memilih satu pembaikan pada setiap binaan dalam bahan yang sama.", "Semak pembaikan tanpa menggoncang atau menguji dengan beban."], "pupil_steps": ["Bina istana pasir dan pilih bahagian tapak atau pintu untuk dirapikan.", "Terangkan pembaikan pada istana, kemudian cuci tangan.", "Bina objek jambatan dan laras satu sokongan supaya lebih stabil.", "Terangkan pembaikan jambatan serta satu perbezaan daripada istana pasir."], "product": "Dua binaan dan dua penerangan pembaikan kecil.", "criterion": "Pembaikan selamat dibuat sendiri; tiada ujian beban atau binaan tinggi.", "next_step": "Kongsi idea dengan kata-kata tanpa menyentuh binaan rakan.", "example": {"teacher": "Apakah yang kamu ubah?", "pupil": "Saya ratakan tapak istana dan rapatkan sokongan jambatan."}}}, "differentiation_delivery": {"common_task": "Murid dapat membina istana pasir dan objek blok dengan reka bentuk sendiri yang mudah.", "placement": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan.", "teacher_rounds": ["Bantu Peneroka membentuk bahagian mudah.", "Semak dua penerangan Pembina.", "Dengar pembaikan Pencabar tanpa menambah beban atau saiz."], "individual_check": "Membina satu istana pasir berpintu dan satu objek jambatan rendah menggunakan blok sendiri.", "flexible_help": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, "pbd": {"method": "Pemerhatian tindakan membina dan hasil individu.", "evidence": "Istana pasir berpintu serta objek blok yang dibuat murid sendiri.", "criterion": "Kedua-dua binaan wujud melalui tindakan murid; tahap bantuan dicatat.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Istana pasir dan tindakan sendiri: ____", "Objek blok dan tindakan sendiri: ____", "Bantuan / belum mendapat giliran: ____"]}, "pbd_complementary": {"2.9.2": {"method": "Soal jawab individu tentang kedua-dua hasil.", "evidence": "Penerangan pintu atau tapak istana pasir dan bahagian jambatan blok.", "criterion": "Murid menerangkan satu bahagian atau pembaikan bagi setiap reka bentuk.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Penerangan istana pasir: ____", "Penerangan objek blok: ____", "Kata bantu / belum didengar: ____"]}, "5.2.1": {"method": "Pemerhatian respons sukarela semasa membina.", "evidence": "Kata atau isyarat sebenar tentang membina pasir dan blok.", "criterion": "Respons sebenar dicatat; sensitiviti terhadap bahan dan keperluan rehat dihormati.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Respons pasir: ____", "Respons blok: ____", "Keselesaan / susulan: ____"]}}, "intervention": ["Jika binaan belum stabil, guna menara pasir tunggal dan objek blok yang rendah sebagai ansur maju.", "Jadualkan susulan bagi murid yang belum melakukan salah satu bahan atau belum menerangkan salah satu reka bentuk."], "book_pages_text": "43", "sp_focus": "", "sp_display": "1.10.2", "complementary": [{"standard_key": "2.9.2", "sp_code": "2.9.2", "sp_text": "Menerangkan reka bentuk istana pasir dan objek yang dibina.", "sk_code": "2.9", "sk_text": "Mengaplikasi strategi dan idea kreatif dalam aktiviti rekreasi dan kesenggangan.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.2.1", "sp_code": "5.2.1", "sp_text": "Mempamerkan rasa seronok melakukan aktiviti baharu dalam Pendidikan Jasmani.", "sk_code": "5.2", "sk_text": "Menunjukkan keyakinan dan tanggungjawab kendiri semasa melakukan aktiviti.", "domain": "afektif", "source_label": ""}], "draft_sha256": "6e6fe8daa5c2311bb18cb9fc7c951cb5237f5cc0a8a0795c6ba6a70160bce48a"}'::jsonb,'[{"kind": "title", "text": "Minggu 32 Sesi 2 — Istana berpintu dan jambatan blok"}, {"kind": "subtitle", "text": "Pendidikan Jasmani Tahun 1 | Dua sesi seminggu | 30 minit setiap sesi | R1"}, {"kind": "p", "text": "ID: PJ1-2026B-2S-W32-S2"}, {"kind": "h2", "text": "A. Maklumat pengajaran"}, {"kind": "p", "text": "Guru: ____________________ | Kelas: __________ | Tarikh: __________ | Waktu: __________"}, {"kind": "p", "text": "Unit 6: Mari Bersantai"}, {"kind": "p", "text": "Tajuk buku teks: Saya Kreatif"}, {"kind": "p", "text": "Aktiviti guru: Istana berpintu dan jambatan blok"}, {"kind": "p", "text": "Rujukan buku teks PJPK Tahun 1, bahagian PJ: muka surat 43."}, {"kind": "p", "text": "Sembilan minit untuk istana pasir dan kebersihan; tujuh minit untuk objek blok serta penerangan. Pertukaran, rehat dan penyejukan berada dalam 30 minit."}, {"kind": "h2", "text": "B. Standard dan hasil pembelajaran"}, {"kind": "p", "text": "SK utama 1.10: Melakukan aktiviti rekreasi dan kesenggangan."}, {"kind": "p", "text": "SP utama 1.10.2: Membina istana pasir dan mereka cipta objek menggunakan plastisin atau blok mainan."}, {"kind": "p", "text": "SK sokongan 2.9: Mengaplikasi strategi dan idea kreatif dalam aktiviti rekreasi dan kesenggangan."}, {"kind": "p", "text": "SP sokongan 2.9.2: Menerangkan reka bentuk istana pasir dan objek yang dibina."}, {"kind": "p", "text": "SK sokongan 5.2: Menunjukkan keyakinan dan tanggungjawab kendiri semasa melakukan aktiviti."}, {"kind": "p", "text": "SP sokongan 5.2.1: Mempamerkan rasa seronok melakukan aktiviti baharu dalam Pendidikan Jasmani."}, {"kind": "label", "text": "Objektif"}, {"kind": "p", "text": "Murid dapat membina istana pasir dan objek blok dengan reka bentuk sendiri yang mudah."}, {"kind": "label", "text": "Kriteria kejayaan"}, {"kind": "p", "text": "1. Membina satu istana pasir berpintu dan satu objek jambatan rendah menggunakan blok sendiri."}, {"kind": "p", "text": "2. Menerangkan satu bahagian atau pembaikan pada setiap binaan."}, {"kind": "p", "text": "Pengetahuan sedia ada: Murid pernah membina menara pasir dan objek blok. Guru memberi contoh semula kepada murid yang belum mencuba."}, {"kind": "h2", "text": "C. Alatan, persediaan dan keselamatan"}, {"kind": "label", "text": "Dulang pasir bersih yang sedikit lembap"}, {"kind": "p", "text": "Keperluan: Satu dulang lebar setiap pasangan, dibahagi kepada dua ruang kerja."}, {"kind": "p", "text": "Kegunaan: Setiap murid membina istana pasir sendiri tanpa mengganggu binaan pasangan."}, {"kind": "label", "text": "Cawan acuan dan sudu plastik tumpul"}, {"kind": "p", "text": "Keperluan: Dua cawan dan dua sudu setiap pasangan; satu set setiap murid."}, {"kind": "p", "text": "Kegunaan: Mencedok, memadatkan dan membentuk pasir."}, {"kind": "label", "text": "Blok mainan besar"}, {"kind": "p", "text": "Keperluan: Dua belas blok setiap pasangan; enam bagi setiap murid."}, {"kind": "p", "text": "Kegunaan: Membina objek sendiri di ruang berasingan daripada dulang pasir."}, {"kind": "label", "text": "Kon, alas kerja dan bekas alatan"}, {"kind": "p", "text": "Keperluan: Empat kon di luar ruang berjalan; alas serta bekas setiap pasangan."}, {"kind": "p", "text": "Kegunaan: Menandakan ruang gerak dan mengasingkan pasir daripada laluan."}, {"kind": "label", "text": "Air minuman serta tempat mencuci tangan"}, {"kind": "p", "text": "Keperluan: Botol sendiri; kemudahan basuh tangan dengan sabun tersedia."}, {"kind": "p", "text": "Kegunaan: Rehat, minum selepas tangan dibersihkan dan kebersihan selepas mengendalikan pasir."}, {"kind": "label", "text": "Persediaan guru"}, {"kind": "p", "text": "1. Sediakan dulang pasir bersih sedikit lembap, dua ruang kerja dan alat sendiri seperti sesi pertama."}, {"kind": "p", "text": "2. Asingkan enam blok besar setiap murid. Sediakan contoh jambatan rendah daripada dua sokongan dan blok penghubung, bukan jambatan yang boleh dipijak."}, {"kind": "p", "text": "3. Susun giliran basuh tangan dalam pandangan guru. Pendekkan masa membina jika perlu supaya kebersihan dan pertukaran tetap sempat."}, {"kind": "label", "text": "Susunan dan giliran murid"}, {"kind": "p", "text": "1. Murid berpasangan tetapi membina istana pasir dan objek blok masing-masing. Binaan pasangan tidak dikira sebagai hasil murid yang hanya melihat."}, {"kind": "p", "text": "2. Guru membimbing Peneroka pada cara membentuk pintu di hadapan istana, kemudian menyemak semua ruang blok."}, {"kind": "p", "text": "3. Setiap murid menerangkan kedua-dua binaan kepada guru atau pasangan pada gilirannya; guru mencatat siapa belum didengar."}, {"kind": "label", "text": "Petunjuk pergerakan"}, {"kind": "p", "text": "1. Bentukkan satu atau dua menara pasir yang rendah. Tinggalkan ruang di hadapan sebagai pintu masuk; tidak perlu mengorek terowong yang meruntuhkan binaan."}, {"kind": "p", "text": "2. Rapikan bahagian yang runtuh dengan menambah sedikit pasir pada tapak dan memadatkan perlahan, bukan membaling pasir."}, {"kind": "p", "text": "3. Letakkan dua sokongan blok rendah dan hubungkan dengan blok yang sesuai. Jika bentuk blok tidak dapat merentang, susun jambatan rendah yang ditiru melalui bentuk keseluruhan; jangan paksa blok bersambung."}, {"kind": "p", "text": "4. Tunjukkan pintu istana dan sokongan jambatan. Jelaskan dengan kata mudah seperti untuk masuk atau supaya tidak jatuh."}, {"kind": "label", "text": "BBM"}, {"kind": "p", "text": "1. Dulang pasir bersih yang sedikit lembap — Satu dulang lebar setiap pasangan, dibahagi kepada dua ruang kerja."}, {"kind": "p", "text": "2. Cawan acuan dan sudu plastik tumpul — Dua cawan dan dua sudu setiap pasangan; satu set setiap murid."}, {"kind": "p", "text": "3. Blok mainan besar — Dua belas blok setiap pasangan; enam bagi setiap murid."}, {"kind": "p", "text": "4. Kon, alas kerja dan bekas alatan — Empat kon di luar ruang berjalan; alas serta bekas setiap pasangan."}, {"kind": "p", "text": "5. Air minuman serta tempat mencuci tangan — Botol sendiri; kemudahan basuh tangan dengan sabun tersedia."}, {"kind": "p", "text": "6. Buku teks dan senarai semak pemerhatian guru."}, {"kind": "p", "text": "PAK-21: Murid berlatih berpasangan atau dalam kumpulan kecil. Setiap murid mendapat giliran sendiri. Rakan memberi teguran ringkas secara sopan tanpa mengambil alih tugasan."}, {"kind": "p", "text": "Nilai: Kerjasama, disiplin dan menjaga keselamatan rakan."}, {"kind": "label", "text": "Keselamatan"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula."}, {"kind": "p", "text": "2. Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan."}, {"kind": "p", "text": "3. Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan."}, {"kind": "p", "text": "4. Pasir mesti bersih, bebas najis, serpihan dan benda tajam serta sedikit lembap supaya tidak berdebu. Jika tidak sesuai, tangguhkan bahagian pasir dan rekod belum dilaksanakan."}, {"kind": "p", "text": "5. Pasir dan blok tidak dimasukkan ke mulut, hidung atau telinga. Tiada tiupan pasir, balingan atau perebutan bahan."}, {"kind": "p", "text": "6. Tangan dibasuh dengan sabun selepas pasir dan sebelum minum atau menyentuh muka. Luka terbuka ditutup mengikut panduan sekolah; murid yang tidak boleh mengendalikan pasir diberi susulan sesuai."}, {"kind": "p", "text": "7. Dulang stabil di atas alas pada permukaan rendah. Bersihkan tumpahan segera dan kosongkan laluan sebelum murid bergerak."}, {"kind": "p", "text": "8. Binaan rendah sahaja; murid tidak memanjat, mengangkat dulang berat atau menjatuhkan blok ke arah rakan."}, {"kind": "p", "text": "Jika cuaca atau ruang tidak sesuai: Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat."}, {"kind": "h2", "text": "D. Langkah PdP"}, {"kind": "h3", "text": "Langkah 1: Persediaan murid dan alatan — 2 minit"}, {"kind": "p", "text": "Minit 0 hingga 2."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid dan alatan."}, {"kind": "p", "text": "2. Guru menerangkan tempat mula, laluan aktiviti dan arahan berhenti."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid memberitahu guru jika tidak sihat."}, {"kind": "p", "text": "2. Murid mengambil tempat yang ditetapkan dan mendengar arahan."}, {"kind": "p", "text": "Semakan: Semua murid tahu tempat menunggu dan boleh berhenti apabila diarahkan."}, {"kind": "p", "text": "Alatan: Dulang pasir bersih yang sedikit lembap Cawan acuan dan sudu plastik tumpul Blok mainan besar Kon, alas kerja dan bekas alatan Air minuman serta tempat mencuci tangan"}, {"kind": "h3", "text": "Langkah 2: Pemanasan badan — 4 minit"}, {"kind": "p", "text": "Minit 2 hingga 6."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan setempat dan langkah ke sisi selama dua minit."}, {"kind": "p", "text": "2. Guru membimbing gerakan ringan bahu, tangan, buku lali dan lutut selama dua minit."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid bergerak dalam ruang sendiri tanpa bersentuh."}, {"kind": "p", "text": "2. Murid bernafas seperti biasa dan berehat jika perlu."}, {"kind": "p", "text": "Semakan: Murid bersedia untuk aktiviti tanpa terlalu penat."}, {"kind": "p", "text": "Alatan: Ruang lapang Kon penanda"}, {"kind": "h3", "text": "Langkah 3: Contoh bahagian dan pembaikan — 4 minit"}, {"kind": "p", "text": "Minit 6 hingga 10."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan ruang pintu di hadapan istana pasir kecil."}, {"kind": "p", "text": "2. Guru menunjukkan dua sokongan jambatan blok rendah dan cara meletak penghubung dengan perlahan. Beritahu murid bahawa objek itu tidak dipijak."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid menunjuk tempat pintu pada contoh guru."}, {"kind": "p", "text": "2. Murid mengenal blok sokongan dan penghubung tanpa mengambil binaan guru sebagai hasil sendiri."}, {"kind": "p", "text": "Semakan: Murid tahu dua binaan yang akan dibuat dan bahagian yang diterangkan."}, {"kind": "p", "text": "Alatan: Dulang pasir Cawan dan sudu Blok"}, {"kind": "h3", "text": "Langkah 4: Bina dan baiki istana berpintu — 9 minit"}, {"kind": "p", "text": "Minit 10 hingga 19."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Berikan dua minit untuk membentuk menara rendah dengan acuan."}, {"kind": "p", "text": "2. Gunakan lima minit untuk menambah ruang pintu dan merapikan tapak. Guru bertanya tentang satu bahagian setiap murid."}, {"kind": "p", "text": "3. Gunakan dua minit akhir untuk mengasingkan alat dan mencuci tangan bergilir. Jika giliran paip lebih lama, kurangkan pembinaan, bukan masa kebersihan."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid membentuk istana pasir di ruang sendiri."}, {"kind": "p", "text": "2. Murid meninggalkan ruang pintu dan membaiki tapak yang runtuh dengan perlahan."}, {"kind": "p", "text": "3. Murid menerangkan pintu atau tapak, kemudian mencuci tangan sebelum ke blok atau minum."}, {"kind": "p", "text": "Semakan: Setiap murid mengendalikan pasir; pembaikan kecil diterima tanpa tuntutan binaan besar."}, {"kind": "p", "text": "Alatan: Pasir lembap Cawan Sudu Air dan sabun"}, {"kind": "h3", "text": "Langkah 5: Cipta jambatan blok rendah — 7 minit"}, {"kind": "p", "text": "Minit 19 hingga 26."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Pastikan tangan murid bersih. Berikan empat minit untuk membina objek jambatan rendah dengan blok sendiri."}, {"kind": "p", "text": "2. Gunakan dua minit untuk murid bergilir menunjukkan sokongan atau penghubung dan satu sebab ringkas."}, {"kind": "p", "text": "3. Gunakan minit akhir untuk mengemas dan mencatat bahagian istana atau blok yang belum diperhatikan."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid menyusun sokongan dan penghubung jambatan tanpa memanjatnya."}, {"kind": "p", "text": "2. Murid menerangkan satu bahagian objek sendiri dan mendengar pasangan."}, {"kind": "p", "text": "3. Murid mengemas blok apabila diarahkan serta menyatakan bantuan yang masih diperlukan."}, {"kind": "p", "text": "Semakan: Kedua-dua reka bentuk diterangkan oleh murid yang sama; hasil kumpulan bukan bukti semua murid."}, {"kind": "p", "text": "Alatan: Blok besar Alas Bekas alatan Air sendiri"}, {"kind": "h3", "text": "Langkah 6: Penyejukan badan dan penutup — 4 minit"}, {"kind": "p", "text": "Minit 26 hingga 30."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru memimpin berjalan perlahan selama satu minit dan regangan lembut tangan serta kaki selama dua minit."}, {"kind": "p", "text": "2. Guru memberi masa minum dan menanyakan satu perkara yang dipelajari."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid meregang mengikut keselesaan tanpa sentapan."}, {"kind": "p", "text": "2. Murid memberitahu guru jika masih tidak selesa dan membantu mengemas alatan ringan selepas arahan."}, {"kind": "p", "text": "Semakan: Tiada latihan kuat selepas penyejukan. Guru mencatat perkara yang perlu disusuli."}, {"kind": "p", "text": "Alatan: Air minuman Ruang rehat"}, {"kind": "p", "text": "Jumlah masa: 30 minit."}, {"kind": "label", "text": "Contoh arahan kelas"}, {"kind": "p", "text": "Guru: Di manakah pintu istana kamu? Selepas cuci tangan, tunjuk sokongan jambatan blok kamu."}, {"kind": "p", "text": "Murid: Murid menunjukkan pintu dan sokongan pada dua binaan sendiri."}, {"kind": "p", "text": "Semakan guru: Guru menilai dua tindakan membina dan dua penerangan, bukan kecantikan atau saiz."}, {"kind": "h2", "text": "E. PdP terbeza", "anchor": "pdp-PJ1-2026B-2S-W32-S2"}, {"kind": "p", "text": "Tugasan bersama: Murid dapat membina istana pasir dan objek blok dengan reka bentuk sendiri yang mudah."}, {"kind": "p", "text": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan."}, {"kind": "label", "text": "Bimbingan guru"}, {"kind": "p", "text": "1. Bantu Peneroka membentuk bahagian mudah."}, {"kind": "p", "text": "2. Semak dua penerangan Pembina."}, {"kind": "p", "text": "3. Dengar pembaikan Pencabar tanpa menambah beban atau saiz."}, {"kind": "p", "text": "Semakan individu: Membina satu istana pasir berpintu dan satu objek jambatan rendah menggunakan blok sendiri."}, {"kind": "p", "text": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, {"kind": "h3", "text": "Peneroka"}, {"kind": "p", "text": "Guru membimbing satu langkah pada satu masa."}, {"kind": "p", "text": "Tugasan: Membentuk istana berpintu dan jambatan blok dengan tunjuk cara ringkas."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Ruang pasir sendiri"}, {"kind": "p", "text": "2. Cawan dan sudu"}, {"kind": "p", "text": "3. Enam blok"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan ruang pintu tanpa mengorek terowong."}, {"kind": "p", "text": "2. Guru meletakkan contoh di sisinya sendiri dan meminta murid menyusun bahan sendiri."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Bentuk istana pasir rendah dengan acuan atau sudu."}, {"kind": "p", "text": "2. Tunjuk ruang pintu dan sebut untuk masuk, kemudian cuci tangan."}, {"kind": "p", "text": "3. Susun dua sokongan dan penghubung objek blok dengan bimbingan."}, {"kind": "p", "text": "4. Tunjuk bahagian jambatan dan sebut semula bahagian istana sendiri."}, {"kind": "p", "text": "Contoh guru: Yang mana pintu istana? Yang mana sokongan jambatan?"}, {"kind": "p", "text": "Contoh respons murid: Ini pintu pasir. Blok di bawah ini menyokong jambatan."}, {"kind": "p", "text": "Hasil individu: Istana pasir serta objek blok sendiri dan dua penerangan pendek."}, {"kind": "p", "text": "Kriteria: Kedua-dua bahan dikendalikan murid dengan bantuan; bahagian dapat ditunjuk dan disebut."}, {"kind": "p", "text": "Susulan: Ulang satu bentuk asas bagi bahan yang masih sukar digunakan."}, {"kind": "h3", "text": "Pembina"}, {"kind": "p", "text": "Murid berlatih berpasangan dan melakukan sendiri."}, {"kind": "p", "text": "Tugasan: Membina dua reka bentuk dan menerangkan bahagiannya."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Dulang dua ruang"}, {"kind": "p", "text": "2. Cawan dan sudu"}, {"kind": "p", "text": "3. Blok sendiri"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Pastikan murid mengendalikan kedua-dua bahan pada gilirannya."}, {"kind": "p", "text": "2. Tanya bahagian yang dipilih tanpa menuntut penerangan panjang."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Bentuk istana pasir dengan ruang pintu di hadapan."}, {"kind": "p", "text": "2. Rapikan tapak dan terangkan satu bahagian, kemudian cuci tangan."}, {"kind": "p", "text": "3. Bina jambatan rendah menggunakan blok sendiri."}, {"kind": "p", "text": "4. Terangkan satu sokongan atau penghubung serta bandingkan dengan istana pasir sendiri."}, {"kind": "p", "text": "Contoh guru: Mengapa ada dua sokongan pada jambatan?"}, {"kind": "p", "text": "Contoh respons murid: Supaya bahagian penghubung dapat diletakkan di atasnya."}, {"kind": "p", "text": "Hasil individu: Dua binaan individu dengan penerangan setiap satu."}, {"kind": "p", "text": "Kriteria: Bahagian yang diterangkan benar-benar ada pada binaan; hasil sendiri, bukan salinan catatan pasangan."}, {"kind": "p", "text": "Susulan: Perkemas satu sambungan blok atau tapak pasir tanpa menambah tinggi."}, {"kind": "h3", "text": "Pencabar"}, {"kind": "p", "text": "Murid memperkemas satu perkara dalam kemahiran yang sama."}, {"kind": "p", "text": "Tugasan: Membaiki satu bahagian istana pasir dan jambatan blok supaya stabil."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Dulang pasir"}, {"kind": "p", "text": "2. Sudu"}, {"kind": "p", "text": "3. Enam blok"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minta murid memilih satu pembaikan pada setiap binaan dalam bahan yang sama."}, {"kind": "p", "text": "2. Semak pembaikan tanpa menggoncang atau menguji dengan beban."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Bina istana pasir dan pilih bahagian tapak atau pintu untuk dirapikan."}, {"kind": "p", "text": "2. Terangkan pembaikan pada istana, kemudian cuci tangan."}, {"kind": "p", "text": "3. Bina objek jambatan dan laras satu sokongan supaya lebih stabil."}, {"kind": "p", "text": "4. Terangkan pembaikan jambatan serta satu perbezaan daripada istana pasir."}, {"kind": "p", "text": "Contoh guru: Apakah yang kamu ubah?"}, {"kind": "p", "text": "Contoh respons murid: Saya ratakan tapak istana dan rapatkan sokongan jambatan."}, {"kind": "p", "text": "Hasil individu: Dua binaan dan dua penerangan pembaikan kecil."}, {"kind": "p", "text": "Kriteria: Pembaikan selamat dibuat sendiri; tiada ujian beban atau binaan tinggi."}, {"kind": "p", "text": "Susulan: Kongsi idea dengan kata-kata tanpa menyentuh binaan rakan."}, {"kind": "h2", "text": "F. Pentaksiran Bilik Darjah"}, {"kind": "h3", "text": "PBD utama — SP 1.10.2"}, {"kind": "p", "text": "Kaedah: Pemerhatian tindakan membina dan hasil individu."}, {"kind": "p", "text": "Bukti: Istana pasir berpintu serta objek blok yang dibuat murid sendiri."}, {"kind": "p", "text": "Kriteria: Kedua-dua binaan wujud melalui tindakan murid; tahap bantuan dicatat."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Istana pasir dan tindakan sendiri: ____"}, {"kind": "p", "text": "2. Objek blok dan tindakan sendiri: ____"}, {"kind": "p", "text": "3. Bantuan / belum mendapat giliran: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 2.9.2"}, {"kind": "p", "text": "Kaedah: Soal jawab individu tentang kedua-dua hasil."}, {"kind": "p", "text": "Bukti: Penerangan pintu atau tapak istana pasir dan bahagian jambatan blok."}, {"kind": "p", "text": "Kriteria: Murid menerangkan satu bahagian atau pembaikan bagi setiap reka bentuk."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Penerangan istana pasir: ____"}, {"kind": "p", "text": "2. Penerangan objek blok: ____"}, {"kind": "p", "text": "3. Kata bantu / belum didengar: ____"}, {"kind": "h3", "text": "PBD sokongan — SP 5.2.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian respons sukarela semasa membina."}, {"kind": "p", "text": "Bukti: Kata atau isyarat sebenar tentang membina pasir dan blok."}, {"kind": "p", "text": "Kriteria: Respons sebenar dicatat; sensitiviti terhadap bahan dan keperluan rehat dihormati."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Respons pasir: ____"}, {"kind": "p", "text": "2. Respons blok: ____"}, {"kind": "p", "text": "3. Keselesaan / susulan: ____"}, {"kind": "h2", "text": "G. Refleksi dan intervensi"}, {"kind": "p", "text": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________."}, {"kind": "label", "text": "Intervensi"}, {"kind": "p", "text": "1. Jika binaan belum stabil, guna menara pasir tunggal dan objek blok yang rendah sebagai ansur maju."}, {"kind": "p", "text": "2. Jadualkan susulan bagi murid yang belum melakukan salah satu bahan atau belum menerangkan salah satu reka bentuk."}]'::jsonb,'{"source_hold": "", "adaptation_note": "Guru mengesahkan pasir bersih dalam dulang dan plastisin atau blok. Blok dipilih daripada pilihan sumber. Setiap murid membina istana pasir dan objek blok dalam setiap sesi; bukan satu bahan bagi satu kumpulan. Tugas ringkas dengan bahagian individu dan penerangan sendiri.", "source_images_verified": true, "audio_verified": false, "ba_verified": false, "classroom_trial_performed": false}'::jsonb),
  ('PJ1-2026B-2S-W33-S1','pj',1,2026,33,1,30,'3.1.1',array[46,47]::int[],'435c11dee07042f8642f14ac46e8aee0cc72ab6b96a81e63a22b12572ce94676','78bdfd7a05fa54f55a3961f8a3cd39f50fc77e1ca571ecde40bef7acb687ab73','715d2dd93e616381f7de4fb5e317e008bae7007088b12831c3d9d17a2be5d6d7','ACCEPTED_FROM_DOWNLOADED_CATATAN',false,'{"id": "PJ1-2026B-2S-W33-S1", "subject": "Pendidikan Jasmani", "year": 1, "week": 33, "session": 1, "revision": "PJ1-30MIN-REVIEW-R1", "date": "", "teaching_time": "", "minutes": 30, "sessions_per_week": 2, "weekly_minutes": 60, "title": "Otot Lentur, Pergerakan Teratur", "source_title": "Otot Lentur, Pergerakan Teratur", "unit": "Unit 7: Badan Cergas Otak Cerdas", "source_row_id": "PJ1-RPT2026-T11-R3", "source_row_literal": ["33\n\nKump A: 20.09.2026-24.09.2026\n\nKump B: 21.09.2026-\n25.09.2026", "7: BADAN CERGAS OTAK CERDAS\nOTOT LENTUR, PERGERAKAN TERATUR.", "3.1 Melakukan aktiviti fizikal berpandukan konsep kecergasan. \n4.1 Mengaplikasi konsep kecergasan semasa melakukan aktiviti fizikal\n5.1 Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.\n\n5.2 Menunjukkan keyakinan dan tanggungjawab kendiri semasa melakukan aktiviti.", "3.1.1 Melakukan pelbagai jenis aktiviti seperti berjalan, berlari, dan regangan yang boleh meningkatkan suhu badan dan otot, kadar pernafasan, dan kadar nadi. \n3.1.2 Melakukan aktiviti yang boleh menurunkan kadar pernafasan dan kadar nadi. \n\n4.1.1 Mengenal pasti aktiviti memanaskan dan menyejukkan badan. \n4.1.2 Mengenal pasti tujuan memanaskan dan menyejukkan badan. \n4.1.3 Menyatakan keperluan air sebelum, semasa, dan selepas melakukan aktiviti fizikal \n\n5.1.1 Membuat persediaan diri sebelum, semasa, dan selepas melakukan aktiviti Pendidikan Jasmani.\n5.2.1 Mempamerkan rasa seronok melakukan aktiviti baharu dalam Pendidikan Jasmani", "AKTIVITI PAK-21\nRecap Group (Mengulangi / mengingat semula)\nBrainstorming (Sumbangsaran)\nBBB/BBM\nBT m/s 46-47\n\nEMK \nKreativiti dan Inovasi\nKBAT\nMengaplikasi Memahami\n\nNILAI\nKerjasama Toleransi"], "rpt_original_page_literal": "46-47", "source_pages": [46, 47], "source_pdf_pages": [54, 55], "rpt_book_pages": "46, 47", "main_standard_key": "3.1.1", "sk_code": "3.1", "sk_text": "Melakukan aktiviti fizikal berpandukan konsep kecergasan.", "sp_code": "3.1.1", "sp_text": "Melakukan pelbagai jenis aktiviti seperti berjalan, berlari, dan regangan yang boleh meningkatkan suhu badan dan otot, kadar pernafasan dan kadar nadi.", "complementary_standards": [{"standard_key": "3.1.2", "sp_code": "3.1.2", "sp_text": "Melakukan aktiviti yang boleh menurunkan kadar pernafasan dan kadar nadi.", "sk_code": "3.1", "sk_text": "Melakukan aktiviti fizikal berpandukan konsep kecergasan.", "domain": "psikomotor", "source_label": ""}, {"standard_key": "4.1.1", "sp_code": "4.1.1", "sp_text": "Mengenal pasti aktiviti memanaskan dan menyejukkan badan.", "sk_code": "4.1", "sk_text": "Mengaplikasi konsep kecergasan semasa melakukan aktiviti fizikal.", "domain": "kognitif", "source_label": ""}, {"standard_key": "4.1.2", "sp_code": "4.1.2", "sp_text": "Mengenal pasti tujuan memanaskan dan menyejukkan badan.", "sk_code": "4.1", "sk_text": "Mengaplikasi konsep kecergasan semasa melakukan aktiviti fizikal.", "domain": "kognitif", "source_label": ""}, {"standard_key": "4.1.3", "sp_code": "4.1.3", "sp_text": "Menyatakan keperluan air sebelum, semasa dan selepas melakukan aktiviti fizikal.", "sk_code": "4.1", "sk_text": "Mengaplikasi konsep kecergasan semasa melakukan aktiviti fizikal.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.1.1", "sp_code": "5.1.1", "sp_text": "Membuat persediaan diri sebelum, semasa dan selepas melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}, {"standard_key": "5.2.1", "sp_code": "5.2.1", "sp_text": "Mempamerkan rasa seronok melakukan aktiviti baharu dalam Pendidikan Jasmani.", "sk_code": "5.2", "sk_text": "Menunjukkan keyakinan dan tanggungjawab kendiri semasa melakukan aktiviti.", "domain": "afektif", "source_label": ""}], "source_task": "Bergerak bersedia dan mengenal perubahan badan", "authoring_focus": "Bergerak bersedia dan mengenal perubahan badan", "source_hold": "Teks RPT, DSKP dan buku dibaca. Semakan imej guling BT35 dan kod DSKP hlm70 terhalang ralat402; OCR dan teks salinan menyokong kod berulang, bukan kelulusan visual. Guru perlu menilai postur, alat dan kesediaan setiap murid.", "practical_required": true, "warmup_required": true, "cooldown_required": true, "facility_replacement": false, "facility_replacement_note": "", "source_subset_focus": false, "source_subset_note": "", "adaptation_note": "Pemanasan, penyejukan dan air sebelum, semasa serta selepas diajar. Nadi diperhatikan pada pergelangan tangan ketika berhenti; tiada sasaran denyut, kiraan bpm wajib atau jawapan peningkatan direka. Keperluan air Tahun1 tidak sama dengan standard kuantiti Tahun3.", "privacy_adaptation": false, "privacy_note": "", "held_standards": [], "source_code_conflict": false, "source_code_note": "", "unperformed_literal_elements": [], "source_mapping_review": "20 RPH, dua sesi30minit seminggu dibenarkan guru. S1/S2 ialah cadangan pecahan RPT mingguan, bukan nombor sesi yang tercetak dalam RPT.", "routine_book_pages": [46, 47], "active": false, "production_write_performed": false, "presentation_review": "PENDING_TEACHER_REVIEW", "safety": ["Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula.", "Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan.", "Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan.", "Nadi dicari semasa berdiri atau duduk stabil sahaja. Guru menunjukkan dua jari pada pergelangan tangannya sendiri; bantuan pada tangan murid diberi dengan izin dan tanpa menekan kuat. Jika nadi sukar dirasa, murid boleh merasai degupan dengan tapak tangan di dada ketika berhenti atau memberitahu guru bahawa nadi belum ditemui. Tiada kiraan denyutan wajib.", "Murid tidak perlu berlari laju untuk merasai perubahan badan. Rasa panas, pernafasan dan nadi mungkin berbeza antara murid; tiada perubahan tertentu dijadikan syarat lulus.", "Guru memberi masa berhenti dan minum di ruang rehat. Murid tidak minum sambil berlari atau dipaksa menghabiskan air."], "weather_plan": "Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat.", "reflection": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________.", "activity_name": "Berjalan, lari perlahan dan regang sebelum bermain", "objective": "Murid dapat melakukan pemanasan badan dengan gerakan ringan untuk bersedia melakukan aktiviti fizikal.", "success_criteria": ["Melakukan berjalan, lari perlahan setempat dan regangan mengikut contoh guru.", "Menamakan satu aktiviti pemanasan dan satu aktiviti penyejukan serta tujuan mudahnya.", "Menyatakan air diperlukan sebelum, semasa dan selepas aktiviti."], "prior_knowledge": "Murid pernah berjalan, berlari dan membawa air minuman ke kelas Pendidikan Jasmani.", "equipment": [{"item": "Kon penanda", "quantity": "6 buah", "use": "Empat kon menandakan tepi kawasan bergerak. Dua kon menandakan ruang rehat; semuanya di luar tempat pijakan murid."}, {"item": "Jam randik", "quantity": "1 buah untuk guru", "use": "Menetapkan masa gerakan, rehat dan mencari nadi tanpa sasaran bilangan denyutan."}, {"item": "Botol air minuman sendiri", "quantity": "1 bagi setiap murid", "use": "Diletakkan di ruang rehat untuk minum sebelum, semasa dan selepas aktiviti; tidak berkongsi botol."}, {"item": "Buku teks PJPK Tahun 1", "quantity": "1 naskhah guru, halaman 46–47", "use": "Rujukan pemanasan, penyejukan dan keperluan air."}, {"item": "Senarai semak dan pen guru", "quantity": "1 set", "use": "Mencatat lakuan, jawapan dan bantuan bagi murid yang benar-benar diperhatikan."}], "preparation": ["Guru memeriksa permukaan rata, kering dan bebas halangan. Empat kon diletakkan di luar kawasan pijakan, bukan untuk dilompat.", "Guru menetapkan ruang sendiri dengan jarak sekurang-kurangnya dua depa antara murid. Dua kon ruang rehat berada di tepi kawasan dalam pandangan guru.", "Botol diletakkan di tepi ruang rehat supaya murid boleh mengambilnya tanpa melintasi rakan yang sedang bergerak. Guru menyemak kesediaan murid sebelum memulakan lari perlahan."], "organisation": "Murid berpasangan di ruang masing-masing. Semua berlatih bersama; dalam semakan, A bergerak pada minit 20–22 dan B pada minit 22–24. Rakan yang menunggu berehat di sebelah ruang sendiri dan tidak meniru serentak. Murid tanpa pasangan berlatih berhampiran guru. Tiada perlumbaan atau pertukaran tempat. Apabila guru berkata “Berhenti”, murid berhenti di tempat yang selamat dan memandang guru.", "movement_cues": ["Pandang depan. Langkah kecil dan ringan.", "Regang perlahan setakat selesa. Jangan menyentap atau menarik badan rakan.", "Bernafas seperti biasa. Berjalan menggantikan lari jika perlu dan beritahu guru.", "Cari nadi hanya selepas kaki berhenti. Gunakan jari telunjuk dan jari tengah di pergelangan tangan, bukan ibu jari dan bukan di leher. Sentuh ringan."], "timing_note": "Minit 0–2 persediaan dan nadi awal; 2–6 pemanasan; 6–10 perhatikan badan dan kenal tujuan; 10–19 latihan; 19–26 semakan individu; 26–30 penyejukan. Minum sebelum pada minit 0–1, semasa pada 9–10 dan 15–16, serta selepas pada 29–30. Mencari nadi diberi 30 saat, diikuti 30 saat merasainya ketika tidak bergerak. Rehat tambahan dibenarkan dalam waktu yang sama; kurangkan ulangan, bukan waktu penyejukan.", "values": "Kerjasama, disiplin dan menjaga keselamatan rakan.", "classroom_example": {"teacher_says": "Jalan dahulu. Sekarang lari perlahan di tempat sendiri. Kemudian regang tangan. Selepas berhenti, beritahu cikgu apa yang kamu rasa.", "pupils_do": "Murid melakukan gerakan sendiri. Selepas berhenti, murid boleh berkata “Badan saya rasa panas”, “Nafas saya lebih cepat” atau “Saya belum rasa beza”.", "teacher_checks": "Guru melihat gerakan dan mendengar pengalaman sebenar. Murid tidak perlu memberi jawapan bahawa nadinya pasti meningkat."}, "bbm": ["Kon penanda — 6 buah", "Jam randik — 1 buah untuk guru", "Botol air minuman sendiri — 1 bagi setiap murid", "Buku teks PJPK Tahun 1 — 1 naskhah guru, halaman 46–47", "Senarai semak dan pen guru — 1 set", "Buku teks dan senarai semak pemerhatian guru."], "pak21": "Murid meniru contoh guru, berlatih berpasangan dan bergilir menunjukkan urutan pemanasan. Rakan mengingatkan “langkah kecil” atau “jaga jarak”. Jawapan bersama hanya latihan; guru mendapatkan lakuan dan jawapan setiap murid secara berasingan.", "phases": [{"name": "Persediaan, minum dan rasa nadi awal", "minutes": 2, "teacher": ["Minit 0–1: guru menyemak pakaian, tali kasut dan keadaan murid. Guru menunjukkan ruang sendiri, ruang rehat dan arahan “Berhenti”, kemudian memberi peluang minum sebelum bergerak.", "Minit 1–2: guru meminta semua berhenti dan berdiri atau duduk stabil. Guru menunjukkan jari telunjuk dan jari tengah pada pergelangan tangan, bukan ibu jari atau leher; beri 30 saat mencari dan 30 saat merasai nadi tanpa mengira."], "pupils": ["Murid membetulkan pakaian atau meminta bantuan mengikat kasut. Murid memberitahu jika tidak sihat dan minum mengikut keperluan.", "Murid tidak melangkah semasa mencari nadi. Murid merasai keadaan badan dan pernafasan sebelum bergerak; jika belum jumpa nadi, murid meminta bantuan."], "check": "Guru mencatat persediaan sebelum aktiviti bagi 5.1.1. Pemerhatian awal nadi, pernafasan dan rasa badan bukan ujian nombor denyutan.", "resources": ["Kon penanda", "Botol air minuman sendiri", "Jam randik"]}, {"name": "Pemanasan: jalan, lari perlahan dan regang", "minutes": 4, "teacher": ["Minit 2–3: guru memimpin berjalan setempat. Minit 3–4: guru memimpin lari perlahan setempat dengan langkah kecil; berjalan dibenarkan jika lebih sesuai.", "Minit 4–5: guru menunjukkan membuka tangan ke sisi dan merapatkannya semula dengan lembut. Minit 5–6: guru menunjukkan regangan betis dengan satu kaki sedikit ke belakang, tumit di lantai dan lutut depan dibengkokkan sedikit; tukar kaki tanpa henjutan.", "Guru menerangkan bahawa gerakan pemanasan boleh membuat badan dan otot lebih panas, nafas lebih cepat serta nadi lebih cepat. Guru tidak meminta murid berusaha sehingga terlalu penat."], "pupils": ["Murid berjalan dan mencuba lari perlahan dalam ruang sendiri. Murid bernafas seperti biasa dan mengekalkan jarak.", "Murid membuka dan merapatkan tangan, kemudian meregangkan betis kanan dan kiri setakat selesa. Murid berhenti dan memaklumkan guru jika sakit atau pening."], "check": "PBD 3.1.1: guru melihat berjalan, lari perlahan dan regangan setiap murid yang sempat diperhatikan. Penyesuaian berjalan menggantikan lari dicatat, bukan disamakan dengan larian.", "resources": ["Kon penanda", "Jam randik", "Ruang rata"]}, {"name": "Perhatikan badan dan kenal tujuan", "minutes": 4, "teacher": ["Minit 6–7: guru mengarahkan semua berhenti di tempat selamat. Beri 30 saat mencari nadi di pergelangan tangan dengan dua jari dan 30 saat merasainya; tanya perubahan sebenar pada rasa panas badan, pernafasan dan nadi.", "Minit 7–8: guru merujuk buku halaman 46–47. Guru menamakan berjalan dan lari perlahan sebagai pemanasan untuk menyediakan badan; berjalan perlahan dan regangan lembut selepas aktiviti membantu badan kembali tenang.", "Minit 8–9: guru memberi contoh soalan pendek tentang aktiviti pemanasan, penyejukan dan tujuan masing-masing. Minit 9–10: semua berehat dan mendapat peluang minum; guru menyebut air diperlukan sebelum, semasa dan selepas aktiviti supaya badan cukup air."], "pupils": ["Murid kekal tidak bergerak ketika merasai nadi. Murid menyebut apa yang benar-benar dirasai, termasuk “belum jumpa” atau “belum rasa beza”.", "Murid bergilir menamakan satu aktiviti pemanasan dan satu aktiviti penyejukan kepada pasangan. Murid menyatakan tujuan dengan kata mudah seperti “bersedia bergerak” dan “badan kembali tenang”.", "Murid minum di ruang rehat. Murid menyebut bahawa air diperlukan sebelum, semasa dan selepas bergerak apabila ditanya guru."], "check": "PBD 4.1.1, 4.1.2 dan 4.1.3: guru mendengar jawapan individu yang dipanggil. Jawapan pasangan atau kelas tidak dijadikan bukti murid lain.", "resources": ["Buku teks halaman 46–47", "Botol air minuman sendiri", "Jam randik"]}, {"name": "Latihan urutan pemanasan dengan bimbingan", "minutes": 9, "teacher": ["Minit 10–11: guru mengulang urutan jalan, lari perlahan dan regang. Guru memberi bimbingan Peneroka, Pembina atau Pencabar dalam aktiviti yang sama, bukan tiga pusingan tambahan.", "Minit 11–14: bimbing berjalan 1 minit, lari perlahan setempat 1 minit dan regangan tangan serta betis 1 minit. Guru mendekati murid yang memerlukan contoh semula.", "Minit 14–15: semua berhenti; beri 30 saat mencari dan 30 saat merasai nadi dengan dua jari pada pergelangan tangan. Minit 15–16: beri rehat dan minum; semak tali kasut, jarak serta keadaan badan sebelum sambung.", "Minit 16–18: ulang urutan ringkas, iaitu jalan 30 saat, lari perlahan 30 saat dan regangan 1 minit. Minit 18–19: semua berhenti dan berehat; guru mendengar jawapan ringkas tentang badan dan keperluan air."], "pupils": ["Murid mengikuti urutan dengan bantuan yang sesuai. Murid tidak menambah kelajuan untuk mengejar rakan.", "Murid berhenti sebelum menyentuh pergelangan tangan. Murid memberitahu guru jika tidak dapat merasai nadi dan tidak meneka bilangannya.", "Semasa rehat, murid minum mengikut keperluan, memeriksa kasut dan memberitahu jika letih. Murid menyebut bahawa air diperlukan juga semasa aktiviti.", "Murid mencuba urutan pendek sekali lagi jika selesa. Selepas berhenti, murid bergilir memberitahu gerakan yang disukai atau jika belum selesa."], "check": "Guru merekod lakuan individu 3.1.1, persediaan semasa 5.1.1, jawapan air 4.1.3 dan respons sukarela 5.2.1. Bantuan, rehat dan gerakan yang tidak dibuat direkod secara berasingan.", "resources": ["Kon penanda", "Jam randik", "Botol air minuman sendiri", "Senarai semak dan pen guru"]}, {"name": "Giliran menunjukkan pemanasan dan semakan individu", "minutes": 7, "teacher": ["Minit 19–20: guru menetapkan pasangan A dan B serta mengulang arahan berhenti. Guru memilih murid untuk diperhatikan tanpa menghalang pandangan terhadap murid lain.", "Minit 20–22: A menunjukkan jalan 30 saat, lari perlahan 30 saat dan regangan 1 minit. Minit 22–24: B melakukan urutan yang sama; pasangan yang menunggu berehat dan memberi satu peringatan sopan.", "Minit 24–25: ketika semua berehat, guru mendapatkan jawapan individu tentang contoh dan tujuan pemanasan serta penyejukan. Guru meminta murid melengkapkan sebutan air sebelum, semasa dan selepas aktiviti.", "Minit 25–26: semua kekal berhenti; beri 30 saat mencari dan 30 saat merasai nadi di pergelangan tangan sebagai pemerhatian sebelum penyejukan. Guru mencatat murid yang belum sempat diperhatikan untuk susulan."], "pupils": ["Murid menjalani giliran sendiri. Rakan yang menunggu tidak menyentuh atau menggerakkan badan murid.", "Murid menunjukkan urutan pemanasan dengan langkah kecil dan regangan lembut. Berjalan atau rehat dibenarkan jika perlu; murid memberitahu guru.", "Murid menjawab guru secara bergilir dengan ayat pendek. Murid boleh menerima pilihan lisan atau contoh semula.", "Murid mencari nadi hanya ketika kaki berhenti dan bernafas seperti biasa. Murid menyimpan pemerhatian sendiri untuk dibandingkan selepas penyejukan."], "check": "Semakan 3.1.1 dibuat pada lakuan setiap murid yang benar-benar dilihat. Jawapan 4.1.1, 4.1.2 dan 4.1.3 dicatat mengikut nama, termasuk bantuan; tidak semua ditanda selesai secara automatik.", "resources": ["Kon penanda", "Jam randik", "Senarai semak dan pen guru"]}, {"name": "Penyejukan, nadi selepas dan minum", "minutes": 4, "teacher": ["Minit 26–27: guru memimpin berjalan perlahan setempat. Minit 27–28: guru membimbing regangan tangan dan betis kanan serta kiri secara lembut tanpa henjutan.", "Minit 28–29: guru meminta semua berhenti dan berdiri atau duduk stabil. Beri 30 saat mencari dan 30 saat merasai nadi dengan dua jari di pergelangan tangan; tanya keadaan nafas dan nadi berbanding sebelum penyejukan, tanpa menentukan jawapan.", "Minit 29–30: guru memberi peluang minum selepas aktiviti. Guru bertanya tujuan penyejukan, memeriksa keadaan murid dan membenarkan murid mengemas botol sendiri; kon dikemas selepas kawasan kosong."], "pupils": ["Murid berjalan perlahan, kemudian meregang dengan lembut dan bernafas seperti biasa. Murid tidak berlari lagi selepas penyejukan.", "Murid berhenti sebelum mencari nadi. Murid melaporkan rasa sebenar; belum dapat merasai perubahan diterima dan dibantu.", "Murid menyatakan air diperlukan selepas aktiviti, minum mengikut keperluan dan memeriksa keadaan diri. Murid memberitahu guru jika masih tidak selesa atau mahu berkongsi gerakan yang disukai."], "check": "PBD 3.1.2: lakuan penyejukan individu; 4.1.1 dan 4.1.2: contoh serta tujuan penyejukan; 4.1.3 dan 5.1.1: air serta urus diri selepas aktiviti. Nadi tidak perlu menunjukkan penurunan tertentu untuk membuktikan lakuan.", "resources": ["Botol air minuman sendiri", "Jam randik", "Ruang rehat", "Senarai semak dan pen guru"]}], "differentiation": {"support": {"label": "Peneroka", "support_description": "Guru membimbing satu langkah pada satu masa.", "task": "Melakukan urutan pemanasan yang sama sambil meniru guru dari dekat.", "materials": ["Ruang sendiri dalam sempadan kon", "Jam randik guru", "Botol air sendiri", "Buku teks halaman 46–47 untuk contoh guru"], "teacher": ["Guru berdiri dalam pandangan murid dan memberi arahan satu demi satu: “jalan”, “lari perlahan”, “regang”. Guru menunjukkan semula regangan betis tanpa memegang atau menarik murid.", "Guru membimbing lokasi nadi pada pergelangan tangan selepas murid berhenti. Guru memberi pilihan lisan tentang tujuan dan mengulang kata “sebelum, semasa, selepas” sambil merujuk waktu minum sebenar."], "pupil_steps": ["Sebelum bergerak, periksa kasut dan pakaian dengan bantuan guru. Minum jika perlu. Berhenti untuk mencari nadi awal selama 30 saat dan merasainya 30 saat dengan dua jari di pergelangan tangan.", "Semasa pemanasan dan latihan, ikut guru berjalan, lari perlahan setempat dan meregang tangan serta betis. Selepas berhenti, rasa nadi dan pernafasan serta beritahu rasa panas badan. Sebut contoh pemanasan dan tujuannya, iaitu menyediakan badan.", "Dalam rehat semasa latihan, minum dan beritahu jika letih; periksa kasut serta ruang sendiri. Sebut “Air diperlukan sebelum, semasa dan selepas aktiviti”. Pada giliran sendiri, tunjuk urutan pemanasan yang sama dengan bimbingan.", "Selepas aktiviti, berjalan perlahan dan regang lembut bersama guru. Sebut ini penyejukan untuk membantu badan kembali tenang. Berhenti, cari nadi 30 saat dan rasa 30 saat; minum selepas, kemas botol dan beritahu keadaan diri serta aktiviti yang disukai jika mahu."], "product": "Urutan pemanasan individu yang dilihat guru, diikuti lakuan penyejukan dan jawapan ringkas tentang tujuan, air serta pengalaman badan.", "criterion": "Murid menunjukkan berjalan, percubaan lari perlahan dan regangan dengan bantuan; contoh serta tujuan pemanasan dan penyejukan, air sebelum/semasa/selepas dan persediaan diri diperiksa satu demi satu. Jika lari diganti berjalan, guru mencatat penyesuaian sebenar.", "next_step": "Kekalkan contoh bersebelahan dan arahan pendek. Jika nadi belum dirasa, ulang ketika berhenti atau rasa degupan di dada; jangan menambah larian untuk mencari perubahan.", "example": {"teacher": "Kita jalan dahulu. Selepas bermain nanti, jalan bagaimana? Bila badan perlukan air?", "pupil": "Murid berjalan mengikut guru, kemudian menjawab “Perlahan. Air sebelum, semasa dan selepas.”"}}, "core": {"label": "Pembina", "support_description": "Murid berlatih berpasangan dan melakukan sendiri.", "task": "Melatih dan menunjukkan urutan jalan, lari perlahan dan regangan secara bergilir.", "materials": ["Ruang pasangan dengan kon di tepi", "Jam randik guru", "Botol air sendiri", "Buku teks halaman 46–47"], "teacher": ["Guru menunjukkan urutan sebelum pasangan mencuba. Guru mengingatkan langkah kecil dan membetulkan kedudukan tumit semasa regangan betis melalui contoh semula.", "Guru menyemak setiap murid ketika giliran sendiri. Guru membantu mencari nadi selepas berhenti dan memberi soalan pendek berasingan untuk tujuan pemanasan, tujuan penyejukan dan waktu air diperlukan."], "pupil_steps": ["Sebelum aktiviti, periksa pakaian, kasut dan ruang; beritahu guru jika tidak sihat. Minum jika perlu. Berhenti untuk mencari nadi 30 saat dan merasainya 30 saat dengan dua jari di pergelangan tangan.", "Ikut latihan jalan, lari perlahan setempat dan regangan tangan serta betis. Selepas berhenti, rasa nadi dan beritahu keadaan nafas serta rasa panas badan. Namakan satu gerakan pemanasan dan sebut tujuannya untuk bersedia bergerak.", "Semasa rehat yang ditetapkan, minum, periksa kasut dan maklumkan jika letih. Sebut air diperlukan sebelum, semasa dan selepas aktiviti. Bergilir menunjukkan urutan pemanasan; pasangan berehat dan memberi peringatan sopan.", "Selepas aktiviti, lakukan berjalan perlahan dan regangan lembut. Namakan penyejukan serta tujuannya membantu badan kembali tenang. Berhenti, cari nadi 30 saat dan rasa 30 saat. Minum selepas, kemas botol dan beritahu keadaan diri serta gerakan yang disukai jika mahu."], "product": "Lakuan urutan pemanasan setiap murid, penyejukan sendiri dan jawapan individu; rakan bukan pengganti bukti guru.", "criterion": "Murid melakukan urutan dengan ruang yang selamat dan mengenal contoh serta tujuan kedua-dua rutin. Guru menyemak air dan persediaan sebelum, semasa dan selepas tanpa menetapkan perubahan nadi wajib.", "next_step": "Ulang bahagian urutan yang belum jelas bersama guru. Teruskan bantuan lisan atau pilihan jawapan; murid yang berehat diberi peluang susulan tanpa hukuman.", "example": {"teacher": "Tunjukkan urutan kamu. Mengapa kita panaskan badan? Selepas bergerak, bagaimana kita tenangkan badan?", "pupil": "Murid berjalan, lari perlahan dan regang; kemudian berkata “Supaya bersedia. Selepas itu jalan perlahan dan regang lembut.”"}}, "challenge": {"label": "Pencabar", "support_description": "Murid memperkemas satu perkara dalam kemahiran yang sama.", "task": "Memperkemas langkah kecil dan regangan dalam urutan pemanasan yang sama.", "materials": ["Ruang sendiri dengan kon di luar pijakan", "Jam randik guru", "Botol air sendiri", "Buku teks halaman 46–47"], "teacher": ["Guru menunjukkan cara menukar daripada jalan kepada lari perlahan tanpa keluar dari ruang sendiri. Guru mengingatkan murid merendahkan kelajuan, bukan menambah ulangan.", "Guru membimbing semakan nadi ketika berhenti dan meminta jawapan mudah, bukan penjelasan panjang. Guru terus memberi contoh untuk tujuan pemanasan, penyejukan dan air jika diperlukan."], "pupil_steps": ["Sebelum aktiviti, semak kasut, pakaian dan ruang sendiri; sediakan botol dan minum jika perlu. Berhenti untuk mencari nadi 30 saat serta merasainya 30 saat dengan dua jari pada pergelangan tangan.", "Lakukan jalan, lari perlahan setempat dan regangan tangan serta betis. Perkemas langkah supaya tidak menghampiri rakan. Selepas berhenti, beritahu rasa panas badan, nafas dan nadi yang sebenar; namakan pemanasan dan tujuan menyediakan badan.", "Semasa rehat, minum dan semak semula keadaan diri serta kasut. Sebut air diperlukan sebelum, semasa dan selepas aktiviti. Pada giliran individu, tunjuk urutan yang sama dengan regangan lebih terkawal, bukan lebih kuat.", "Selepas aktiviti, berjalan perlahan dan regang lembut. Namakan rutin penyejukan dan tujuannya membantu badan kembali tenang. Berhenti, cari nadi 30 saat dan rasa 30 saat, kemudian minum selepas dan kemas botol. Beritahu jika tidak selesa atau mahu berkongsi gerakan yang menyeronokkan."], "product": "Urutan pemanasan individu dengan kawalan ruang, lakuan penyejukan serta jawapan ringkas yang diperhatikan guru.", "criterion": "Murid memperkemas kawalan langkah dalam kemahiran yang sama. Contoh dan tujuan pemanasan/penyejukan, air serta persediaan sebelum/semasa/selepas tetap disemak; kelajuan dan perubahan nadi bukan ukuran tambahan.", "next_step": "Berikan satu maklum balas tentang ruang atau regangan. Kembali kepada contoh guru bila perlu; tiada tambahan beban, jarak atau bilangan gerakan.", "example": {"teacher": "Boleh kekalkan langkah kecil di tempat sendiri? Apakah gerakan kita selepas selesai?", "pupil": "Murid memperkemas langkah dan menjawab “Jalan perlahan dan regang supaya badan kembali tenang.”"}}}, "differentiation_delivery": {"common_task": "Murid dapat melakukan pemanasan badan dengan gerakan ringan untuk bersedia melakukan aktiviti fizikal.", "placement": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan.", "teacher_rounds": ["Minit 0–2: lihat persediaan sebelum dan bantu nadi awal.", "Minit 2–10: lihat gerakan pemanasan dan dengar jawapan individu yang sempat dipanggil.", "Minit 11–19: guru bergerak dari pasangan ke pasangan, memberi bantuan dan mencatat persediaan semasa serta respons murid.", "Minit 20–24: semak lakuan A kemudian B. Minit 24–26: dengar jawapan dan perhatikan nadi ketika berhenti.", "Minit 26–30: semak penyejukan dan persediaan selepas. Senaraikan nama serta aspek yang belum sempat diperhatikan; jangan mengisi bukti berdasarkan jawapan kelas."], "individual_check": "Melakukan berjalan, lari perlahan setempat dan regangan mengikut contoh guru.", "flexible_help": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, "pbd": {"method": "Pemerhatian lakuan individu pada minit 2–6, 11–14 dan giliran 20–24.", "evidence": ["Gerakan berjalan, lari perlahan setempat dan regangan tangan/betis setiap murid yang dilihat.", "Laporan sebenar tentang rasa panas badan, pernafasan dan nadi selepas berhenti pada minit 6–7 atau 14–15; bukan jawapan peningkatan yang ditetapkan."], "criterion": "Murid melakukan urutan pemanasan dengan gerakan ringan dan selamat. Bantuan dibenarkan. Jika larian diganti berjalan, nyatakan lakuan sebenar; laporan nadi bukan syarat wajib meningkat.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama murid: ____; berjalan: ____; lari perlahan atau penyesuaian: ____; regangan: ____.", "Pemerhatian badan/nafas/nadi: ____; bantuan atau rehat: ____; belum diperhatikan: ____."]}, "pbd_complementary": {"3.1.2": {"method": "Pemerhatian setiap murid semasa penyejukan pada minit 26–28; semakan rasa nadi dan nafas ketika berhenti pada minit 28–29.", "evidence": "Lakuan berjalan perlahan dan regangan lembut; laporan sebenar selepas penyejukan berbanding pemerhatian berhenti pada minit 25–26.", "criterion": "Murid melakukan aktiviti penyejukan dengan perlahan dan bernafas seperti biasa. Tiada penurunan nadi tertentu atau kiraan denyutan diwajibkan.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama: ____; berjalan perlahan: ____; regangan lembut: ____; bantuan: ____.", "Nadi/nafas sebelum dan selepas yang dilaporkan: ____; belum dapat dirasa: ____."]}, "4.1.1": {"method": "Soal jawab individu pada minit 8–9 dan 24–25; lengkapkan contoh penyejukan semasa penutup 29–30 jika sempat.", "evidence": "Murid menamakan satu aktiviti memanaskan badan dan satu aktiviti menyejukkan badan yang dilakukan sendiri.", "criterion": "Murid mengenal kedua-duanya, contohnya lari perlahan untuk pemanasan serta berjalan perlahan selepas aktiviti untuk penyejukan. Pilihan lisan guru dibenarkan dan dicatat.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama: ____; contoh pemanasan: ____; contoh penyejukan: ____; bantuan: ____."]}, "4.1.2": {"method": "Guru menyoal tujuan pemanasan dan tujuan penyejukan secara berasingan pada minit 8–9, 24–25 dan 29–30.", "evidence": "Jawapan individu seperti “Badan bersedia bergerak” dan “Badan kembali tenang selepas bergerak”.", "criterion": "Murid mengenal tujuan kedua-dua rutin dengan bahasa mudah. Guru boleh memberi dua pilihan lisan; tidak perlu penerangan sebab yang panjang.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama: ____; tujuan pemanasan: ____; tujuan penyejukan: ____; contoh/bantuan lisan: ____."]}, "4.1.3": {"method": "Soal jawab individu ketika rehat minum minit 9–10 dan 15–16, serta selepas aktiviti 29–30. Guru meminta murid melengkapkan ketiga-tiga waktu.", "evidence": "Sebutannya sendiri bahawa air diperlukan sebelum, semasa dan selepas melakukan aktiviti; tindakan minum sahaja tidak menggantikan jawapan ini.", "criterion": "Murid menyatakan ketiga-tiga waktu air diperlukan. Tiada jumlah gelas, kuota air atau syarat menghabiskan botol.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama: ____; menyebut sebelum: ____; semasa: ____; selepas: ____; bantuan/jawapan belum diperoleh: ____."]}, "5.1.1": {"method": "Pemerhatian individu sebelum pada minit 0–2, semasa pada 15–16 dan selepas pada 29–30.", "evidence": ["Sebelum: menyemak pakaian/kasut, menyediakan air dan memaklumkan keadaan diri.", "Semasa: menjaga ruang, memeriksa kasut apabila perlu, berehat/minum dan memaklumkan ketidakselesaan.", "Selepas: menyejukkan badan, memeriksa keadaan diri, mendapat peluang minum dan mengemas botol sendiri."], "criterion": "Persediaan dan penjagaan diri sebelum, semasa serta selepas dilihat secara berasingan. Meminta bantuan atau rehat ialah penjagaan diri, bukan kegagalan disiplin.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama: ____; sebelum: ____; semasa: ____; selepas: ____; bantuan atau keperluan tubuh: ____."]}, "5.2.1": {"method": "Pemerhatian respons sukarela ketika latihan minit 16–19 dan pertanyaan ringkas selepas minum pada 29–30.", "evidence": "Kata atau isyarat murid sendiri tentang gerakan baharu yang disukai atau kesediaan mencuba lagi; guru mencatat respons sebenar.", "criterion": "Ada ungkapan atau respons seronok yang benar-benar diperhatikan. Tidak wajib tersenyum atau bersorak; murid yang pendiam, penat atau berehat tidak terus ditanda tidak seronok.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama: ____; kata/isyarat sebenar: ____; keadaan atau bantuan: ____; belum diperhatikan: ____."]}}, "intervention": ["Murid yang belum dapat mengikuti urutan berlatih dekat guru dengan satu arahan pada satu masa. Bantuan boleh diteruskan semasa semakan.", "Jika lari tidak sesuai, gunakan berjalan dan rekod penyesuaian. Jika sakit, pening atau sukar bernafas, hentikan aktiviti dan beri perhatian mengikut tatacara sekolah.", "Jika nadi sukar dirasa, bantu ketika murid tidak bergerak atau benarkan rasa degupan dengan tapak tangan di dada. Tiada kiraan atau perubahan nadi direka.", "Ulang contoh pemanasan, penyejukan dan tiga waktu air melalui soalan lisan pendek. Sambung bukti individu yang belum lengkap dalam peluang PdP seterusnya; jangan mereka pencapaian."], "book_pages_text": "46, 47", "sp_focus": "", "sp_display": "3.1.1", "complementary": [{"standard_key": "3.1.2", "sp_code": "3.1.2", "sp_text": "Melakukan aktiviti yang boleh menurunkan kadar pernafasan dan kadar nadi.", "sk_code": "3.1", "sk_text": "Melakukan aktiviti fizikal berpandukan konsep kecergasan.", "domain": "psikomotor", "source_label": ""}, {"standard_key": "4.1.1", "sp_code": "4.1.1", "sp_text": "Mengenal pasti aktiviti memanaskan dan menyejukkan badan.", "sk_code": "4.1", "sk_text": "Mengaplikasi konsep kecergasan semasa melakukan aktiviti fizikal.", "domain": "kognitif", "source_label": ""}, {"standard_key": "4.1.2", "sp_code": "4.1.2", "sp_text": "Mengenal pasti tujuan memanaskan dan menyejukkan badan.", "sk_code": "4.1", "sk_text": "Mengaplikasi konsep kecergasan semasa melakukan aktiviti fizikal.", "domain": "kognitif", "source_label": ""}, {"standard_key": "4.1.3", "sp_code": "4.1.3", "sp_text": "Menyatakan keperluan air sebelum, semasa dan selepas melakukan aktiviti fizikal.", "sk_code": "4.1", "sk_text": "Mengaplikasi konsep kecergasan semasa melakukan aktiviti fizikal.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.1.1", "sp_code": "5.1.1", "sp_text": "Membuat persediaan diri sebelum, semasa dan selepas melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}, {"standard_key": "5.2.1", "sp_code": "5.2.1", "sp_text": "Mempamerkan rasa seronok melakukan aktiviti baharu dalam Pendidikan Jasmani.", "sk_code": "5.2", "sk_text": "Menunjukkan keyakinan dan tanggungjawab kendiri semasa melakukan aktiviti.", "domain": "afektif", "source_label": ""}], "draft_sha256": "a0a85e80e9809e3d7f1b96d410a6a14484e73f3379103eacdfa8fd967af19144"}'::jsonb,'[{"kind": "title", "text": "Minggu 33 Sesi 1 — Berjalan, lari perlahan dan regang sebelum bermain"}, {"kind": "subtitle", "text": "Pendidikan Jasmani Tahun 1 | Dua sesi seminggu | 30 minit setiap sesi | R1"}, {"kind": "p", "text": "ID: PJ1-2026B-2S-W33-S1"}, {"kind": "h2", "text": "A. Maklumat pengajaran"}, {"kind": "p", "text": "Guru: ____________________ | Kelas: __________ | Tarikh: __________ | Waktu: __________"}, {"kind": "p", "text": "Unit 7: Badan Cergas Otak Cerdas"}, {"kind": "p", "text": "Tajuk buku teks: Otot Lentur, Pergerakan Teratur"}, {"kind": "p", "text": "Aktiviti guru: Berjalan, lari perlahan dan regang sebelum bermain"}, {"kind": "p", "text": "Rujukan buku teks PJPK Tahun 1, bahagian PJ: muka surat 46, 47."}, {"kind": "p", "text": "Minit 0–2 persediaan dan nadi awal; 2–6 pemanasan; 6–10 perhatikan badan dan kenal tujuan; 10–19 latihan; 19–26 semakan individu; 26–30 penyejukan. Minum sebelum pada minit 0–1, semasa pada 9–10 dan 15–16, serta selepas pada 29–30. Mencari nadi diberi 30 saat, diikuti 30 saat merasainya ketika tidak bergerak. Rehat tambahan dibenarkan dalam waktu yang sama; kurangkan ulangan, bukan waktu penyejukan."}, {"kind": "h2", "text": "B. Standard dan hasil pembelajaran"}, {"kind": "p", "text": "SK utama 3.1: Melakukan aktiviti fizikal berpandukan konsep kecergasan."}, {"kind": "p", "text": "SP utama 3.1.1: Melakukan pelbagai jenis aktiviti seperti berjalan, berlari, dan regangan yang boleh meningkatkan suhu badan dan otot, kadar pernafasan dan kadar nadi."}, {"kind": "p", "text": "SK sokongan 3.1: Melakukan aktiviti fizikal berpandukan konsep kecergasan."}, {"kind": "p", "text": "SP sokongan 3.1.2: Melakukan aktiviti yang boleh menurunkan kadar pernafasan dan kadar nadi."}, {"kind": "p", "text": "SK sokongan 4.1: Mengaplikasi konsep kecergasan semasa melakukan aktiviti fizikal."}, {"kind": "p", "text": "SP sokongan 4.1.1: Mengenal pasti aktiviti memanaskan dan menyejukkan badan."}, {"kind": "p", "text": "SK sokongan 4.1: Mengaplikasi konsep kecergasan semasa melakukan aktiviti fizikal."}, {"kind": "p", "text": "SP sokongan 4.1.2: Mengenal pasti tujuan memanaskan dan menyejukkan badan."}, {"kind": "p", "text": "SK sokongan 4.1: Mengaplikasi konsep kecergasan semasa melakukan aktiviti fizikal."}, {"kind": "p", "text": "SP sokongan 4.1.3: Menyatakan keperluan air sebelum, semasa dan selepas melakukan aktiviti fizikal."}, {"kind": "p", "text": "SK sokongan 5.1: Mematuhi dan mengamalkan elemen pengurusan dan keselamatan."}, {"kind": "p", "text": "SP sokongan 5.1.1: Membuat persediaan diri sebelum, semasa dan selepas melakukan aktiviti Pendidikan Jasmani."}, {"kind": "p", "text": "SK sokongan 5.2: Menunjukkan keyakinan dan tanggungjawab kendiri semasa melakukan aktiviti."}, {"kind": "p", "text": "SP sokongan 5.2.1: Mempamerkan rasa seronok melakukan aktiviti baharu dalam Pendidikan Jasmani."}, {"kind": "label", "text": "Objektif"}, {"kind": "p", "text": "Murid dapat melakukan pemanasan badan dengan gerakan ringan untuk bersedia melakukan aktiviti fizikal."}, {"kind": "label", "text": "Kriteria kejayaan"}, {"kind": "p", "text": "1. Melakukan berjalan, lari perlahan setempat dan regangan mengikut contoh guru."}, {"kind": "p", "text": "2. Menamakan satu aktiviti pemanasan dan satu aktiviti penyejukan serta tujuan mudahnya."}, {"kind": "p", "text": "3. Menyatakan air diperlukan sebelum, semasa dan selepas aktiviti."}, {"kind": "p", "text": "Pengetahuan sedia ada: Murid pernah berjalan, berlari dan membawa air minuman ke kelas Pendidikan Jasmani."}, {"kind": "h2", "text": "C. Alatan, persediaan dan keselamatan"}, {"kind": "label", "text": "Kon penanda"}, {"kind": "p", "text": "Keperluan: 6 buah"}, {"kind": "p", "text": "Kegunaan: Empat kon menandakan tepi kawasan bergerak. Dua kon menandakan ruang rehat; semuanya di luar tempat pijakan murid."}, {"kind": "label", "text": "Jam randik"}, {"kind": "p", "text": "Keperluan: 1 buah untuk guru"}, {"kind": "p", "text": "Kegunaan: Menetapkan masa gerakan, rehat dan mencari nadi tanpa sasaran bilangan denyutan."}, {"kind": "label", "text": "Botol air minuman sendiri"}, {"kind": "p", "text": "Keperluan: 1 bagi setiap murid"}, {"kind": "p", "text": "Kegunaan: Diletakkan di ruang rehat untuk minum sebelum, semasa dan selepas aktiviti; tidak berkongsi botol."}, {"kind": "label", "text": "Buku teks PJPK Tahun 1"}, {"kind": "p", "text": "Keperluan: 1 naskhah guru, halaman 46–47"}, {"kind": "p", "text": "Kegunaan: Rujukan pemanasan, penyejukan dan keperluan air."}, {"kind": "label", "text": "Senarai semak dan pen guru"}, {"kind": "p", "text": "Keperluan: 1 set"}, {"kind": "p", "text": "Kegunaan: Mencatat lakuan, jawapan dan bantuan bagi murid yang benar-benar diperhatikan."}, {"kind": "label", "text": "Persediaan guru"}, {"kind": "p", "text": "1. Guru memeriksa permukaan rata, kering dan bebas halangan. Empat kon diletakkan di luar kawasan pijakan, bukan untuk dilompat."}, {"kind": "p", "text": "2. Guru menetapkan ruang sendiri dengan jarak sekurang-kurangnya dua depa antara murid. Dua kon ruang rehat berada di tepi kawasan dalam pandangan guru."}, {"kind": "p", "text": "3. Botol diletakkan di tepi ruang rehat supaya murid boleh mengambilnya tanpa melintasi rakan yang sedang bergerak. Guru menyemak kesediaan murid sebelum memulakan lari perlahan."}, {"kind": "label", "text": "Susunan dan giliran murid"}, {"kind": "p", "text": "Murid berpasangan di ruang masing-masing. Semua berlatih bersama; dalam semakan, A bergerak pada minit 20–22 dan B pada minit 22–24. Rakan yang menunggu berehat di sebelah ruang sendiri dan tidak meniru serentak. Murid tanpa pasangan berlatih berhampiran guru. Tiada perlumbaan atau pertukaran tempat. Apabila guru berkata “Berhenti”, murid berhenti di tempat yang selamat dan memandang guru."}, {"kind": "label", "text": "Petunjuk pergerakan"}, {"kind": "p", "text": "1. Pandang depan. Langkah kecil dan ringan."}, {"kind": "p", "text": "2. Regang perlahan setakat selesa. Jangan menyentap atau menarik badan rakan."}, {"kind": "p", "text": "3. Bernafas seperti biasa. Berjalan menggantikan lari jika perlu dan beritahu guru."}, {"kind": "p", "text": "4. Cari nadi hanya selepas kaki berhenti. Gunakan jari telunjuk dan jari tengah di pergelangan tangan, bukan ibu jari dan bukan di leher. Sentuh ringan."}, {"kind": "label", "text": "BBM"}, {"kind": "p", "text": "1. Kon penanda — 6 buah"}, {"kind": "p", "text": "2. Jam randik — 1 buah untuk guru"}, {"kind": "p", "text": "3. Botol air minuman sendiri — 1 bagi setiap murid"}, {"kind": "p", "text": "4. Buku teks PJPK Tahun 1 — 1 naskhah guru, halaman 46–47"}, {"kind": "p", "text": "5. Senarai semak dan pen guru — 1 set"}, {"kind": "p", "text": "6. Buku teks dan senarai semak pemerhatian guru."}, {"kind": "p", "text": "PAK-21: Murid meniru contoh guru, berlatih berpasangan dan bergilir menunjukkan urutan pemanasan. Rakan mengingatkan “langkah kecil” atau “jaga jarak”. Jawapan bersama hanya latihan; guru mendapatkan lakuan dan jawapan setiap murid secara berasingan."}, {"kind": "p", "text": "Nilai: Kerjasama, disiplin dan menjaga keselamatan rakan."}, {"kind": "label", "text": "Keselamatan"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula."}, {"kind": "p", "text": "2. Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan."}, {"kind": "p", "text": "3. Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan."}, {"kind": "p", "text": "4. Nadi dicari semasa berdiri atau duduk stabil sahaja. Guru menunjukkan dua jari pada pergelangan tangannya sendiri; bantuan pada tangan murid diberi dengan izin dan tanpa menekan kuat. Jika nadi sukar dirasa, murid boleh merasai degupan dengan tapak tangan di dada ketika berhenti atau memberitahu guru bahawa nadi belum ditemui. Tiada kiraan denyutan wajib."}, {"kind": "p", "text": "5. Murid tidak perlu berlari laju untuk merasai perubahan badan. Rasa panas, pernafasan dan nadi mungkin berbeza antara murid; tiada perubahan tertentu dijadikan syarat lulus."}, {"kind": "p", "text": "6. Guru memberi masa berhenti dan minum di ruang rehat. Murid tidak minum sambil berlari atau dipaksa menghabiskan air."}, {"kind": "p", "text": "Jika cuaca atau ruang tidak sesuai: Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat."}, {"kind": "h2", "text": "D. Langkah PdP"}, {"kind": "h3", "text": "Langkah 1: Persediaan, minum dan rasa nadi awal — 2 minit"}, {"kind": "p", "text": "Minit 0 hingga 2."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minit 0–1: guru menyemak pakaian, tali kasut dan keadaan murid. Guru menunjukkan ruang sendiri, ruang rehat dan arahan “Berhenti”, kemudian memberi peluang minum sebelum bergerak."}, {"kind": "p", "text": "2. Minit 1–2: guru meminta semua berhenti dan berdiri atau duduk stabil. Guru menunjukkan jari telunjuk dan jari tengah pada pergelangan tangan, bukan ibu jari atau leher; beri 30 saat mencari dan 30 saat merasai nadi tanpa mengira."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid membetulkan pakaian atau meminta bantuan mengikat kasut. Murid memberitahu jika tidak sihat dan minum mengikut keperluan."}, {"kind": "p", "text": "2. Murid tidak melangkah semasa mencari nadi. Murid merasai keadaan badan dan pernafasan sebelum bergerak; jika belum jumpa nadi, murid meminta bantuan."}, {"kind": "p", "text": "Semakan: Guru mencatat persediaan sebelum aktiviti bagi 5.1.1. Pemerhatian awal nadi, pernafasan dan rasa badan bukan ujian nombor denyutan."}, {"kind": "p", "text": "Alatan: Kon penanda Botol air minuman sendiri Jam randik"}, {"kind": "h3", "text": "Langkah 2: Pemanasan: jalan, lari perlahan dan regang — 4 minit"}, {"kind": "p", "text": "Minit 2 hingga 6."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minit 2–3: guru memimpin berjalan setempat. Minit 3–4: guru memimpin lari perlahan setempat dengan langkah kecil; berjalan dibenarkan jika lebih sesuai."}, {"kind": "p", "text": "2. Minit 4–5: guru menunjukkan membuka tangan ke sisi dan merapatkannya semula dengan lembut. Minit 5–6: guru menunjukkan regangan betis dengan satu kaki sedikit ke belakang, tumit di lantai dan lutut depan dibengkokkan sedikit; tukar kaki tanpa henjutan."}, {"kind": "p", "text": "3. Guru menerangkan bahawa gerakan pemanasan boleh membuat badan dan otot lebih panas, nafas lebih cepat serta nadi lebih cepat. Guru tidak meminta murid berusaha sehingga terlalu penat."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid berjalan dan mencuba lari perlahan dalam ruang sendiri. Murid bernafas seperti biasa dan mengekalkan jarak."}, {"kind": "p", "text": "2. Murid membuka dan merapatkan tangan, kemudian meregangkan betis kanan dan kiri setakat selesa. Murid berhenti dan memaklumkan guru jika sakit atau pening."}, {"kind": "p", "text": "Semakan: PBD 3.1.1: guru melihat berjalan, lari perlahan dan regangan setiap murid yang sempat diperhatikan. Penyesuaian berjalan menggantikan lari dicatat, bukan disamakan dengan larian."}, {"kind": "p", "text": "Alatan: Kon penanda Jam randik Ruang rata"}, {"kind": "h3", "text": "Langkah 3: Perhatikan badan dan kenal tujuan — 4 minit"}, {"kind": "p", "text": "Minit 6 hingga 10."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minit 6–7: guru mengarahkan semua berhenti di tempat selamat. Beri 30 saat mencari nadi di pergelangan tangan dengan dua jari dan 30 saat merasainya; tanya perubahan sebenar pada rasa panas badan, pernafasan dan nadi."}, {"kind": "p", "text": "2. Minit 7–8: guru merujuk buku halaman 46–47. Guru menamakan berjalan dan lari perlahan sebagai pemanasan untuk menyediakan badan; berjalan perlahan dan regangan lembut selepas aktiviti membantu badan kembali tenang."}, {"kind": "p", "text": "3. Minit 8–9: guru memberi contoh soalan pendek tentang aktiviti pemanasan, penyejukan dan tujuan masing-masing. Minit 9–10: semua berehat dan mendapat peluang minum; guru menyebut air diperlukan sebelum, semasa dan selepas aktiviti supaya badan cukup air."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid kekal tidak bergerak ketika merasai nadi. Murid menyebut apa yang benar-benar dirasai, termasuk “belum jumpa” atau “belum rasa beza”."}, {"kind": "p", "text": "2. Murid bergilir menamakan satu aktiviti pemanasan dan satu aktiviti penyejukan kepada pasangan. Murid menyatakan tujuan dengan kata mudah seperti “bersedia bergerak” dan “badan kembali tenang”."}, {"kind": "p", "text": "3. Murid minum di ruang rehat. Murid menyebut bahawa air diperlukan sebelum, semasa dan selepas bergerak apabila ditanya guru."}, {"kind": "p", "text": "Semakan: PBD 4.1.1, 4.1.2 dan 4.1.3: guru mendengar jawapan individu yang dipanggil. Jawapan pasangan atau kelas tidak dijadikan bukti murid lain."}, {"kind": "p", "text": "Alatan: Buku teks halaman 46–47 Botol air minuman sendiri Jam randik"}, {"kind": "h3", "text": "Langkah 4: Latihan urutan pemanasan dengan bimbingan — 9 minit"}, {"kind": "p", "text": "Minit 10 hingga 19."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minit 10–11: guru mengulang urutan jalan, lari perlahan dan regang. Guru memberi bimbingan Peneroka, Pembina atau Pencabar dalam aktiviti yang sama, bukan tiga pusingan tambahan."}, {"kind": "p", "text": "2. Minit 11–14: bimbing berjalan 1 minit, lari perlahan setempat 1 minit dan regangan tangan serta betis 1 minit. Guru mendekati murid yang memerlukan contoh semula."}, {"kind": "p", "text": "3. Minit 14–15: semua berhenti; beri 30 saat mencari dan 30 saat merasai nadi dengan dua jari pada pergelangan tangan. Minit 15–16: beri rehat dan minum; semak tali kasut, jarak serta keadaan badan sebelum sambung."}, {"kind": "p", "text": "4. Minit 16–18: ulang urutan ringkas, iaitu jalan 30 saat, lari perlahan 30 saat dan regangan 1 minit. Minit 18–19: semua berhenti dan berehat; guru mendengar jawapan ringkas tentang badan dan keperluan air."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid mengikuti urutan dengan bantuan yang sesuai. Murid tidak menambah kelajuan untuk mengejar rakan."}, {"kind": "p", "text": "2. Murid berhenti sebelum menyentuh pergelangan tangan. Murid memberitahu guru jika tidak dapat merasai nadi dan tidak meneka bilangannya."}, {"kind": "p", "text": "3. Semasa rehat, murid minum mengikut keperluan, memeriksa kasut dan memberitahu jika letih. Murid menyebut bahawa air diperlukan juga semasa aktiviti."}, {"kind": "p", "text": "4. Murid mencuba urutan pendek sekali lagi jika selesa. Selepas berhenti, murid bergilir memberitahu gerakan yang disukai atau jika belum selesa."}, {"kind": "p", "text": "Semakan: Guru merekod lakuan individu 3.1.1, persediaan semasa 5.1.1, jawapan air 4.1.3 dan respons sukarela 5.2.1. Bantuan, rehat dan gerakan yang tidak dibuat direkod secara berasingan."}, {"kind": "p", "text": "Alatan: Kon penanda Jam randik Botol air minuman sendiri Senarai semak dan pen guru"}, {"kind": "h3", "text": "Langkah 5: Giliran menunjukkan pemanasan dan semakan individu — 7 minit"}, {"kind": "p", "text": "Minit 19 hingga 26."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minit 19–20: guru menetapkan pasangan A dan B serta mengulang arahan berhenti. Guru memilih murid untuk diperhatikan tanpa menghalang pandangan terhadap murid lain."}, {"kind": "p", "text": "2. Minit 20–22: A menunjukkan jalan 30 saat, lari perlahan 30 saat dan regangan 1 minit. Minit 22–24: B melakukan urutan yang sama; pasangan yang menunggu berehat dan memberi satu peringatan sopan."}, {"kind": "p", "text": "3. Minit 24–25: ketika semua berehat, guru mendapatkan jawapan individu tentang contoh dan tujuan pemanasan serta penyejukan. Guru meminta murid melengkapkan sebutan air sebelum, semasa dan selepas aktiviti."}, {"kind": "p", "text": "4. Minit 25–26: semua kekal berhenti; beri 30 saat mencari dan 30 saat merasai nadi di pergelangan tangan sebagai pemerhatian sebelum penyejukan. Guru mencatat murid yang belum sempat diperhatikan untuk susulan."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid menjalani giliran sendiri. Rakan yang menunggu tidak menyentuh atau menggerakkan badan murid."}, {"kind": "p", "text": "2. Murid menunjukkan urutan pemanasan dengan langkah kecil dan regangan lembut. Berjalan atau rehat dibenarkan jika perlu; murid memberitahu guru."}, {"kind": "p", "text": "3. Murid menjawab guru secara bergilir dengan ayat pendek. Murid boleh menerima pilihan lisan atau contoh semula."}, {"kind": "p", "text": "4. Murid mencari nadi hanya ketika kaki berhenti dan bernafas seperti biasa. Murid menyimpan pemerhatian sendiri untuk dibandingkan selepas penyejukan."}, {"kind": "p", "text": "Semakan: Semakan 3.1.1 dibuat pada lakuan setiap murid yang benar-benar dilihat. Jawapan 4.1.1, 4.1.2 dan 4.1.3 dicatat mengikut nama, termasuk bantuan; tidak semua ditanda selesai secara automatik."}, {"kind": "p", "text": "Alatan: Kon penanda Jam randik Senarai semak dan pen guru"}, {"kind": "h3", "text": "Langkah 6: Penyejukan, nadi selepas dan minum — 4 minit"}, {"kind": "p", "text": "Minit 26 hingga 30."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minit 26–27: guru memimpin berjalan perlahan setempat. Minit 27–28: guru membimbing regangan tangan dan betis kanan serta kiri secara lembut tanpa henjutan."}, {"kind": "p", "text": "2. Minit 28–29: guru meminta semua berhenti dan berdiri atau duduk stabil. Beri 30 saat mencari dan 30 saat merasai nadi dengan dua jari di pergelangan tangan; tanya keadaan nafas dan nadi berbanding sebelum penyejukan, tanpa menentukan jawapan."}, {"kind": "p", "text": "3. Minit 29–30: guru memberi peluang minum selepas aktiviti. Guru bertanya tujuan penyejukan, memeriksa keadaan murid dan membenarkan murid mengemas botol sendiri; kon dikemas selepas kawasan kosong."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid berjalan perlahan, kemudian meregang dengan lembut dan bernafas seperti biasa. Murid tidak berlari lagi selepas penyejukan."}, {"kind": "p", "text": "2. Murid berhenti sebelum mencari nadi. Murid melaporkan rasa sebenar; belum dapat merasai perubahan diterima dan dibantu."}, {"kind": "p", "text": "3. Murid menyatakan air diperlukan selepas aktiviti, minum mengikut keperluan dan memeriksa keadaan diri. Murid memberitahu guru jika masih tidak selesa atau mahu berkongsi gerakan yang disukai."}, {"kind": "p", "text": "Semakan: PBD 3.1.2: lakuan penyejukan individu; 4.1.1 dan 4.1.2: contoh serta tujuan penyejukan; 4.1.3 dan 5.1.1: air serta urus diri selepas aktiviti. Nadi tidak perlu menunjukkan penurunan tertentu untuk membuktikan lakuan."}, {"kind": "p", "text": "Alatan: Botol air minuman sendiri Jam randik Ruang rehat Senarai semak dan pen guru"}, {"kind": "p", "text": "Jumlah masa: 30 minit."}, {"kind": "label", "text": "Contoh arahan kelas"}, {"kind": "p", "text": "Guru: Jalan dahulu. Sekarang lari perlahan di tempat sendiri. Kemudian regang tangan. Selepas berhenti, beritahu cikgu apa yang kamu rasa."}, {"kind": "p", "text": "Murid: Murid melakukan gerakan sendiri. Selepas berhenti, murid boleh berkata “Badan saya rasa panas”, “Nafas saya lebih cepat” atau “Saya belum rasa beza”."}, {"kind": "p", "text": "Semakan guru: Guru melihat gerakan dan mendengar pengalaman sebenar. Murid tidak perlu memberi jawapan bahawa nadinya pasti meningkat."}, {"kind": "h2", "text": "E. PdP terbeza", "anchor": "pdp-PJ1-2026B-2S-W33-S1"}, {"kind": "p", "text": "Tugasan bersama: Murid dapat melakukan pemanasan badan dengan gerakan ringan untuk bersedia melakukan aktiviti fizikal."}, {"kind": "p", "text": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan."}, {"kind": "label", "text": "Bimbingan guru"}, {"kind": "p", "text": "1. Minit 0–2: lihat persediaan sebelum dan bantu nadi awal."}, {"kind": "p", "text": "2. Minit 2–10: lihat gerakan pemanasan dan dengar jawapan individu yang sempat dipanggil."}, {"kind": "p", "text": "3. Minit 11–19: guru bergerak dari pasangan ke pasangan, memberi bantuan dan mencatat persediaan semasa serta respons murid."}, {"kind": "p", "text": "4. Minit 20–24: semak lakuan A kemudian B. Minit 24–26: dengar jawapan dan perhatikan nadi ketika berhenti."}, {"kind": "p", "text": "5. Minit 26–30: semak penyejukan dan persediaan selepas. Senaraikan nama serta aspek yang belum sempat diperhatikan; jangan mengisi bukti berdasarkan jawapan kelas."}, {"kind": "p", "text": "Semakan individu: Melakukan berjalan, lari perlahan setempat dan regangan mengikut contoh guru."}, {"kind": "p", "text": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, {"kind": "h3", "text": "Peneroka"}, {"kind": "p", "text": "Guru membimbing satu langkah pada satu masa."}, {"kind": "p", "text": "Tugasan: Melakukan urutan pemanasan yang sama sambil meniru guru dari dekat."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Ruang sendiri dalam sempadan kon"}, {"kind": "p", "text": "2. Jam randik guru"}, {"kind": "p", "text": "3. Botol air sendiri"}, {"kind": "p", "text": "4. Buku teks halaman 46–47 untuk contoh guru"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru berdiri dalam pandangan murid dan memberi arahan satu demi satu: “jalan”, “lari perlahan”, “regang”. Guru menunjukkan semula regangan betis tanpa memegang atau menarik murid."}, {"kind": "p", "text": "2. Guru membimbing lokasi nadi pada pergelangan tangan selepas murid berhenti. Guru memberi pilihan lisan tentang tujuan dan mengulang kata “sebelum, semasa, selepas” sambil merujuk waktu minum sebenar."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Sebelum bergerak, periksa kasut dan pakaian dengan bantuan guru. Minum jika perlu. Berhenti untuk mencari nadi awal selama 30 saat dan merasainya 30 saat dengan dua jari di pergelangan tangan."}, {"kind": "p", "text": "2. Semasa pemanasan dan latihan, ikut guru berjalan, lari perlahan setempat dan meregang tangan serta betis. Selepas berhenti, rasa nadi dan pernafasan serta beritahu rasa panas badan. Sebut contoh pemanasan dan tujuannya, iaitu menyediakan badan."}, {"kind": "p", "text": "3. Dalam rehat semasa latihan, minum dan beritahu jika letih; periksa kasut serta ruang sendiri. Sebut “Air diperlukan sebelum, semasa dan selepas aktiviti”. Pada giliran sendiri, tunjuk urutan pemanasan yang sama dengan bimbingan."}, {"kind": "p", "text": "4. Selepas aktiviti, berjalan perlahan dan regang lembut bersama guru. Sebut ini penyejukan untuk membantu badan kembali tenang. Berhenti, cari nadi 30 saat dan rasa 30 saat; minum selepas, kemas botol dan beritahu keadaan diri serta aktiviti yang disukai jika mahu."}, {"kind": "p", "text": "Contoh guru: Kita jalan dahulu. Selepas bermain nanti, jalan bagaimana? Bila badan perlukan air?"}, {"kind": "p", "text": "Contoh respons murid: Murid berjalan mengikut guru, kemudian menjawab “Perlahan. Air sebelum, semasa dan selepas.”"}, {"kind": "p", "text": "Hasil individu: Urutan pemanasan individu yang dilihat guru, diikuti lakuan penyejukan dan jawapan ringkas tentang tujuan, air serta pengalaman badan."}, {"kind": "p", "text": "Kriteria: Murid menunjukkan berjalan, percubaan lari perlahan dan regangan dengan bantuan; contoh serta tujuan pemanasan dan penyejukan, air sebelum/semasa/selepas dan persediaan diri diperiksa satu demi satu. Jika lari diganti berjalan, guru mencatat penyesuaian sebenar."}, {"kind": "p", "text": "Susulan: Kekalkan contoh bersebelahan dan arahan pendek. Jika nadi belum dirasa, ulang ketika berhenti atau rasa degupan di dada; jangan menambah larian untuk mencari perubahan."}, {"kind": "h3", "text": "Pembina"}, {"kind": "p", "text": "Murid berlatih berpasangan dan melakukan sendiri."}, {"kind": "p", "text": "Tugasan: Melatih dan menunjukkan urutan jalan, lari perlahan dan regangan secara bergilir."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Ruang pasangan dengan kon di tepi"}, {"kind": "p", "text": "2. Jam randik guru"}, {"kind": "p", "text": "3. Botol air sendiri"}, {"kind": "p", "text": "4. Buku teks halaman 46–47"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan urutan sebelum pasangan mencuba. Guru mengingatkan langkah kecil dan membetulkan kedudukan tumit semasa regangan betis melalui contoh semula."}, {"kind": "p", "text": "2. Guru menyemak setiap murid ketika giliran sendiri. Guru membantu mencari nadi selepas berhenti dan memberi soalan pendek berasingan untuk tujuan pemanasan, tujuan penyejukan dan waktu air diperlukan."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Sebelum aktiviti, periksa pakaian, kasut dan ruang; beritahu guru jika tidak sihat. Minum jika perlu. Berhenti untuk mencari nadi 30 saat dan merasainya 30 saat dengan dua jari di pergelangan tangan."}, {"kind": "p", "text": "2. Ikut latihan jalan, lari perlahan setempat dan regangan tangan serta betis. Selepas berhenti, rasa nadi dan beritahu keadaan nafas serta rasa panas badan. Namakan satu gerakan pemanasan dan sebut tujuannya untuk bersedia bergerak."}, {"kind": "p", "text": "3. Semasa rehat yang ditetapkan, minum, periksa kasut dan maklumkan jika letih. Sebut air diperlukan sebelum, semasa dan selepas aktiviti. Bergilir menunjukkan urutan pemanasan; pasangan berehat dan memberi peringatan sopan."}, {"kind": "p", "text": "4. Selepas aktiviti, lakukan berjalan perlahan dan regangan lembut. Namakan penyejukan serta tujuannya membantu badan kembali tenang. Berhenti, cari nadi 30 saat dan rasa 30 saat. Minum selepas, kemas botol dan beritahu keadaan diri serta gerakan yang disukai jika mahu."}, {"kind": "p", "text": "Contoh guru: Tunjukkan urutan kamu. Mengapa kita panaskan badan? Selepas bergerak, bagaimana kita tenangkan badan?"}, {"kind": "p", "text": "Contoh respons murid: Murid berjalan, lari perlahan dan regang; kemudian berkata “Supaya bersedia. Selepas itu jalan perlahan dan regang lembut.”"}, {"kind": "p", "text": "Hasil individu: Lakuan urutan pemanasan setiap murid, penyejukan sendiri dan jawapan individu; rakan bukan pengganti bukti guru."}, {"kind": "p", "text": "Kriteria: Murid melakukan urutan dengan ruang yang selamat dan mengenal contoh serta tujuan kedua-dua rutin. Guru menyemak air dan persediaan sebelum, semasa dan selepas tanpa menetapkan perubahan nadi wajib."}, {"kind": "p", "text": "Susulan: Ulang bahagian urutan yang belum jelas bersama guru. Teruskan bantuan lisan atau pilihan jawapan; murid yang berehat diberi peluang susulan tanpa hukuman."}, {"kind": "h3", "text": "Pencabar"}, {"kind": "p", "text": "Murid memperkemas satu perkara dalam kemahiran yang sama."}, {"kind": "p", "text": "Tugasan: Memperkemas langkah kecil dan regangan dalam urutan pemanasan yang sama."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Ruang sendiri dengan kon di luar pijakan"}, {"kind": "p", "text": "2. Jam randik guru"}, {"kind": "p", "text": "3. Botol air sendiri"}, {"kind": "p", "text": "4. Buku teks halaman 46–47"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan cara menukar daripada jalan kepada lari perlahan tanpa keluar dari ruang sendiri. Guru mengingatkan murid merendahkan kelajuan, bukan menambah ulangan."}, {"kind": "p", "text": "2. Guru membimbing semakan nadi ketika berhenti dan meminta jawapan mudah, bukan penjelasan panjang. Guru terus memberi contoh untuk tujuan pemanasan, penyejukan dan air jika diperlukan."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Sebelum aktiviti, semak kasut, pakaian dan ruang sendiri; sediakan botol dan minum jika perlu. Berhenti untuk mencari nadi 30 saat serta merasainya 30 saat dengan dua jari pada pergelangan tangan."}, {"kind": "p", "text": "2. Lakukan jalan, lari perlahan setempat dan regangan tangan serta betis. Perkemas langkah supaya tidak menghampiri rakan. Selepas berhenti, beritahu rasa panas badan, nafas dan nadi yang sebenar; namakan pemanasan dan tujuan menyediakan badan."}, {"kind": "p", "text": "3. Semasa rehat, minum dan semak semula keadaan diri serta kasut. Sebut air diperlukan sebelum, semasa dan selepas aktiviti. Pada giliran individu, tunjuk urutan yang sama dengan regangan lebih terkawal, bukan lebih kuat."}, {"kind": "p", "text": "4. Selepas aktiviti, berjalan perlahan dan regang lembut. Namakan rutin penyejukan dan tujuannya membantu badan kembali tenang. Berhenti, cari nadi 30 saat dan rasa 30 saat, kemudian minum selepas dan kemas botol. Beritahu jika tidak selesa atau mahu berkongsi gerakan yang menyeronokkan."}, {"kind": "p", "text": "Contoh guru: Boleh kekalkan langkah kecil di tempat sendiri? Apakah gerakan kita selepas selesai?"}, {"kind": "p", "text": "Contoh respons murid: Murid memperkemas langkah dan menjawab “Jalan perlahan dan regang supaya badan kembali tenang.”"}, {"kind": "p", "text": "Hasil individu: Urutan pemanasan individu dengan kawalan ruang, lakuan penyejukan serta jawapan ringkas yang diperhatikan guru."}, {"kind": "p", "text": "Kriteria: Murid memperkemas kawalan langkah dalam kemahiran yang sama. Contoh dan tujuan pemanasan/penyejukan, air serta persediaan sebelum/semasa/selepas tetap disemak; kelajuan dan perubahan nadi bukan ukuran tambahan."}, {"kind": "p", "text": "Susulan: Berikan satu maklum balas tentang ruang atau regangan. Kembali kepada contoh guru bila perlu; tiada tambahan beban, jarak atau bilangan gerakan."}, {"kind": "h2", "text": "F. Pentaksiran Bilik Darjah"}, {"kind": "h3", "text": "PBD utama — SP 3.1.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian lakuan individu pada minit 2–6, 11–14 dan giliran 20–24."}, {"kind": "p", "text": "Bukti: Gerakan berjalan, lari perlahan setempat dan regangan tangan/betis setiap murid yang dilihat. Laporan sebenar tentang rasa panas badan, pernafasan dan nadi selepas berhenti pada minit 6–7 atau 14–15; bukan jawapan peningkatan yang ditetapkan."}, {"kind": "p", "text": "Kriteria: Murid melakukan urutan pemanasan dengan gerakan ringan dan selamat. Bantuan dibenarkan. Jika larian diganti berjalan, nyatakan lakuan sebenar; laporan nadi bukan syarat wajib meningkat."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama murid: ____; berjalan: ____; lari perlahan atau penyesuaian: ____; regangan: ____."}, {"kind": "p", "text": "2. Pemerhatian badan/nafas/nadi: ____; bantuan atau rehat: ____; belum diperhatikan: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 3.1.2"}, {"kind": "p", "text": "Kaedah: Pemerhatian setiap murid semasa penyejukan pada minit 26–28; semakan rasa nadi dan nafas ketika berhenti pada minit 28–29."}, {"kind": "p", "text": "Bukti: Lakuan berjalan perlahan dan regangan lembut; laporan sebenar selepas penyejukan berbanding pemerhatian berhenti pada minit 25–26."}, {"kind": "p", "text": "Kriteria: Murid melakukan aktiviti penyejukan dengan perlahan dan bernafas seperti biasa. Tiada penurunan nadi tertentu atau kiraan denyutan diwajibkan."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama: ____; berjalan perlahan: ____; regangan lembut: ____; bantuan: ____."}, {"kind": "p", "text": "2. Nadi/nafas sebelum dan selepas yang dilaporkan: ____; belum dapat dirasa: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 4.1.1"}, {"kind": "p", "text": "Kaedah: Soal jawab individu pada minit 8–9 dan 24–25; lengkapkan contoh penyejukan semasa penutup 29–30 jika sempat."}, {"kind": "p", "text": "Bukti: Murid menamakan satu aktiviti memanaskan badan dan satu aktiviti menyejukkan badan yang dilakukan sendiri."}, {"kind": "p", "text": "Kriteria: Murid mengenal kedua-duanya, contohnya lari perlahan untuk pemanasan serta berjalan perlahan selepas aktiviti untuk penyejukan. Pilihan lisan guru dibenarkan dan dicatat."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama: ____; contoh pemanasan: ____; contoh penyejukan: ____; bantuan: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 4.1.2"}, {"kind": "p", "text": "Kaedah: Guru menyoal tujuan pemanasan dan tujuan penyejukan secara berasingan pada minit 8–9, 24–25 dan 29–30."}, {"kind": "p", "text": "Bukti: Jawapan individu seperti “Badan bersedia bergerak” dan “Badan kembali tenang selepas bergerak”."}, {"kind": "p", "text": "Kriteria: Murid mengenal tujuan kedua-dua rutin dengan bahasa mudah. Guru boleh memberi dua pilihan lisan; tidak perlu penerangan sebab yang panjang."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama: ____; tujuan pemanasan: ____; tujuan penyejukan: ____; contoh/bantuan lisan: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 4.1.3"}, {"kind": "p", "text": "Kaedah: Soal jawab individu ketika rehat minum minit 9–10 dan 15–16, serta selepas aktiviti 29–30. Guru meminta murid melengkapkan ketiga-tiga waktu."}, {"kind": "p", "text": "Bukti: Sebutannya sendiri bahawa air diperlukan sebelum, semasa dan selepas melakukan aktiviti; tindakan minum sahaja tidak menggantikan jawapan ini."}, {"kind": "p", "text": "Kriteria: Murid menyatakan ketiga-tiga waktu air diperlukan. Tiada jumlah gelas, kuota air atau syarat menghabiskan botol."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama: ____; menyebut sebelum: ____; semasa: ____; selepas: ____; bantuan/jawapan belum diperoleh: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 5.1.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian individu sebelum pada minit 0–2, semasa pada 15–16 dan selepas pada 29–30."}, {"kind": "p", "text": "Bukti: Sebelum: menyemak pakaian/kasut, menyediakan air dan memaklumkan keadaan diri. Semasa: menjaga ruang, memeriksa kasut apabila perlu, berehat/minum dan memaklumkan ketidakselesaan. Selepas: menyejukkan badan, memeriksa keadaan diri, mendapat peluang minum dan mengemas botol sendiri."}, {"kind": "p", "text": "Kriteria: Persediaan dan penjagaan diri sebelum, semasa serta selepas dilihat secara berasingan. Meminta bantuan atau rehat ialah penjagaan diri, bukan kegagalan disiplin."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama: ____; sebelum: ____; semasa: ____; selepas: ____; bantuan atau keperluan tubuh: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 5.2.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian respons sukarela ketika latihan minit 16–19 dan pertanyaan ringkas selepas minum pada 29–30."}, {"kind": "p", "text": "Bukti: Kata atau isyarat murid sendiri tentang gerakan baharu yang disukai atau kesediaan mencuba lagi; guru mencatat respons sebenar."}, {"kind": "p", "text": "Kriteria: Ada ungkapan atau respons seronok yang benar-benar diperhatikan. Tidak wajib tersenyum atau bersorak; murid yang pendiam, penat atau berehat tidak terus ditanda tidak seronok."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama: ____; kata/isyarat sebenar: ____; keadaan atau bantuan: ____; belum diperhatikan: ____."}, {"kind": "h2", "text": "G. Refleksi dan intervensi"}, {"kind": "p", "text": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________."}, {"kind": "label", "text": "Intervensi"}, {"kind": "p", "text": "1. Murid yang belum dapat mengikuti urutan berlatih dekat guru dengan satu arahan pada satu masa. Bantuan boleh diteruskan semasa semakan."}, {"kind": "p", "text": "2. Jika lari tidak sesuai, gunakan berjalan dan rekod penyesuaian. Jika sakit, pening atau sukar bernafas, hentikan aktiviti dan beri perhatian mengikut tatacara sekolah."}, {"kind": "p", "text": "3. Jika nadi sukar dirasa, bantu ketika murid tidak bergerak atau benarkan rasa degupan dengan tapak tangan di dada. Tiada kiraan atau perubahan nadi direka."}, {"kind": "p", "text": "4. Ulang contoh pemanasan, penyejukan dan tiga waktu air melalui soalan lisan pendek. Sambung bukti individu yang belum lengkap dalam peluang PdP seterusnya; jangan mereka pencapaian."}]'::jsonb,'{"source_hold": "", "adaptation_note": "Pemanasan, penyejukan dan air sebelum, semasa serta selepas diajar. Nadi diperhatikan pada pergelangan tangan ketika berhenti; tiada sasaran denyut, kiraan bpm wajib atau jawapan peningkatan direka. Keperluan air Tahun1 tidak sama dengan standard kuantiti Tahun3.", "source_images_verified": true, "audio_verified": false, "ba_verified": false, "classroom_trial_performed": false}'::jsonb),
  ('PJ1-2026B-2S-W33-S2','pj',1,2026,33,2,30,'3.1.2',array[46,47]::int[],'ec019bc4dc2b74ee3f36d30014316c9e7971047a21cf28002fb9383810fbe087','8e6d3ab63f7be3d7d431fde287c893d8c38fc85c24e11c2b943ca7bf67f7b731','715d2dd93e616381f7de4fb5e317e008bae7007088b12831c3d9d17a2be5d6d7','ACCEPTED_FROM_DOWNLOADED_CATATAN',false,'{"id": "PJ1-2026B-2S-W33-S2", "subject": "Pendidikan Jasmani", "year": 1, "week": 33, "session": 2, "revision": "PJ1-30MIN-REVIEW-R1", "date": "", "teaching_time": "", "minutes": 30, "sessions_per_week": 2, "weekly_minutes": 60, "title": "Otot Lentur, Pergerakan Teratur", "source_title": "Otot Lentur, Pergerakan Teratur", "unit": "Unit 7: Badan Cergas Otak Cerdas", "source_row_id": "PJ1-RPT2026-T11-R3", "source_row_literal": ["33\n\nKump A: 20.09.2026-24.09.2026\n\nKump B: 21.09.2026-\n25.09.2026", "7: BADAN CERGAS OTAK CERDAS\nOTOT LENTUR, PERGERAKAN TERATUR.", "3.1 Melakukan aktiviti fizikal berpandukan konsep kecergasan. \n4.1 Mengaplikasi konsep kecergasan semasa melakukan aktiviti fizikal\n5.1 Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.\n\n5.2 Menunjukkan keyakinan dan tanggungjawab kendiri semasa melakukan aktiviti.", "3.1.1 Melakukan pelbagai jenis aktiviti seperti berjalan, berlari, dan regangan yang boleh meningkatkan suhu badan dan otot, kadar pernafasan, dan kadar nadi. \n3.1.2 Melakukan aktiviti yang boleh menurunkan kadar pernafasan dan kadar nadi. \n\n4.1.1 Mengenal pasti aktiviti memanaskan dan menyejukkan badan. \n4.1.2 Mengenal pasti tujuan memanaskan dan menyejukkan badan. \n4.1.3 Menyatakan keperluan air sebelum, semasa, dan selepas melakukan aktiviti fizikal \n\n5.1.1 Membuat persediaan diri sebelum, semasa, dan selepas melakukan aktiviti Pendidikan Jasmani.\n5.2.1 Mempamerkan rasa seronok melakukan aktiviti baharu dalam Pendidikan Jasmani", "AKTIVITI PAK-21\nRecap Group (Mengulangi / mengingat semula)\nBrainstorming (Sumbangsaran)\nBBB/BBM\nBT m/s 46-47\n\nEMK \nKreativiti dan Inovasi\nKBAT\nMengaplikasi Memahami\n\nNILAI\nKerjasama Toleransi"], "rpt_original_page_literal": "46-47", "source_pages": [46, 47], "source_pdf_pages": [54, 55], "rpt_book_pages": "46, 47", "main_standard_key": "3.1.2", "sk_code": "3.1", "sk_text": "Melakukan aktiviti fizikal berpandukan konsep kecergasan.", "sp_code": "3.1.2", "sp_text": "Melakukan aktiviti yang boleh menurunkan kadar pernafasan dan kadar nadi.", "complementary_standards": [{"standard_key": "3.1.1", "sp_code": "3.1.1", "sp_text": "Melakukan pelbagai jenis aktiviti seperti berjalan, berlari, dan regangan yang boleh meningkatkan suhu badan dan otot, kadar pernafasan dan kadar nadi.", "sk_code": "3.1", "sk_text": "Melakukan aktiviti fizikal berpandukan konsep kecergasan.", "domain": "psikomotor", "source_label": ""}, {"standard_key": "4.1.1", "sp_code": "4.1.1", "sp_text": "Mengenal pasti aktiviti memanaskan dan menyejukkan badan.", "sk_code": "4.1", "sk_text": "Mengaplikasi konsep kecergasan semasa melakukan aktiviti fizikal.", "domain": "kognitif", "source_label": ""}, {"standard_key": "4.1.2", "sp_code": "4.1.2", "sp_text": "Mengenal pasti tujuan memanaskan dan menyejukkan badan.", "sk_code": "4.1", "sk_text": "Mengaplikasi konsep kecergasan semasa melakukan aktiviti fizikal.", "domain": "kognitif", "source_label": ""}, {"standard_key": "4.1.3", "sp_code": "4.1.3", "sp_text": "Menyatakan keperluan air sebelum, semasa dan selepas melakukan aktiviti fizikal.", "sk_code": "4.1", "sk_text": "Mengaplikasi konsep kecergasan semasa melakukan aktiviti fizikal.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.1.1", "sp_code": "5.1.1", "sp_text": "Membuat persediaan diri sebelum, semasa dan selepas melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}, {"standard_key": "5.2.1", "sp_code": "5.2.1", "sp_text": "Mempamerkan rasa seronok melakukan aktiviti baharu dalam Pendidikan Jasmani.", "sk_code": "5.2", "sk_text": "Menunjukkan keyakinan dan tanggungjawab kendiri semasa melakukan aktiviti.", "domain": "afektif", "source_label": ""}], "source_task": "Memperlahankan gerakan dan menjaga keperluan air", "authoring_focus": "Memperlahankan gerakan dan menjaga keperluan air", "source_hold": "Teks RPT, DSKP dan buku dibaca. Semakan imej guling BT35 dan kod DSKP hlm70 terhalang ralat402; OCR dan teks salinan menyokong kod berulang, bukan kelulusan visual. Guru perlu menilai postur, alat dan kesediaan setiap murid.", "practical_required": true, "warmup_required": true, "cooldown_required": true, "facility_replacement": false, "facility_replacement_note": "", "source_subset_focus": false, "source_subset_note": "", "adaptation_note": "Pemanasan, penyejukan dan air sebelum, semasa serta selepas diajar. Nadi diperhatikan pada pergelangan tangan ketika berhenti; tiada sasaran denyut, kiraan bpm wajib atau jawapan peningkatan direka. Keperluan air Tahun1 tidak sama dengan standard kuantiti Tahun3.", "privacy_adaptation": false, "privacy_note": "", "held_standards": [], "source_code_conflict": false, "source_code_note": "", "unperformed_literal_elements": [], "source_mapping_review": "20 RPH, dua sesi30minit seminggu dibenarkan guru. S1/S2 ialah cadangan pecahan RPT mingguan, bukan nombor sesi yang tercetak dalam RPT.", "routine_book_pages": [46, 47], "active": false, "production_write_performed": false, "presentation_review": "PENDING_TEACHER_REVIEW", "safety": ["Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula.", "Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan.", "Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan.", "Murid mencari nadi hanya semasa berdiri atau duduk stabil. Guru menunjukkan dua jari pada pergelangan tangannya sendiri dan membantu dengan izin murid tanpa tekanan kuat. Jika nadi belum ditemui, murid boleh merasai degupan dengan tapak tangan di dada atau melaporkan belum dapat merasainya.", "Tiada kiraan denyutan wajib dan tiada sasaran nadi. Guru tidak menambah larian untuk mendapatkan perubahan nadi; murid bernafas seperti biasa sepanjang aktiviti.", "Lari hanya secara perlahan dalam pemanasan dan latihan awal. Selepas latihan penyejukan, semakan menggunakan jalan ringan sahaja; tiada larian kuat atau perlumbaan selepas penyejukan.", "Murid berhenti di ruang rehat untuk minum; tidak berkongsi botol atau dipaksa menghabiskan air."], "weather_plan": "Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat.", "reflection": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________.", "activity_name": "Perlahankan langkah dan tenangkan badan", "objective": "Murid dapat melakukan penyejukan badan dengan berjalan perlahan dan regangan lembut selepas aktiviti fizikal.", "success_criteria": ["Menunjukkan berjalan perlahan dan regangan lembut selepas bergerak.", "Menyebut satu contoh dan tujuan pemanasan serta satu contoh dan tujuan penyejukan.", "Menyatakan air diperlukan sebelum, semasa dan selepas aktiviti."], "prior_knowledge": "Murid pernah memanaskan badan dan merasai perubahan pernafasan selepas bergerak.", "equipment": [{"item": "Kon penanda", "quantity": "6 buah", "use": "Empat kon di luar tepi kawasan senaman dan dua kon di tepi ruang rehat; tidak diletakkan di tempat murid melangkah."}, {"item": "Jam randik", "quantity": "1 buah untuk guru", "use": "Menandakan tempoh langkah, regangan, rehat dan masa mencari nadi."}, {"item": "Botol air minuman sendiri", "quantity": "1 bagi setiap murid", "use": "Digunakan untuk minum sebelum, semasa dan selepas aktiviti mengikut keperluan."}, {"item": "Buku teks PJPK Tahun 1", "quantity": "1 naskhah guru, halaman 46–47", "use": "Rujukan tujuan pemanasan, penyejukan dan air."}, {"item": "Senarai semak dan pen guru", "quantity": "1 set", "use": "Rekod individu bagi lakuan penyejukan, jawapan dan persediaan diri."}], "preparation": ["Guru memastikan permukaan kering, rata dan tiada benda yang boleh menyebabkan murid tersadung. Kon hanya menandakan tepi kawasan.", "Murid diberi ruang sendiri dengan jarak sekurang-kurangnya dua depa. Pasangan berada bersebelahan, bukan berhadapan terlalu dekat.", "Ruang rehat dan botol berada di tepi kawasan dalam pandangan guru. Guru menentukan laluan berjalan ke botol supaya tidak melalui ruang rakan."], "organisation": "Semua murid mengikuti latihan bersama dalam ruang sendiri. Dalam semakan, murid A menunjukkan penyejukan pada minit 21–23 dan B pada minit 23–25. Rakan yang menunggu berehat di sisi ruang sendiri dan memberi peringatan ringkas, bukan menarik tubuh rakan. Murid tanpa pasangan berada dekat guru. Arahan “Perlahankan” bermaksud jalan kecil; arahan “Berhenti” bermaksud hentikan langkah di tempat selamat dan pandang guru.", "movement_cues": ["Perlahankan langkah. Biarkan tangan bergerak dengan santai.", "Regang setakat selesa. Jangan melantun atau menahan nafas.", "Kaki berhenti dahulu sebelum mencari nadi. Gunakan jari telunjuk dan jari tengah di pergelangan tangan, bukan ibu jari atau leher.", "Beritahu cikgu apa yang benar-benar dirasa. Nadi tidak perlu menjadi lebih cepat atau lebih perlahan mengikut jawapan rakan."], "timing_note": "Minit 0–2 persediaan; 2–6 pemanasan; 6–10 tunjuk cara penyejukan; 10–19 latihan memperlahankan gerakan; 19–26 giliran individu; 26–30 penyejukan akhir. Peluang minum sebelum pada 0–1, semasa pada 9–10 dan 17–18, serta selepas pada 29–30. Setiap semakan nadi mempunyai 30 saat mencari dan 30 saat merasai ketika berhenti. Rehat tambahan dibenarkan; guru mengurangkan latihan jika masa diperlukan, bukan memotong penyejukan.", "values": "Kerjasama, disiplin dan menjaga keselamatan rakan.", "classroom_example": {"teacher_says": "Selepas bergerak, kita jalan perlahan. Kemudian regang dengan lembut. Berhenti dahulu sebelum merasai nadi.", "pupils_do": "Murid mengecilkan langkah, melakukan regangan dan berhenti dengan stabil. Murid melaporkan “Nafas saya lebih tenang”, “Masih laju” atau “Saya belum rasa beza”.", "teacher_checks": "Guru melihat tindakan memperlahankan gerakan dan regangan yang selamat. Laporan badan diterima seadanya, bukan dipaksa menunjukkan penurunan nadi."}, "bbm": ["Kon penanda — 6 buah", "Jam randik — 1 buah untuk guru", "Botol air minuman sendiri — 1 bagi setiap murid", "Buku teks PJPK Tahun 1 — 1 naskhah guru, halaman 46–47", "Senarai semak dan pen guru — 1 set", "Buku teks dan senarai semak pemerhatian guru."], "pak21": "Pasangan melihat giliran masing-masing dan mengingatkan “perlahan” atau “regang lembut”. Setiap murid tetap menunjukkan penyejukan dan menjawab soalan sendiri. Perbincangan pasangan membantu murid mengingat rutin, bukan menggantikan semakan guru.", "phases": [{"name": "Persediaan dan nadi sebelum bergerak", "minutes": 2, "teacher": ["Minit 0–1: guru memeriksa pakaian, kasut, keadaan murid dan ruang. Guru menerangkan “Perlahankan” serta “Berhenti”, kemudian memberi peluang minum sebelum aktiviti.", "Minit 1–2: guru meminta semua berhenti dengan stabil. Guru menunjukkan dua jari pada pergelangan tangan; beri 30 saat mencari dan 30 saat merasai nadi tanpa mengira."], "pupils": ["Murid memeriksa kasut dan pakaian, memberitahu jika tidak sihat dan minum mengikut keperluan.", "Murid mencari nadi dengan jari telunjuk dan jari tengah ketika tidak bergerak. Murid meminta bantuan jika belum menjumpainya dan memerhatikan nafas serta rasa badan sebelum aktiviti."], "check": "5.1.1: guru melihat persediaan sebelum aktiviti mengikut murid. Keadaan awal nadi, nafas dan rasa badan dicatat hanya jika diperhatikan atau dilaporkan.", "resources": ["Kon penanda", "Botol air minuman sendiri", "Jam randik"]}, {"name": "Pemanasan sebelum latihan penyejukan", "minutes": 4, "teacher": ["Minit 2–3: guru memimpin berjalan setempat. Minit 3–4: guru menunjukkan lari perlahan setempat dengan langkah kecil; murid boleh terus berjalan jika perlu.", "Minit 4–5: guru memimpin membuka dan merapatkan tangan dengan lembut. Minit 5–6: guru menunjukkan regangan betis kanan dan kiri, satu kaki sedikit ke belakang dengan tumit di lantai.", "Guru menyebut bahawa pemanasan menyediakan badan. Badan dan otot boleh terasa lebih panas, manakala pernafasan dan nadi boleh menjadi lebih cepat; murid tidak perlu mengejar perubahan ini."], "pupils": ["Murid berjalan, mencuba lari perlahan dan menjaga ruang sendiri. Murid bernafas seperti biasa dan memaklumkan keperluan rehat.", "Murid meregang tangan dan betis setakat selesa tanpa sentapan. Murid menyebut satu gerakan pemanasan apabila ditanya guru."], "check": "3.1.1: guru melihat lakuan berjalan, lari perlahan dan regangan. Berjalan sebagai penyesuaian lari direkod dengan tepat.", "resources": ["Kon penanda", "Jam randik", "Ruang rata"]}, {"name": "Belajar cara menyejukkan badan", "minutes": 4, "teacher": ["Minit 6–7: guru meminta semua berhenti; beri 30 saat mencari dan 30 saat merasai nadi dengan dua jari di pergelangan tangan. Tanya rasa panas badan, nafas dan nadi selepas pemanasan tanpa menentukan jawapan.", "Minit 7–8: guru menunjukkan berjalan perlahan dan berkata “Selepas bergerak, kita tenangkan badan”. Guru merujuk halaman 46–47 dan membezakan tujuan pemanasan dengan penyejukan secara ringkas.", "Minit 8–9: guru menunjukkan regangan tangan merentas dada dengan sokongan ringan pada lengan atas, kemudian regangan betis dengan tumit belakang di lantai; murid mencuba lembut tanpa menekan sendi.", "Minit 9–10: guru memberi rehat minum dan mengingatkan air diperlukan sebelum, semasa dan selepas aktiviti. Guru mengambil beberapa jawapan individu tentang contoh dan tujuan kedua-dua rutin."], "pupils": ["Murid berhenti sebelum merasai nadi dan menyatakan keadaan badan sebenar. Murid boleh menjawab belum dapat merasai nadi.", "Murid meniru langkah perlahan serta regangan tangan dan betis. Murid tidak memaksa badan mencapai jarak tertentu.", "Murid berehat dan minum. Murid menjawab soalan mudah secara bergilir, bukan sekadar mengikut jawapan ramai-ramai."], "check": "3.1.2: percubaan awal penyejukan dilihat. 4.1.1, 4.1.2 dan 4.1.3: catat contoh, tujuan dan sebutan tiga waktu air diperlukan bagi murid yang menjawab sendiri.", "resources": ["Buku teks halaman 46–47", "Botol air minuman sendiri", "Jam randik"]}, {"name": "Latihan: bergerak kemudian perlahan", "minutes": 9, "teacher": ["Minit 10–11: guru memimpin berjalan setempat sambil mengayun tangan ringan. Minit 11–12: lakukan lari perlahan setempat atau berjalan mengikut kesediaan; tiada larian laju.", "Minit 12–13: semua berhenti. Guru memberi 30 saat mencari dan 30 saat merasai nadi sebelum latihan penyejukan.", "Minit 13–14: guru memberi arahan berjalan perlahan. Minit 14–16: bimbing regangan tangan merentas dada dan regangan betis, kedua-dua belah, secara lembut; bantuan tiga aras diberi dalam latihan yang sama.", "Minit 16–17: semua berhenti; beri 30 saat mencari dan 30 saat merasai nadi selepas latihan penyejukan. Guru menerima laporan nafas/nadi yang belum berubah.", "Minit 17–18: beri rehat dan minum. Minit 18–19: guru meminta jawapan individu tentang tujuan penyejukan, air sebelum/semasa/selepas dan gerakan yang disukai jika murid mahu berkongsi."], "pupils": ["Murid berjalan dan mencuba lari perlahan mengikut keselesaan. Murid berhenti sebelum mencari nadi pada waktu yang diarahkan.", "Murid memperlahankan langkah dan meregang tangan serta betis dengan lembut. Murid menjaga ruang dan tidak menarik pasangan.", "Selepas regangan, murid berhenti untuk mencari nadi. Murid membandingkan pengalaman nafas dan nadi sendiri dengan keadaan sebelum penyejukan, tanpa mengira denyutan.", "Semasa rehat, murid minum jika perlu, memeriksa kasut dan memberitahu keadaan diri. Murid menyebut tujuan penyejukan serta waktu air diperlukan apabila ditanya guru."], "check": "3.1.2: guru melihat langkah perlahan dan regangan individu. Rekod juga 4.1.2, 4.1.3, persediaan semasa 5.1.1 serta respons sebenar 5.2.1. Keperluan rehat dicatat, bukan dihukum.", "resources": ["Kon penanda", "Jam randik", "Botol air minuman sendiri", "Senarai semak dan pen guru"]}, {"name": "Giliran individu menunjukkan penyejukan", "minutes": 7, "teacher": ["Minit 19–20: semua berjalan ringan setempat untuk memulakan urutan; tiada larian atau usaha kuat. Minit 20–21: semua berhenti, cari nadi 30 saat dan rasa 30 saat sebelum semakan penyejukan.", "Minit 21–23: A menunjukkan berjalan perlahan 1 minit dan regangan tangan/betis 1 minit. Minit 23–25: B menunjukkan urutan yang sama; guru melihat lakuan setiap murid yang dipilih tanpa melepaskan pengawasan kelas.", "Minit 25–26: semua berehat. Guru bertanya secara berasingan contoh serta tujuan pemanasan dan penyejukan, dan meminta murid menyebut air sebelum, semasa serta selepas. Guru mencatat nama serta aspek yang belum sempat disemak."], "pupils": ["Murid berjalan ringan, kemudian berhenti untuk mencari nadi dengan dua jari di pergelangan tangan. Murid tidak mencari nadi ketika melangkah.", "Pada giliran sendiri, murid berjalan perlahan dan regang dengan lembut. Rakan yang menunggu berehat di sisi ruang sendiri dan memberi satu peringatan sopan.", "Murid menjawab guru dengan kata mudah. Murid boleh melihat contoh semula dan menerima bantuan lisan tanpa kehilangan peluang menunjukkan kemahiran."], "check": "Bukti utama 3.1.2 ialah lakuan individu pada giliran A atau B. Bukti kognitif ialah jawapan sendiri; jika masa tidak cukup, tandakan belum diperhatikan, bukan terus menganggap semua telah menguasai.", "resources": ["Kon penanda", "Jam randik", "Senarai semak dan pen guru"]}, {"name": "Penyejukan akhir, nadi selepas dan urus diri", "minutes": 4, "teacher": ["Minit 26–27: guru memimpin berjalan perlahan. Minit 27–28: guru membimbing regangan tangan dan betis dengan lembut, kedua-dua belah; tiada aktiviti kuat selepas ini.", "Minit 28–29: guru meminta semua berhenti dengan stabil. Beri 30 saat mencari dan 30 saat merasai nadi menggunakan dua jari pada pergelangan tangan; tanya nafas dan nadi berbanding sebelum penyejukan pada minit 20–21.", "Minit 29–30: guru memberi masa minum selepas aktiviti dan menyemak keadaan diri murid. Guru mendengar tujuan penyejukan atau pengalaman murid yang belum sempat menjawab, kemudian mengarahkan botol dikemas."], "pupils": ["Murid berjalan perlahan, melakukan regangan lembut dan bernafas seperti biasa. Murid tidak menambah gerakan kuat.", "Murid berhenti sebelum merasai nadi. Murid melaporkan pengalaman sebenar seperti lebih tenang, masih cepat atau belum dapat dibezakan.", "Murid minum jika perlu dan menyebut air diperlukan selepas aktiviti. Murid memeriksa keadaan diri, mengemas botol dan memberitahu guru jika masih tidak selesa."], "check": "3.1.2: semakan penyejukan; 5.1.1: persediaan selepas. Lengkapkan 4.1.2, 4.1.3 dan respons 5.2.1 hanya jika diperoleh. Nadi yang belum berubah bukan bukti gagal melakukan penyejukan.", "resources": ["Botol air minuman sendiri", "Jam randik", "Ruang rehat", "Senarai semak dan pen guru"]}], "differentiation": {"support": {"label": "Peneroka", "support_description": "Guru membimbing satu langkah pada satu masa.", "task": "Mengikuti guru memperlahankan langkah dan meregang selepas gerakan ringan.", "materials": ["Ruang sendiri dengan kon di tepi", "Jam randik guru", "Botol air sendiri", "Buku teks halaman 46–47 untuk rujukan guru"], "teacher": ["Guru berada dekat dan menunjukkan berjalan perlahan sambil berkata “langkah kecil”. Guru menunjukkan regangan tangan dan betis satu demi satu serta membenarkan julat kecil.", "Guru membantu mencari nadi ketika murid berhenti; gunakan dua jari di pergelangan tangan tanpa tekanan kuat. Guru memberi pilihan lisan untuk tujuan kedua-dua rutin dan mengulang tiga waktu air diperlukan."], "pupil_steps": ["Sebelum aktiviti, periksa pakaian serta kasut dengan bantuan dan minum jika perlu. Berhenti, cari nadi awal selama 30 saat dan rasa 30 saat dengan dua jari pada pergelangan tangan. Ikut pemanasan jalan, lari perlahan dan regangan; sebut “bersedia bergerak”.", "Semasa latihan, ikut gerakan ringan guru. Berhenti dan cari nadi sebelum penyejukan selama 30 saat, kemudian rasa 30 saat. Beritahu keadaan panas badan serta nafas; ikut guru berjalan perlahan, regang tangan dan betis.", "Selepas latihan penyejukan, berhenti untuk mencari nadi 30 saat dan merasainya 30 saat. Dalam rehat semasa kelas, minum, periksa kasut dan beritahu jika letih. Sebut air diperlukan sebelum, semasa dan selepas; tunjuk penyejukan sendiri apabila giliran tiba.", "Selepas aktiviti, ikut penyejukan akhir dan sebut ini untuk membantu badan kembali tenang. Berhenti, cari nadi 30 saat dan rasa 30 saat. Minum selepas, kemas botol dan beritahu keadaan diri; kongsi gerakan yang disukai jika mahu."], "product": "Lakuan penyejukan sendiri dengan contoh guru, jawapan tentang pemanasan/penyejukan, air serta laporan pengalaman badan.", "criterion": "Murid berjalan perlahan dan mencuba regangan lembut selepas aktiviti. Guru menyemak contoh serta tujuan kedua-dua rutin dan air/persediaan sebelum, semasa serta selepas; bantuan direkod.", "next_step": "Kekalkan contoh dekat guru. Jika lari tidak sesuai, catat berjalan sebagai penyesuaian; jika nadi belum dirasa, bantu ketika berhenti tanpa memaksa kiraan.", "example": {"teacher": "Ikut langkah kecil cikgu. Ini pemanasan atau penyejukan? Mengapa kita lakukan selepas bergerak?", "pupil": "Murid berjalan perlahan dan menjawab dengan bantuan “Penyejukan. Supaya badan kembali tenang.”"}}, "core": {"label": "Pembina", "support_description": "Murid berlatih berpasangan dan melakukan sendiri.", "task": "Menunjukkan urutan langkah perlahan dan regangan secara bergilir dengan pasangan.", "materials": ["Ruang pasangan dalam sempadan kon", "Jam randik guru", "Botol air sendiri", "Buku teks halaman 46–47"], "teacher": ["Guru menunjukkan beza jalan biasa dengan jalan perlahan melalui contoh selamat. Guru memberi peringatan supaya tumit belakang kekal di lantai semasa regangan betis.", "Guru membantu murid merasai nadi hanya selepas berhenti dan mendengar jawapan setiap orang. Guru memberi kata mula “Pemanasan untuk…” dan “Penyejukan untuk…” serta membantu menyebut tiga waktu air."], "pupil_steps": ["Sebelum bergerak, semak pakaian, kasut dan ruang; minum jika perlu. Berhenti, cari nadi awal 30 saat dan rasa 30 saat dengan dua jari pada pergelangan tangan. Lakukan pemanasan jalan, lari perlahan serta regangan dan sebut tujuannya untuk bersedia.", "Semasa latihan, berjalan dan lari perlahan mengikut keselesaan. Berhenti untuk mencari nadi 30 saat dan merasainya 30 saat sebelum penyejukan. Beritahu rasa panas badan serta nafas, kemudian perlahankan langkah dan regang tangan serta betis.", "Berhenti selepas latihan penyejukan untuk mencari nadi 30 saat dan rasa 30 saat. Semasa rehat, minum, periksa kasut dan maklumkan jika tidak selesa. Sebut keperluan air sebelum, semasa dan selepas. Pada giliran sendiri, tunjuk urutan penyejukan kepada guru.", "Selepas aktiviti, lakukan penyejukan akhir; sebut tujuannya untuk membantu badan kembali tenang. Berhenti, cari nadi 30 saat dan rasa 30 saat. Minum selepas, periksa keadaan diri dan kemas botol; beritahu gerakan yang disukai jika mahu."], "product": "Urutan penyejukan setiap murid dan jawapan individu tentang contoh, tujuan serta air; laporan nadi/nafas tidak ditentukan awal.", "criterion": "Murid mengurangkan kelajuan langkah dan melakukan regangan lembut dengan selamat. Kedua-dua contoh serta tujuan rutin, air dan persediaan sebelum/semasa/selepas diperiksa; perubahan nadi tertentu tidak diwajibkan.", "next_step": "Ulang bahagian regangan yang belum selesa dengan julat kecil. Murid yang memerlukan rehat tidak dipaksa mengulang demi melengkapkan bukti pada hari yang sama.", "example": {"teacher": "Tunjukkan cara menyejukkan badan. Apakah tujuan pemanasan sebelum kita bergerak?", "pupil": "Murid berjalan perlahan dan regang, kemudian berkata “Pemanasan menyediakan badan. Penyejukan membantu badan kembali tenang.”"}}, "challenge": {"label": "Pencabar", "support_description": "Murid memperkemas satu perkara dalam kemahiran yang sama.", "task": "Memperkemas langkah yang semakin perlahan dan regangan lembut dalam urutan yang sama.", "materials": ["Ruang sendiri dengan kon di luar pijakan", "Jam randik guru", "Botol air sendiri", "Buku teks halaman 46–47"], "teacher": ["Guru menunjukkan langkah pendek dengan ayunan tangan santai, kemudian regangan tanpa henjutan. Guru memberi satu maklum balas tentang kawalan, bukan meminta regangan lebih jauh.", "Guru menyokong semakan nadi selepas berhenti dan menerima laporan sebenar. Guru mengulang tujuan pemanasan/penyejukan serta sebelum, semasa dan selepas jika murid terlupa."], "pupil_steps": ["Sebelum aktiviti, periksa kasut, pakaian dan ruang; sediakan botol serta minum jika perlu. Berhenti, cari nadi awal 30 saat dan rasa 30 saat dengan dua jari di pergelangan tangan. Lakukan pemanasan jalan, lari perlahan dan regangan untuk menyediakan badan.", "Semasa latihan, bergerak ringan dahulu. Berhenti untuk mencari nadi sebelum penyejukan selama 30 saat dan rasa 30 saat; beritahu rasa panas badan dan nafas. Perlahankan langkah dengan terkawal, kemudian regang tangan dan betis tanpa henjutan.", "Selepas latihan penyejukan, berhenti, cari nadi 30 saat dan rasa 30 saat. Dalam rehat semasa aktiviti, minum, semak kasut dan keadaan diri serta sebut air diperlukan sebelum, semasa dan selepas. Tunjuk urutan penyejukan sendiri pada giliran dengan kelajuan yang selesa.", "Selepas aktiviti, lakukan penyejukan akhir dan nyatakan contoh serta tujuannya membantu badan kembali tenang. Berhenti, cari nadi 30 saat dan rasa 30 saat; minum selepas dan kemas botol. Laporkan keadaan diri serta kongsi rasa seronok jika benar-benar dirasai."], "product": "Penyejukan individu dengan kawalan langkah dan regangan, diikuti jawapan mudah dan laporan keadaan badan sendiri.", "criterion": "Murid memperkemas kawalan dalam aktiviti penyejukan yang sama, bukan memanjangkan masa atau menambah kelajuan. Semakan tetap merangkumi pemanasan, tujuan kedua-dua rutin dan air/persediaan sebelum/semasa/selepas.", "next_step": "Kekalkan satu sasaran kecil, iaitu langkah yang santai atau regangan tanpa henjutan. Bantuan guru masih tersedia dan rehat dicatat tanpa hukuman.", "example": {"teacher": "Boleh perlahankan langkah tanpa menghampiri rakan? Bagaimana badan kamu rasa selepas berhenti?", "pupil": "Murid menunjukkan langkah terkawal dan menjawab berdasarkan pengalaman sendiri, termasuk “Saya belum rasa beza”."}}}, "differentiation_delivery": {"common_task": "Murid dapat melakukan penyejukan badan dengan berjalan perlahan dan regangan lembut selepas aktiviti fizikal.", "placement": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan.", "teacher_rounds": ["Minit 0–6: semak persediaan sebelum dan gerakan pemanasan; bantu murid yang memerlukan penyesuaian.", "Minit 6–10: dengar pengalaman badan dan contoh serta tujuan rutin. Minit 13–18: lihat penyejukan dan persediaan semasa.", "Minit 21–23 dan 23–25: guru memerhatikan individu A kemudian B. Guru menyebut satu pembetulan mudah tanpa melambatkan murid yang lain.", "Minit 25–30: lengkapkan jawapan pendek, penyejukan akhir dan persediaan selepas. Tandakan aspek yang belum sempat diperhatikan untuk susulan, bukan memberi keputusan beramai-ramai."], "individual_check": "Menunjukkan berjalan perlahan dan regangan lembut selepas bergerak.", "flexible_help": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, "pbd": {"method": "Pemerhatian individu pada latihan minit 13–16, giliran A 21–23 atau B 23–25, dan penyejukan akhir 26–28.", "evidence": ["Lakuan berjalan perlahan serta regangan tangan dan betis yang lembut.", "Laporan nadi/pernafasan ketika berhenti sebelum dan selepas penyejukan: minit 12–13 dan 16–17, kemudian 20–21 dan 28–29."], "criterion": "Murid melakukan penyejukan selepas aktiviti dengan langkah perlahan dan regangan selesa. Tidak diwajibkan nadi atau pernafasan menunjukkan penurunan tertentu; guru menilai lakuan, bukan mereka perubahan tubuh.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama: ____; berjalan perlahan: ____; regangan lembut: ____; waktu dilihat: ____.", "Nadi/nafas yang dilaporkan: ____; bantuan atau rehat: ____; belum diperhatikan: ____."]}, "pbd_complementary": {"3.1.1": {"method": "Pemerhatian lakuan individu semasa pemanasan minit 2–6 dan aktiviti ringan 10–12.", "evidence": "Berjalan, percubaan lari perlahan dan regangan setiap murid; laporan rasa panas badan, nafas serta nadi pada minit 6–7 selepas berhenti.", "criterion": "Murid melakukan gerakan pemanasan yang boleh menyediakan badan. Lari yang diganti dengan berjalan dan bantuan regangan dicatat tepat; tidak wajib melaporkan peningkatan nadi.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama: ____; berjalan: ____; lari perlahan/penyesuaian: ____; regangan: ____; bantuan: ____."]}, "4.1.1": {"method": "Soal jawab individu semasa rehat minit 9–10, 18–19 atau 25–26.", "evidence": "Murid menyebut satu aktiviti pemanasan dan satu aktiviti penyejukan yang dilakukan sendiri.", "criterion": "Murid mengenal kedua-dua rutin, contohnya lari perlahan sebelum aktiviti dan berjalan perlahan selepasnya. Pilihan jawapan lisan dibenarkan dan dicatat.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama: ____; contoh pemanasan: ____; contoh penyejukan: ____; bantuan: ____."]}, "4.1.2": {"method": "Soalan pendek berasingan tentang tujuan pemanasan dan penyejukan pada minit 9–10, 18–19, 25–26 atau 29–30.", "evidence": "Jawapan murid sendiri seperti “Supaya bersedia bergerak” dan “Supaya badan kembali tenang”.", "criterion": "Murid mengenal tujuan kedua-dua rutin melalui ayat mudah atau pilihan lisan. Tidak perlu menerangkan mekanisme tubuh dengan panjang.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama: ____; tujuan pemanasan: ____; tujuan penyejukan: ____; bantuan/contoh semula: ____."]}, "4.1.3": {"method": "Soal jawab individu dalam rehat minum 9–10 dan 17–18 serta penutup 29–30; minta murid melengkapkan semua waktu air diperlukan.", "evidence": "Sebutannya sendiri “sebelum, semasa dan selepas aktiviti”; guru menyemak setiap bahagian, bukan sekadar melihat botol digunakan.", "criterion": "Murid menyatakan ketiga-tiga waktu air diperlukan. Tiada kuota minuman atau syarat menghabiskan air.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama: ____; sebelum: ____; semasa: ____; selepas: ____; bantuan atau belum menjawab: ____."]}, "5.1.1": {"method": "Pemerhatian persediaan diri individu sebelum pada 0–2, semasa pada 17–18 dan selepas pada 29–30.", "evidence": ["Sebelum: periksa pakaian/kasut, sediakan air dan maklumkan keadaan diri.", "Semasa: jaga jarak, semak kasut bila perlu, minum/rehat mengikut keperluan dan beritahu guru jika tidak selesa.", "Selepas: lakukan penyejukan, periksa keadaan diri, mendapat peluang minum dan kemas botol."], "criterion": "Guru merekod penjagaan diri sebelum, semasa dan selepas secara berasingan. Permintaan bantuan atau rehat diterima sebagai usaha menjaga diri.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama: ____; sebelum: ____; semasa: ____; selepas: ____; bantuan/keperluan tubuh: ____."]}, "5.2.1": {"method": "Pemerhatian respons individu semasa latihan dan pertanyaan sukarela pada minit 18–19 atau 29–30.", "evidence": "Kata atau isyarat sebenar murid tentang gerakan baharu yang disukai atau minat mencuba lagi bersama guru.", "criterion": "Respons seronok dicatat hanya jika dilihat atau didengar. Murid tidak dipaksa tersenyum, bersorak atau terus bergerak ketika memerlukan rehat.", "recording": "Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP.", "sample_checklist": ["Nama: ____; kata/isyarat sebenar: ____; bantuan/keadaan diri: ____; belum diperhatikan: ____."]}}, "intervention": ["Jika murid belum dapat memperlahankan gerakan, guru berjalan di hadapannya dalam ruang selamat sambil memberi arahan pendek. Regangan dibuat dengan julat kecil.", "Berjalan menggantikan lari dibenarkan dan direkod sebagai penyesuaian. Rehat atau ketidakselesaan tidak dianggap sikap negatif.", "Jika nadi belum dirasa, beri bantuan semasa berhenti atau gunakan tapak tangan di dada untuk merasai degupan. Jangan memaksa kiraan atau perubahan.", "Gunakan contoh lisan berulang bagi tujuan kedua-dua rutin dan air sebelum, semasa serta selepas. Catat jawapan atau giliran yang belum lengkap untuk bimbingan seterusnya."], "book_pages_text": "46, 47", "sp_focus": "", "sp_display": "3.1.2", "complementary": [{"standard_key": "3.1.1", "sp_code": "3.1.1", "sp_text": "Melakukan pelbagai jenis aktiviti seperti berjalan, berlari, dan regangan yang boleh meningkatkan suhu badan dan otot, kadar pernafasan dan kadar nadi.", "sk_code": "3.1", "sk_text": "Melakukan aktiviti fizikal berpandukan konsep kecergasan.", "domain": "psikomotor", "source_label": ""}, {"standard_key": "4.1.1", "sp_code": "4.1.1", "sp_text": "Mengenal pasti aktiviti memanaskan dan menyejukkan badan.", "sk_code": "4.1", "sk_text": "Mengaplikasi konsep kecergasan semasa melakukan aktiviti fizikal.", "domain": "kognitif", "source_label": ""}, {"standard_key": "4.1.2", "sp_code": "4.1.2", "sp_text": "Mengenal pasti tujuan memanaskan dan menyejukkan badan.", "sk_code": "4.1", "sk_text": "Mengaplikasi konsep kecergasan semasa melakukan aktiviti fizikal.", "domain": "kognitif", "source_label": ""}, {"standard_key": "4.1.3", "sp_code": "4.1.3", "sp_text": "Menyatakan keperluan air sebelum, semasa dan selepas melakukan aktiviti fizikal.", "sk_code": "4.1", "sk_text": "Mengaplikasi konsep kecergasan semasa melakukan aktiviti fizikal.", "domain": "kognitif", "source_label": ""}, {"standard_key": "5.1.1", "sp_code": "5.1.1", "sp_text": "Membuat persediaan diri sebelum, semasa dan selepas melakukan aktiviti Pendidikan Jasmani.", "sk_code": "5.1", "sk_text": "Mematuhi dan mengamalkan elemen pengurusan dan keselamatan.", "domain": "afektif", "source_label": ""}, {"standard_key": "5.2.1", "sp_code": "5.2.1", "sp_text": "Mempamerkan rasa seronok melakukan aktiviti baharu dalam Pendidikan Jasmani.", "sk_code": "5.2", "sk_text": "Menunjukkan keyakinan dan tanggungjawab kendiri semasa melakukan aktiviti.", "domain": "afektif", "source_label": ""}], "draft_sha256": "8f945719977f660231f2ad94cf7874f68016bc95b7a0e693cf70c7cee05763ed"}'::jsonb,'[{"kind": "title", "text": "Minggu 33 Sesi 2 — Perlahankan langkah dan tenangkan badan"}, {"kind": "subtitle", "text": "Pendidikan Jasmani Tahun 1 | Dua sesi seminggu | 30 minit setiap sesi | R1"}, {"kind": "p", "text": "ID: PJ1-2026B-2S-W33-S2"}, {"kind": "h2", "text": "A. Maklumat pengajaran"}, {"kind": "p", "text": "Guru: ____________________ | Kelas: __________ | Tarikh: __________ | Waktu: __________"}, {"kind": "p", "text": "Unit 7: Badan Cergas Otak Cerdas"}, {"kind": "p", "text": "Tajuk buku teks: Otot Lentur, Pergerakan Teratur"}, {"kind": "p", "text": "Aktiviti guru: Perlahankan langkah dan tenangkan badan"}, {"kind": "p", "text": "Rujukan buku teks PJPK Tahun 1, bahagian PJ: muka surat 46, 47."}, {"kind": "p", "text": "Minit 0–2 persediaan; 2–6 pemanasan; 6–10 tunjuk cara penyejukan; 10–19 latihan memperlahankan gerakan; 19–26 giliran individu; 26–30 penyejukan akhir. Peluang minum sebelum pada 0–1, semasa pada 9–10 dan 17–18, serta selepas pada 29–30. Setiap semakan nadi mempunyai 30 saat mencari dan 30 saat merasai ketika berhenti. Rehat tambahan dibenarkan; guru mengurangkan latihan jika masa diperlukan, bukan memotong penyejukan."}, {"kind": "h2", "text": "B. Standard dan hasil pembelajaran"}, {"kind": "p", "text": "SK utama 3.1: Melakukan aktiviti fizikal berpandukan konsep kecergasan."}, {"kind": "p", "text": "SP utama 3.1.2: Melakukan aktiviti yang boleh menurunkan kadar pernafasan dan kadar nadi."}, {"kind": "p", "text": "SK sokongan 3.1: Melakukan aktiviti fizikal berpandukan konsep kecergasan."}, {"kind": "p", "text": "SP sokongan 3.1.1: Melakukan pelbagai jenis aktiviti seperti berjalan, berlari, dan regangan yang boleh meningkatkan suhu badan dan otot, kadar pernafasan dan kadar nadi."}, {"kind": "p", "text": "SK sokongan 4.1: Mengaplikasi konsep kecergasan semasa melakukan aktiviti fizikal."}, {"kind": "p", "text": "SP sokongan 4.1.1: Mengenal pasti aktiviti memanaskan dan menyejukkan badan."}, {"kind": "p", "text": "SK sokongan 4.1: Mengaplikasi konsep kecergasan semasa melakukan aktiviti fizikal."}, {"kind": "p", "text": "SP sokongan 4.1.2: Mengenal pasti tujuan memanaskan dan menyejukkan badan."}, {"kind": "p", "text": "SK sokongan 4.1: Mengaplikasi konsep kecergasan semasa melakukan aktiviti fizikal."}, {"kind": "p", "text": "SP sokongan 4.1.3: Menyatakan keperluan air sebelum, semasa dan selepas melakukan aktiviti fizikal."}, {"kind": "p", "text": "SK sokongan 5.1: Mematuhi dan mengamalkan elemen pengurusan dan keselamatan."}, {"kind": "p", "text": "SP sokongan 5.1.1: Membuat persediaan diri sebelum, semasa dan selepas melakukan aktiviti Pendidikan Jasmani."}, {"kind": "p", "text": "SK sokongan 5.2: Menunjukkan keyakinan dan tanggungjawab kendiri semasa melakukan aktiviti."}, {"kind": "p", "text": "SP sokongan 5.2.1: Mempamerkan rasa seronok melakukan aktiviti baharu dalam Pendidikan Jasmani."}, {"kind": "label", "text": "Objektif"}, {"kind": "p", "text": "Murid dapat melakukan penyejukan badan dengan berjalan perlahan dan regangan lembut selepas aktiviti fizikal."}, {"kind": "label", "text": "Kriteria kejayaan"}, {"kind": "p", "text": "1. Menunjukkan berjalan perlahan dan regangan lembut selepas bergerak."}, {"kind": "p", "text": "2. Menyebut satu contoh dan tujuan pemanasan serta satu contoh dan tujuan penyejukan."}, {"kind": "p", "text": "3. Menyatakan air diperlukan sebelum, semasa dan selepas aktiviti."}, {"kind": "p", "text": "Pengetahuan sedia ada: Murid pernah memanaskan badan dan merasai perubahan pernafasan selepas bergerak."}, {"kind": "h2", "text": "C. Alatan, persediaan dan keselamatan"}, {"kind": "label", "text": "Kon penanda"}, {"kind": "p", "text": "Keperluan: 6 buah"}, {"kind": "p", "text": "Kegunaan: Empat kon di luar tepi kawasan senaman dan dua kon di tepi ruang rehat; tidak diletakkan di tempat murid melangkah."}, {"kind": "label", "text": "Jam randik"}, {"kind": "p", "text": "Keperluan: 1 buah untuk guru"}, {"kind": "p", "text": "Kegunaan: Menandakan tempoh langkah, regangan, rehat dan masa mencari nadi."}, {"kind": "label", "text": "Botol air minuman sendiri"}, {"kind": "p", "text": "Keperluan: 1 bagi setiap murid"}, {"kind": "p", "text": "Kegunaan: Digunakan untuk minum sebelum, semasa dan selepas aktiviti mengikut keperluan."}, {"kind": "label", "text": "Buku teks PJPK Tahun 1"}, {"kind": "p", "text": "Keperluan: 1 naskhah guru, halaman 46–47"}, {"kind": "p", "text": "Kegunaan: Rujukan tujuan pemanasan, penyejukan dan air."}, {"kind": "label", "text": "Senarai semak dan pen guru"}, {"kind": "p", "text": "Keperluan: 1 set"}, {"kind": "p", "text": "Kegunaan: Rekod individu bagi lakuan penyejukan, jawapan dan persediaan diri."}, {"kind": "label", "text": "Persediaan guru"}, {"kind": "p", "text": "1. Guru memastikan permukaan kering, rata dan tiada benda yang boleh menyebabkan murid tersadung. Kon hanya menandakan tepi kawasan."}, {"kind": "p", "text": "2. Murid diberi ruang sendiri dengan jarak sekurang-kurangnya dua depa. Pasangan berada bersebelahan, bukan berhadapan terlalu dekat."}, {"kind": "p", "text": "3. Ruang rehat dan botol berada di tepi kawasan dalam pandangan guru. Guru menentukan laluan berjalan ke botol supaya tidak melalui ruang rakan."}, {"kind": "label", "text": "Susunan dan giliran murid"}, {"kind": "p", "text": "Semua murid mengikuti latihan bersama dalam ruang sendiri. Dalam semakan, murid A menunjukkan penyejukan pada minit 21–23 dan B pada minit 23–25. Rakan yang menunggu berehat di sisi ruang sendiri dan memberi peringatan ringkas, bukan menarik tubuh rakan. Murid tanpa pasangan berada dekat guru. Arahan “Perlahankan” bermaksud jalan kecil; arahan “Berhenti” bermaksud hentikan langkah di tempat selamat dan pandang guru."}, {"kind": "label", "text": "Petunjuk pergerakan"}, {"kind": "p", "text": "1. Perlahankan langkah. Biarkan tangan bergerak dengan santai."}, {"kind": "p", "text": "2. Regang setakat selesa. Jangan melantun atau menahan nafas."}, {"kind": "p", "text": "3. Kaki berhenti dahulu sebelum mencari nadi. Gunakan jari telunjuk dan jari tengah di pergelangan tangan, bukan ibu jari atau leher."}, {"kind": "p", "text": "4. Beritahu cikgu apa yang benar-benar dirasa. Nadi tidak perlu menjadi lebih cepat atau lebih perlahan mengikut jawapan rakan."}, {"kind": "label", "text": "BBM"}, {"kind": "p", "text": "1. Kon penanda — 6 buah"}, {"kind": "p", "text": "2. Jam randik — 1 buah untuk guru"}, {"kind": "p", "text": "3. Botol air minuman sendiri — 1 bagi setiap murid"}, {"kind": "p", "text": "4. Buku teks PJPK Tahun 1 — 1 naskhah guru, halaman 46–47"}, {"kind": "p", "text": "5. Senarai semak dan pen guru — 1 set"}, {"kind": "p", "text": "6. Buku teks dan senarai semak pemerhatian guru."}, {"kind": "p", "text": "PAK-21: Pasangan melihat giliran masing-masing dan mengingatkan “perlahan” atau “regang lembut”. Setiap murid tetap menunjukkan penyejukan dan menjawab soalan sendiri. Perbincangan pasangan membantu murid mengingat rutin, bukan menggantikan semakan guru."}, {"kind": "p", "text": "Nilai: Kerjasama, disiplin dan menjaga keselamatan rakan."}, {"kind": "label", "text": "Keselamatan"}, {"kind": "p", "text": "1. Guru memeriksa pakaian, tali kasut, keadaan murid, permukaan tempat aktiviti dan alatan sebelum bermula."}, {"kind": "p", "text": "2. Murid berhenti dan memberitahu guru jika sakit, pening atau sukar bernafas. Rehat dan minum dibenarkan mengikut keperluan."}, {"kind": "p", "text": "3. Guru memastikan semua murid berada dalam pandangannya. Murid tidak menolak, menarik atau menghalang laluan rakan."}, {"kind": "p", "text": "4. Murid mencari nadi hanya semasa berdiri atau duduk stabil. Guru menunjukkan dua jari pada pergelangan tangannya sendiri dan membantu dengan izin murid tanpa tekanan kuat. Jika nadi belum ditemui, murid boleh merasai degupan dengan tapak tangan di dada atau melaporkan belum dapat merasainya."}, {"kind": "p", "text": "5. Tiada kiraan denyutan wajib dan tiada sasaran nadi. Guru tidak menambah larian untuk mendapatkan perubahan nadi; murid bernafas seperti biasa sepanjang aktiviti."}, {"kind": "p", "text": "6. Lari hanya secara perlahan dalam pemanasan dan latihan awal. Selepas latihan penyejukan, semakan menggunakan jalan ringan sahaja; tiada larian kuat atau perlumbaan selepas penyejukan."}, {"kind": "p", "text": "7. Murid berhenti di ruang rehat untuk minum; tidak berkongsi botol atau dipaksa menghabiskan air."}, {"kind": "p", "text": "Jika cuaca atau ruang tidak sesuai: Jika hujan, kilat, panas melampau atau lantai licin, guru menggunakan ruang berbumbung yang selamat. Jika ruang tidak sesuai, aktiviti berisiko ditangguhkan dan perkara yang belum dilaksanakan dicatat."}, {"kind": "h2", "text": "D. Langkah PdP"}, {"kind": "h3", "text": "Langkah 1: Persediaan dan nadi sebelum bergerak — 2 minit"}, {"kind": "p", "text": "Minit 0 hingga 2."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minit 0–1: guru memeriksa pakaian, kasut, keadaan murid dan ruang. Guru menerangkan “Perlahankan” serta “Berhenti”, kemudian memberi peluang minum sebelum aktiviti."}, {"kind": "p", "text": "2. Minit 1–2: guru meminta semua berhenti dengan stabil. Guru menunjukkan dua jari pada pergelangan tangan; beri 30 saat mencari dan 30 saat merasai nadi tanpa mengira."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid memeriksa kasut dan pakaian, memberitahu jika tidak sihat dan minum mengikut keperluan."}, {"kind": "p", "text": "2. Murid mencari nadi dengan jari telunjuk dan jari tengah ketika tidak bergerak. Murid meminta bantuan jika belum menjumpainya dan memerhatikan nafas serta rasa badan sebelum aktiviti."}, {"kind": "p", "text": "Semakan: 5.1.1: guru melihat persediaan sebelum aktiviti mengikut murid. Keadaan awal nadi, nafas dan rasa badan dicatat hanya jika diperhatikan atau dilaporkan."}, {"kind": "p", "text": "Alatan: Kon penanda Botol air minuman sendiri Jam randik"}, {"kind": "h3", "text": "Langkah 2: Pemanasan sebelum latihan penyejukan — 4 minit"}, {"kind": "p", "text": "Minit 2 hingga 6."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minit 2–3: guru memimpin berjalan setempat. Minit 3–4: guru menunjukkan lari perlahan setempat dengan langkah kecil; murid boleh terus berjalan jika perlu."}, {"kind": "p", "text": "2. Minit 4–5: guru memimpin membuka dan merapatkan tangan dengan lembut. Minit 5–6: guru menunjukkan regangan betis kanan dan kiri, satu kaki sedikit ke belakang dengan tumit di lantai."}, {"kind": "p", "text": "3. Guru menyebut bahawa pemanasan menyediakan badan. Badan dan otot boleh terasa lebih panas, manakala pernafasan dan nadi boleh menjadi lebih cepat; murid tidak perlu mengejar perubahan ini."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid berjalan, mencuba lari perlahan dan menjaga ruang sendiri. Murid bernafas seperti biasa dan memaklumkan keperluan rehat."}, {"kind": "p", "text": "2. Murid meregang tangan dan betis setakat selesa tanpa sentapan. Murid menyebut satu gerakan pemanasan apabila ditanya guru."}, {"kind": "p", "text": "Semakan: 3.1.1: guru melihat lakuan berjalan, lari perlahan dan regangan. Berjalan sebagai penyesuaian lari direkod dengan tepat."}, {"kind": "p", "text": "Alatan: Kon penanda Jam randik Ruang rata"}, {"kind": "h3", "text": "Langkah 3: Belajar cara menyejukkan badan — 4 minit"}, {"kind": "p", "text": "Minit 6 hingga 10."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minit 6–7: guru meminta semua berhenti; beri 30 saat mencari dan 30 saat merasai nadi dengan dua jari di pergelangan tangan. Tanya rasa panas badan, nafas dan nadi selepas pemanasan tanpa menentukan jawapan."}, {"kind": "p", "text": "2. Minit 7–8: guru menunjukkan berjalan perlahan dan berkata “Selepas bergerak, kita tenangkan badan”. Guru merujuk halaman 46–47 dan membezakan tujuan pemanasan dengan penyejukan secara ringkas."}, {"kind": "p", "text": "3. Minit 8–9: guru menunjukkan regangan tangan merentas dada dengan sokongan ringan pada lengan atas, kemudian regangan betis dengan tumit belakang di lantai; murid mencuba lembut tanpa menekan sendi."}, {"kind": "p", "text": "4. Minit 9–10: guru memberi rehat minum dan mengingatkan air diperlukan sebelum, semasa dan selepas aktiviti. Guru mengambil beberapa jawapan individu tentang contoh dan tujuan kedua-dua rutin."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid berhenti sebelum merasai nadi dan menyatakan keadaan badan sebenar. Murid boleh menjawab belum dapat merasai nadi."}, {"kind": "p", "text": "2. Murid meniru langkah perlahan serta regangan tangan dan betis. Murid tidak memaksa badan mencapai jarak tertentu."}, {"kind": "p", "text": "3. Murid berehat dan minum. Murid menjawab soalan mudah secara bergilir, bukan sekadar mengikut jawapan ramai-ramai."}, {"kind": "p", "text": "Semakan: 3.1.2: percubaan awal penyejukan dilihat. 4.1.1, 4.1.2 dan 4.1.3: catat contoh, tujuan dan sebutan tiga waktu air diperlukan bagi murid yang menjawab sendiri."}, {"kind": "p", "text": "Alatan: Buku teks halaman 46–47 Botol air minuman sendiri Jam randik"}, {"kind": "h3", "text": "Langkah 4: Latihan: bergerak kemudian perlahan — 9 minit"}, {"kind": "p", "text": "Minit 10 hingga 19."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minit 10–11: guru memimpin berjalan setempat sambil mengayun tangan ringan. Minit 11–12: lakukan lari perlahan setempat atau berjalan mengikut kesediaan; tiada larian laju."}, {"kind": "p", "text": "2. Minit 12–13: semua berhenti. Guru memberi 30 saat mencari dan 30 saat merasai nadi sebelum latihan penyejukan."}, {"kind": "p", "text": "3. Minit 13–14: guru memberi arahan berjalan perlahan. Minit 14–16: bimbing regangan tangan merentas dada dan regangan betis, kedua-dua belah, secara lembut; bantuan tiga aras diberi dalam latihan yang sama."}, {"kind": "p", "text": "4. Minit 16–17: semua berhenti; beri 30 saat mencari dan 30 saat merasai nadi selepas latihan penyejukan. Guru menerima laporan nafas/nadi yang belum berubah."}, {"kind": "p", "text": "5. Minit 17–18: beri rehat dan minum. Minit 18–19: guru meminta jawapan individu tentang tujuan penyejukan, air sebelum/semasa/selepas dan gerakan yang disukai jika murid mahu berkongsi."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid berjalan dan mencuba lari perlahan mengikut keselesaan. Murid berhenti sebelum mencari nadi pada waktu yang diarahkan."}, {"kind": "p", "text": "2. Murid memperlahankan langkah dan meregang tangan serta betis dengan lembut. Murid menjaga ruang dan tidak menarik pasangan."}, {"kind": "p", "text": "3. Selepas regangan, murid berhenti untuk mencari nadi. Murid membandingkan pengalaman nafas dan nadi sendiri dengan keadaan sebelum penyejukan, tanpa mengira denyutan."}, {"kind": "p", "text": "4. Semasa rehat, murid minum jika perlu, memeriksa kasut dan memberitahu keadaan diri. Murid menyebut tujuan penyejukan serta waktu air diperlukan apabila ditanya guru."}, {"kind": "p", "text": "Semakan: 3.1.2: guru melihat langkah perlahan dan regangan individu. Rekod juga 4.1.2, 4.1.3, persediaan semasa 5.1.1 serta respons sebenar 5.2.1. Keperluan rehat dicatat, bukan dihukum."}, {"kind": "p", "text": "Alatan: Kon penanda Jam randik Botol air minuman sendiri Senarai semak dan pen guru"}, {"kind": "h3", "text": "Langkah 5: Giliran individu menunjukkan penyejukan — 7 minit"}, {"kind": "p", "text": "Minit 19 hingga 26."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minit 19–20: semua berjalan ringan setempat untuk memulakan urutan; tiada larian atau usaha kuat. Minit 20–21: semua berhenti, cari nadi 30 saat dan rasa 30 saat sebelum semakan penyejukan."}, {"kind": "p", "text": "2. Minit 21–23: A menunjukkan berjalan perlahan 1 minit dan regangan tangan/betis 1 minit. Minit 23–25: B menunjukkan urutan yang sama; guru melihat lakuan setiap murid yang dipilih tanpa melepaskan pengawasan kelas."}, {"kind": "p", "text": "3. Minit 25–26: semua berehat. Guru bertanya secara berasingan contoh serta tujuan pemanasan dan penyejukan, dan meminta murid menyebut air sebelum, semasa serta selepas. Guru mencatat nama serta aspek yang belum sempat disemak."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid berjalan ringan, kemudian berhenti untuk mencari nadi dengan dua jari di pergelangan tangan. Murid tidak mencari nadi ketika melangkah."}, {"kind": "p", "text": "2. Pada giliran sendiri, murid berjalan perlahan dan regang dengan lembut. Rakan yang menunggu berehat di sisi ruang sendiri dan memberi satu peringatan sopan."}, {"kind": "p", "text": "3. Murid menjawab guru dengan kata mudah. Murid boleh melihat contoh semula dan menerima bantuan lisan tanpa kehilangan peluang menunjukkan kemahiran."}, {"kind": "p", "text": "Semakan: Bukti utama 3.1.2 ialah lakuan individu pada giliran A atau B. Bukti kognitif ialah jawapan sendiri; jika masa tidak cukup, tandakan belum diperhatikan, bukan terus menganggap semua telah menguasai."}, {"kind": "p", "text": "Alatan: Kon penanda Jam randik Senarai semak dan pen guru"}, {"kind": "h3", "text": "Langkah 6: Penyejukan akhir, nadi selepas dan urus diri — 4 minit"}, {"kind": "p", "text": "Minit 26 hingga 30."}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Minit 26–27: guru memimpin berjalan perlahan. Minit 27–28: guru membimbing regangan tangan dan betis dengan lembut, kedua-dua belah; tiada aktiviti kuat selepas ini."}, {"kind": "p", "text": "2. Minit 28–29: guru meminta semua berhenti dengan stabil. Beri 30 saat mencari dan 30 saat merasai nadi menggunakan dua jari pada pergelangan tangan; tanya nafas dan nadi berbanding sebelum penyejukan pada minit 20–21."}, {"kind": "p", "text": "3. Minit 29–30: guru memberi masa minum selepas aktiviti dan menyemak keadaan diri murid. Guru mendengar tujuan penyejukan atau pengalaman murid yang belum sempat menjawab, kemudian mengarahkan botol dikemas."}, {"kind": "label", "text": "Tindakan murid"}, {"kind": "p", "text": "1. Murid berjalan perlahan, melakukan regangan lembut dan bernafas seperti biasa. Murid tidak menambah gerakan kuat."}, {"kind": "p", "text": "2. Murid berhenti sebelum merasai nadi. Murid melaporkan pengalaman sebenar seperti lebih tenang, masih cepat atau belum dapat dibezakan."}, {"kind": "p", "text": "3. Murid minum jika perlu dan menyebut air diperlukan selepas aktiviti. Murid memeriksa keadaan diri, mengemas botol dan memberitahu guru jika masih tidak selesa."}, {"kind": "p", "text": "Semakan: 3.1.2: semakan penyejukan; 5.1.1: persediaan selepas. Lengkapkan 4.1.2, 4.1.3 dan respons 5.2.1 hanya jika diperoleh. Nadi yang belum berubah bukan bukti gagal melakukan penyejukan."}, {"kind": "p", "text": "Alatan: Botol air minuman sendiri Jam randik Ruang rehat Senarai semak dan pen guru"}, {"kind": "p", "text": "Jumlah masa: 30 minit."}, {"kind": "label", "text": "Contoh arahan kelas"}, {"kind": "p", "text": "Guru: Selepas bergerak, kita jalan perlahan. Kemudian regang dengan lembut. Berhenti dahulu sebelum merasai nadi."}, {"kind": "p", "text": "Murid: Murid mengecilkan langkah, melakukan regangan dan berhenti dengan stabil. Murid melaporkan “Nafas saya lebih tenang”, “Masih laju” atau “Saya belum rasa beza”."}, {"kind": "p", "text": "Semakan guru: Guru melihat tindakan memperlahankan gerakan dan regangan yang selamat. Laporan badan diterima seadanya, bukan dipaksa menunjukkan penurunan nadi."}, {"kind": "h2", "text": "E. PdP terbeza", "anchor": "pdp-PJ1-2026B-2S-W33-S2"}, {"kind": "p", "text": "Tugasan bersama: Murid dapat melakukan penyejukan badan dengan berjalan perlahan dan regangan lembut selepas aktiviti fizikal."}, {"kind": "p", "text": "Bimbingan ini diberikan dalam waktu latihan dan aplikasi. Murid tidak perlu menjalani tiga kumpulan bantuan sebagai aktiviti tambahan."}, {"kind": "label", "text": "Bimbingan guru"}, {"kind": "p", "text": "1. Minit 0–6: semak persediaan sebelum dan gerakan pemanasan; bantu murid yang memerlukan penyesuaian."}, {"kind": "p", "text": "2. Minit 6–10: dengar pengalaman badan dan contoh serta tujuan rutin. Minit 13–18: lihat penyejukan dan persediaan semasa."}, {"kind": "p", "text": "3. Minit 21–23 dan 23–25: guru memerhatikan individu A kemudian B. Guru menyebut satu pembetulan mudah tanpa melambatkan murid yang lain."}, {"kind": "p", "text": "4. Minit 25–30: lengkapkan jawapan pendek, penyejukan akhir dan persediaan selepas. Tandakan aspek yang belum sempat diperhatikan untuk susulan, bukan memberi keputusan beramai-ramai."}, {"kind": "p", "text": "Semakan individu: Menunjukkan berjalan perlahan dan regangan lembut selepas bergerak."}, {"kind": "p", "text": "Bantuan diteruskan selagi diperlukan. Murid tidak dipaksa menambah kelajuan, jarak, beban atau ulangan untuk menunjukkan kemajuan."}, {"kind": "h3", "text": "Peneroka"}, {"kind": "p", "text": "Guru membimbing satu langkah pada satu masa."}, {"kind": "p", "text": "Tugasan: Mengikuti guru memperlahankan langkah dan meregang selepas gerakan ringan."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Ruang sendiri dengan kon di tepi"}, {"kind": "p", "text": "2. Jam randik guru"}, {"kind": "p", "text": "3. Botol air sendiri"}, {"kind": "p", "text": "4. Buku teks halaman 46–47 untuk rujukan guru"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru berada dekat dan menunjukkan berjalan perlahan sambil berkata “langkah kecil”. Guru menunjukkan regangan tangan dan betis satu demi satu serta membenarkan julat kecil."}, {"kind": "p", "text": "2. Guru membantu mencari nadi ketika murid berhenti; gunakan dua jari di pergelangan tangan tanpa tekanan kuat. Guru memberi pilihan lisan untuk tujuan kedua-dua rutin dan mengulang tiga waktu air diperlukan."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Sebelum aktiviti, periksa pakaian serta kasut dengan bantuan dan minum jika perlu. Berhenti, cari nadi awal selama 30 saat dan rasa 30 saat dengan dua jari pada pergelangan tangan. Ikut pemanasan jalan, lari perlahan dan regangan; sebut “bersedia bergerak”."}, {"kind": "p", "text": "2. Semasa latihan, ikut gerakan ringan guru. Berhenti dan cari nadi sebelum penyejukan selama 30 saat, kemudian rasa 30 saat. Beritahu keadaan panas badan serta nafas; ikut guru berjalan perlahan, regang tangan dan betis."}, {"kind": "p", "text": "3. Selepas latihan penyejukan, berhenti untuk mencari nadi 30 saat dan merasainya 30 saat. Dalam rehat semasa kelas, minum, periksa kasut dan beritahu jika letih. Sebut air diperlukan sebelum, semasa dan selepas; tunjuk penyejukan sendiri apabila giliran tiba."}, {"kind": "p", "text": "4. Selepas aktiviti, ikut penyejukan akhir dan sebut ini untuk membantu badan kembali tenang. Berhenti, cari nadi 30 saat dan rasa 30 saat. Minum selepas, kemas botol dan beritahu keadaan diri; kongsi gerakan yang disukai jika mahu."}, {"kind": "p", "text": "Contoh guru: Ikut langkah kecil cikgu. Ini pemanasan atau penyejukan? Mengapa kita lakukan selepas bergerak?"}, {"kind": "p", "text": "Contoh respons murid: Murid berjalan perlahan dan menjawab dengan bantuan “Penyejukan. Supaya badan kembali tenang.”"}, {"kind": "p", "text": "Hasil individu: Lakuan penyejukan sendiri dengan contoh guru, jawapan tentang pemanasan/penyejukan, air serta laporan pengalaman badan."}, {"kind": "p", "text": "Kriteria: Murid berjalan perlahan dan mencuba regangan lembut selepas aktiviti. Guru menyemak contoh serta tujuan kedua-dua rutin dan air/persediaan sebelum, semasa serta selepas; bantuan direkod."}, {"kind": "p", "text": "Susulan: Kekalkan contoh dekat guru. Jika lari tidak sesuai, catat berjalan sebagai penyesuaian; jika nadi belum dirasa, bantu ketika berhenti tanpa memaksa kiraan."}, {"kind": "h3", "text": "Pembina"}, {"kind": "p", "text": "Murid berlatih berpasangan dan melakukan sendiri."}, {"kind": "p", "text": "Tugasan: Menunjukkan urutan langkah perlahan dan regangan secara bergilir dengan pasangan."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Ruang pasangan dalam sempadan kon"}, {"kind": "p", "text": "2. Jam randik guru"}, {"kind": "p", "text": "3. Botol air sendiri"}, {"kind": "p", "text": "4. Buku teks halaman 46–47"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan beza jalan biasa dengan jalan perlahan melalui contoh selamat. Guru memberi peringatan supaya tumit belakang kekal di lantai semasa regangan betis."}, {"kind": "p", "text": "2. Guru membantu murid merasai nadi hanya selepas berhenti dan mendengar jawapan setiap orang. Guru memberi kata mula “Pemanasan untuk…” dan “Penyejukan untuk…” serta membantu menyebut tiga waktu air."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Sebelum bergerak, semak pakaian, kasut dan ruang; minum jika perlu. Berhenti, cari nadi awal 30 saat dan rasa 30 saat dengan dua jari pada pergelangan tangan. Lakukan pemanasan jalan, lari perlahan serta regangan dan sebut tujuannya untuk bersedia."}, {"kind": "p", "text": "2. Semasa latihan, berjalan dan lari perlahan mengikut keselesaan. Berhenti untuk mencari nadi 30 saat dan merasainya 30 saat sebelum penyejukan. Beritahu rasa panas badan serta nafas, kemudian perlahankan langkah dan regang tangan serta betis."}, {"kind": "p", "text": "3. Berhenti selepas latihan penyejukan untuk mencari nadi 30 saat dan rasa 30 saat. Semasa rehat, minum, periksa kasut dan maklumkan jika tidak selesa. Sebut keperluan air sebelum, semasa dan selepas. Pada giliran sendiri, tunjuk urutan penyejukan kepada guru."}, {"kind": "p", "text": "4. Selepas aktiviti, lakukan penyejukan akhir; sebut tujuannya untuk membantu badan kembali tenang. Berhenti, cari nadi 30 saat dan rasa 30 saat. Minum selepas, periksa keadaan diri dan kemas botol; beritahu gerakan yang disukai jika mahu."}, {"kind": "p", "text": "Contoh guru: Tunjukkan cara menyejukkan badan. Apakah tujuan pemanasan sebelum kita bergerak?"}, {"kind": "p", "text": "Contoh respons murid: Murid berjalan perlahan dan regang, kemudian berkata “Pemanasan menyediakan badan. Penyejukan membantu badan kembali tenang.”"}, {"kind": "p", "text": "Hasil individu: Urutan penyejukan setiap murid dan jawapan individu tentang contoh, tujuan serta air; laporan nadi/nafas tidak ditentukan awal."}, {"kind": "p", "text": "Kriteria: Murid mengurangkan kelajuan langkah dan melakukan regangan lembut dengan selamat. Kedua-dua contoh serta tujuan rutin, air dan persediaan sebelum/semasa/selepas diperiksa; perubahan nadi tertentu tidak diwajibkan."}, {"kind": "p", "text": "Susulan: Ulang bahagian regangan yang belum selesa dengan julat kecil. Murid yang memerlukan rehat tidak dipaksa mengulang demi melengkapkan bukti pada hari yang sama."}, {"kind": "h3", "text": "Pencabar"}, {"kind": "p", "text": "Murid memperkemas satu perkara dalam kemahiran yang sama."}, {"kind": "p", "text": "Tugasan: Memperkemas langkah yang semakin perlahan dan regangan lembut dalam urutan yang sama."}, {"kind": "label", "text": "Alatan"}, {"kind": "p", "text": "1. Ruang sendiri dengan kon di luar pijakan"}, {"kind": "p", "text": "2. Jam randik guru"}, {"kind": "p", "text": "3. Botol air sendiri"}, {"kind": "p", "text": "4. Buku teks halaman 46–47"}, {"kind": "label", "text": "Tindakan guru"}, {"kind": "p", "text": "1. Guru menunjukkan langkah pendek dengan ayunan tangan santai, kemudian regangan tanpa henjutan. Guru memberi satu maklum balas tentang kawalan, bukan meminta regangan lebih jauh."}, {"kind": "p", "text": "2. Guru menyokong semakan nadi selepas berhenti dan menerima laporan sebenar. Guru mengulang tujuan pemanasan/penyejukan serta sebelum, semasa dan selepas jika murid terlupa."}, {"kind": "label", "text": "Langkah murid"}, {"kind": "p", "text": "1. Sebelum aktiviti, periksa kasut, pakaian dan ruang; sediakan botol serta minum jika perlu. Berhenti, cari nadi awal 30 saat dan rasa 30 saat dengan dua jari di pergelangan tangan. Lakukan pemanasan jalan, lari perlahan dan regangan untuk menyediakan badan."}, {"kind": "p", "text": "2. Semasa latihan, bergerak ringan dahulu. Berhenti untuk mencari nadi sebelum penyejukan selama 30 saat dan rasa 30 saat; beritahu rasa panas badan dan nafas. Perlahankan langkah dengan terkawal, kemudian regang tangan dan betis tanpa henjutan."}, {"kind": "p", "text": "3. Selepas latihan penyejukan, berhenti, cari nadi 30 saat dan rasa 30 saat. Dalam rehat semasa aktiviti, minum, semak kasut dan keadaan diri serta sebut air diperlukan sebelum, semasa dan selepas. Tunjuk urutan penyejukan sendiri pada giliran dengan kelajuan yang selesa."}, {"kind": "p", "text": "4. Selepas aktiviti, lakukan penyejukan akhir dan nyatakan contoh serta tujuannya membantu badan kembali tenang. Berhenti, cari nadi 30 saat dan rasa 30 saat; minum selepas dan kemas botol. Laporkan keadaan diri serta kongsi rasa seronok jika benar-benar dirasai."}, {"kind": "p", "text": "Contoh guru: Boleh perlahankan langkah tanpa menghampiri rakan? Bagaimana badan kamu rasa selepas berhenti?"}, {"kind": "p", "text": "Contoh respons murid: Murid menunjukkan langkah terkawal dan menjawab berdasarkan pengalaman sendiri, termasuk “Saya belum rasa beza”."}, {"kind": "p", "text": "Hasil individu: Penyejukan individu dengan kawalan langkah dan regangan, diikuti jawapan mudah dan laporan keadaan badan sendiri."}, {"kind": "p", "text": "Kriteria: Murid memperkemas kawalan dalam aktiviti penyejukan yang sama, bukan memanjangkan masa atau menambah kelajuan. Semakan tetap merangkumi pemanasan, tujuan kedua-dua rutin dan air/persediaan sebelum/semasa/selepas."}, {"kind": "p", "text": "Susulan: Kekalkan satu sasaran kecil, iaitu langkah yang santai atau regangan tanpa henjutan. Bantuan guru masih tersedia dan rehat dicatat tanpa hukuman."}, {"kind": "h2", "text": "F. Pentaksiran Bilik Darjah"}, {"kind": "h3", "text": "PBD utama — SP 3.1.2"}, {"kind": "p", "text": "Kaedah: Pemerhatian individu pada latihan minit 13–16, giliran A 21–23 atau B 23–25, dan penyejukan akhir 26–28."}, {"kind": "p", "text": "Bukti: Lakuan berjalan perlahan serta regangan tangan dan betis yang lembut. Laporan nadi/pernafasan ketika berhenti sebelum dan selepas penyejukan: minit 12–13 dan 16–17, kemudian 20–21 dan 28–29."}, {"kind": "p", "text": "Kriteria: Murid melakukan penyejukan selepas aktiviti dengan langkah perlahan dan regangan selesa. Tidak diwajibkan nadi atau pernafasan menunjukkan penurunan tertentu; guru menilai lakuan, bukan mereka perubahan tubuh."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama: ____; berjalan perlahan: ____; regangan lembut: ____; waktu dilihat: ____."}, {"kind": "p", "text": "2. Nadi/nafas yang dilaporkan: ____; bantuan atau rehat: ____; belum diperhatikan: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 3.1.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian lakuan individu semasa pemanasan minit 2–6 dan aktiviti ringan 10–12."}, {"kind": "p", "text": "Bukti: Berjalan, percubaan lari perlahan dan regangan setiap murid; laporan rasa panas badan, nafas serta nadi pada minit 6–7 selepas berhenti."}, {"kind": "p", "text": "Kriteria: Murid melakukan gerakan pemanasan yang boleh menyediakan badan. Lari yang diganti dengan berjalan dan bantuan regangan dicatat tepat; tidak wajib melaporkan peningkatan nadi."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama: ____; berjalan: ____; lari perlahan/penyesuaian: ____; regangan: ____; bantuan: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 4.1.1"}, {"kind": "p", "text": "Kaedah: Soal jawab individu semasa rehat minit 9–10, 18–19 atau 25–26."}, {"kind": "p", "text": "Bukti: Murid menyebut satu aktiviti pemanasan dan satu aktiviti penyejukan yang dilakukan sendiri."}, {"kind": "p", "text": "Kriteria: Murid mengenal kedua-dua rutin, contohnya lari perlahan sebelum aktiviti dan berjalan perlahan selepasnya. Pilihan jawapan lisan dibenarkan dan dicatat."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama: ____; contoh pemanasan: ____; contoh penyejukan: ____; bantuan: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 4.1.2"}, {"kind": "p", "text": "Kaedah: Soalan pendek berasingan tentang tujuan pemanasan dan penyejukan pada minit 9–10, 18–19, 25–26 atau 29–30."}, {"kind": "p", "text": "Bukti: Jawapan murid sendiri seperti “Supaya bersedia bergerak” dan “Supaya badan kembali tenang”."}, {"kind": "p", "text": "Kriteria: Murid mengenal tujuan kedua-dua rutin melalui ayat mudah atau pilihan lisan. Tidak perlu menerangkan mekanisme tubuh dengan panjang."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama: ____; tujuan pemanasan: ____; tujuan penyejukan: ____; bantuan/contoh semula: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 4.1.3"}, {"kind": "p", "text": "Kaedah: Soal jawab individu dalam rehat minum 9–10 dan 17–18 serta penutup 29–30; minta murid melengkapkan semua waktu air diperlukan."}, {"kind": "p", "text": "Bukti: Sebutannya sendiri “sebelum, semasa dan selepas aktiviti”; guru menyemak setiap bahagian, bukan sekadar melihat botol digunakan."}, {"kind": "p", "text": "Kriteria: Murid menyatakan ketiga-tiga waktu air diperlukan. Tiada kuota minuman atau syarat menghabiskan air."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama: ____; sebelum: ____; semasa: ____; selepas: ____; bantuan atau belum menjawab: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 5.1.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian persediaan diri individu sebelum pada 0–2, semasa pada 17–18 dan selepas pada 29–30."}, {"kind": "p", "text": "Bukti: Sebelum: periksa pakaian/kasut, sediakan air dan maklumkan keadaan diri. Semasa: jaga jarak, semak kasut bila perlu, minum/rehat mengikut keperluan dan beritahu guru jika tidak selesa. Selepas: lakukan penyejukan, periksa keadaan diri, mendapat peluang minum dan kemas botol."}, {"kind": "p", "text": "Kriteria: Guru merekod penjagaan diri sebelum, semasa dan selepas secara berasingan. Permintaan bantuan atau rehat diterima sebagai usaha menjaga diri."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama: ____; sebelum: ____; semasa: ____; selepas: ____; bantuan/keperluan tubuh: ____."}, {"kind": "h3", "text": "PBD sokongan — SP 5.2.1"}, {"kind": "p", "text": "Kaedah: Pemerhatian respons individu semasa latihan dan pertanyaan sukarela pada minit 18–19 atau 29–30."}, {"kind": "p", "text": "Bukti: Kata atau isyarat sebenar murid tentang gerakan baharu yang disukai atau minat mencuba lagi bersama guru."}, {"kind": "p", "text": "Kriteria: Respons seronok dicatat hanya jika dilihat atau didengar. Murid tidak dipaksa tersenyum, bersorak atau terus bergerak ketika memerlukan rehat."}, {"kind": "p", "text": "Rekod: Guru mencatat perkara yang benar-benar dilihat atau didengar. Bantuan dan giliran yang belum selesai dicatat; keputusan tidak diisi sebelum PdP."}, {"kind": "label", "text": "Senarai semak"}, {"kind": "p", "text": "1. Nama: ____; kata/isyarat sebenar: ____; bantuan/keadaan diri: ____; belum diperhatikan: ____."}, {"kind": "h2", "text": "G. Refleksi dan intervensi"}, {"kind": "p", "text": "Murid yang telah diperhatikan: ____ daripada ____. Kemahiran yang dikuasai: __________. Murid yang masih memerlukan bimbingan atau belum mendapat giliran: __________."}, {"kind": "label", "text": "Intervensi"}, {"kind": "p", "text": "1. Jika murid belum dapat memperlahankan gerakan, guru berjalan di hadapannya dalam ruang selamat sambil memberi arahan pendek. Regangan dibuat dengan julat kecil."}, {"kind": "p", "text": "2. Berjalan menggantikan lari dibenarkan dan direkod sebagai penyesuaian. Rehat atau ketidakselesaan tidak dianggap sikap negatif."}, {"kind": "p", "text": "3. Jika nadi belum dirasa, beri bantuan semasa berhenti atau gunakan tapak tangan di dada untuk merasai degupan. Jangan memaksa kiraan atau perubahan."}, {"kind": "p", "text": "4. Gunakan contoh lisan berulang bagi tujuan kedua-dua rutin dan air sebelum, semasa serta selepas. Catat jawapan atau giliran yang belum lengkap untuk bimbingan seterusnya."}]'::jsonb,'{"source_hold": "", "adaptation_note": "Pemanasan, penyejukan dan air sebelum, semasa serta selepas diajar. Nadi diperhatikan pada pergelangan tangan ketika berhenti; tiada sasaran denyut, kiraan bpm wajib atau jawapan peningkatan direka. Keperluan air Tahun1 tidak sama dengan standard kuantiti Tahun3.", "source_images_verified": true, "audio_verified": false, "ba_verified": false, "classroom_trial_performed": false}'::jsonb)
